from flask import Flask, render_template, request, jsonify, send_file
import openai
import os

app = Flask(__name__)
openai.api_key = os.getenv("OPENAI_API_KEY")  # 确保设置环境变量

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/expand', methods=['POST'])
def expand_content():
    data = request.json
    outline = data['outline']
    character = data['character']
    plot = data['plot']

    # 调用ChatGPT API扩写内容
    expanded_outline = openai.Completion.create(
        engine="gpt-4",
        prompt=f"Expand the outline: {outline}",
        max_tokens=200
    ).choices[0].text.strip()

    expanded_character = openai.Completion.create(
        engine="gpt-4",
        prompt=f"Expand the character: {character}",
        max_tokens=200
    ).choices[0].text.strip()

    expanded_plot = openai.Completion.create(
        engine="gpt-4",
        prompt=f"Expand the plot: {plot}",
        max_tokens=200
    ).choices[0].text.strip()

    return jsonify({
        "expanded_outline": expanded_outline,
        "expanded_character": expanded_character,
        "expanded_plot": expanded_plot
    })

@app.route('/generate_chapter', methods=['POST'])
def generate_chapter():
    data = request.json
    outline = data['outline']
    character = data['character']
    plot = data['plot']
    style = data['style']
    chapter = data['chapter']

    # 调用ChatGPT API生成章节
    prompt = f"Write a chapter in {style} style based on the following:\nOutline: {outline}\nCharacter: {character}\nPlot: {plot}"
    chapter_text = openai.Completion.create(
        engine="gpt-4",
        prompt=prompt,
        max_tokens=500
    ).choices[0].text.strip()

    return jsonify({"chapter": chapter_text})

@app.route('/save_chapter', methods=['POST'])
def save_chapter():
    data = request.json
    chapter_text = data['chapter']
    with open('chapter.txt', 'w') as f:
        f.write(chapter_text)
    return send_file('chapter.txt', as_attachment=True)

if __name__ == '__main__':
    app.run(debug=True)
```

