require("dotenv").config();
const express = require("express");
const mongoose = require("mongoose");
const shortid = require("shortid");
const multer = require("multer");
const path = require("path");
const ejs = require("ejs");

const app = express();
const PORT = process.env.PORT || 3000;

// MongoDB Connection
mongoose.connect(process.env.MONGO_URI, {
  useNewUrlParser: true,
  useUnifiedTopology: true,
});

// Image Storage Setup
const storage = multer.diskStorage({
  destination: (req, file, cb) => {
    cb(null, "public/uploads/");
  },
  filename: (req, file, cb) => {
    cb(null, Date.now() + path.extname(file.originalname));
  },
});

const upload = multer({ storage: storage });

// MongoDB Schema for Image Metadata
const Image = mongoose.model("Image", {
  originalname: String,
  shortUrl: String,
});

// Middleware
app.set("view engine", "ejs");
app.use(express.static("public"));
app.use(express.urlencoded({ extended: true }));

// Routes
app.get("/", (req, res) => {
  res.render("index");
});

app.post("/upload", upload.single("image"), async (req, res) => {
  try {
    const shortUrl = shortid.generate();
    const image = new Image({
      originalname: req.file.originalname,
      shortUrl: shortUrl,
    });
    await image.save();
    res.render("index", { shortUrl: `${req.headers.origin}/${shortUrl}` });
  } catch (error) {
    res.status(500).send("Error uploading image.");
  }
});

app.get("/:shortUrl", async (req, res) => {
  try {
    const image = await Image.findOne({ shortUrl: req.params.shortUrl });
    if (image) {
      const imagePath = path.join(__dirname, "public/uploads", req.file.filename);
      res.sendFile(imagePath);
    } else {
      res.status(404).send("Image not found.");
    }
  } catch (error) {
    res.status(500).send("Error retrieving image.");
  }
});

app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});
```

