```cpp
// Включаем библиотеки, необходимые для работы с датчиком температуры DS18B20 и радиомодулем HC-12
#include <OneWire.h>
#include <DallasTemperature.h>

// Определяем номераピンов
#define ONE_WIRE_BUS 2          // Пин, к которому подключен датчик температуры DS18B20
#define DIGITAL_INPUT_PIN 3     // Пин, к которому подключен цифровой вход
#define HC12_TX 4               // Пин TX радиомодуля HC-12 (подключен к RX Arduino)
#define HC12_RX 5               // Пин RX радиомодуля HC-12 (подключен к TX Arduino)

// Инициализируем датчик температуры
OneWire oneWire(ONE_WIRE_BUS);
DallasTemperature sensors(&oneWire);

// Переменные для хранения данных
float temperature = 0.0;        // Переменная для хранения показаний температуры
int digitalInputState = 0;      // Переменная для хранения состояния цифрового входа

void setup() {
  // Начинаем сериальный порт для отладки и связи с HC-12
  Serial.begin(9600);
  while (!Serial); // Ждем, пока сериальный порт не будет готов (необходимо для некоторых плат)

  // Начинаем работу с датчиком температуры
  sensors.begin();

  // Настраиваем пин цифрового входа как вход
  pinMode(DIGITAL_INPUT_PIN, INPUT);

  // Инициализируем радиомодуль HC-12
  Serial.begin(9600, SERIAL_8N1, HC12_RX, HC12_TX); // Используем HardwareSerial для HC-12
}

void loop() {
  // Читаем показания температуры
  sensors.requestTemperatures(); // Отправляем запрос на измерение температуры
  temperature = sensors.getTempCByIndex(0); // Получаем температуру в градусах Цельсия

  // Читаем состояние цифрового входа
  digitalInputState = digitalRead(DIGITAL_INPUT_PIN);

  // Формируем строку для передачи через радиоканал
  String dataToSend = "Temp:" + String(temperature) + ",State:" + String(digitalInputState);

  // Отправляем данные через радиомодуль HC-12
  Serial.println(dataToSend);

  // Ждем 5 секунд перед следующей передачей данных
  delay(5000);
}
```

### Подробные комментарии:

1. **Включение библиотек**:
   - `#include <OneWire.h>` и `#include <DallasTemperature.h>` - библиотеки для работы с датчиком температуры DS18B20.

2. **Определение пинов**:
   - `ONE_WIRE_BUS` - пин, к которому подключен датчик температуры.
   - `DIGITAL_INPUT_PIN` - пин, к которому подключен цифровой вход.
   - `HC12_TX` и `HC12_RX` - пины для связи с радиомодулем HC-12.

3. **Инициализация датчика температуры**:
   - `OneWire oneWire(ONE_WIRE_BUS);` - создает объект для работы с протоколом OneWire.
   - `DallasTemperature sensors(&oneWire);` - создает объект для работы с датчиком температуры.

4. **Функция `setup()`**:
   - `Serial.begin(9600);` - инициализирует сериальный порт для отладки.
   - `sensors.begin();` - начинает работу с датчиком температуры.
   - `pinMode(DIGITAL_INPUT_PIN, INPUT);` - настраивает пин цифрового входа как вход.
   - `Serial.begin(9600, SERIAL_8N1, HC12_RX, HC12_TX);` - инициализирует HardwareSerial для связи с HC-12.

5. **Функция `loop()`**:
   - `sensors.requestTemperatures();` - отправляет запрос на измерение температуры.
   - `temperature = sensors.getTempCByIndex(0);` - получает температуру в градусах Цельсия.
   - `digitalInputState = digitalRead(DIGITAL_INPUT_PIN);` - читает состояние цифрового входа.
   - `String dataToSend = "Temp:" + String(temperature) + ",State:" + String(digitalInputState);` - формирует строку с данными для передачи.
   - `Serial.println(dataToSend);` - отправляет данные через радиомодуль HC-12.
   - `delay(5000);` - ждет 5 секунд перед следующей передачей данных.

Этот код обеспечивает чтение показаний датчика температуры и состояния цифрового входа, а также передачу этих данных через радиомодуль HC-12. Следующим этапом будет написание кода для Orange Pi Zero, который будет принимать эти данные и отображать их на веб-странице.

