import random
import time

class HalfLifeMiniGame:
    def __init__(self):
        self.player_health = 100
        self.hev_suit_enabled = True
        self.headcrabs_encountered = 0
        self.gman_encounters = 0
        self.locations = ["Sector A", "Sector B", "Sector C", "Surface"]
        self.current_location = self.locations[0]

