        status = f"""
        ==== Black Mesa Incident ====
        Location: {self.current_location}
        Health: {self.player_health}
        HEV Suit: {'Enabled' if self.hev_suit_enabled else 'Disabled'}
        Headcrabs Encountered: {self.headcrabs_encountered}
        G-Man Encounters: {self.gman_encounters}
        """
        print(status)

    def encounter_headcrab(self):
        print("\nA headcrab jumps out of the shadows!")
        time.sleep(1)
        if random.random() < 0.3 and self.hev_suit_enabled:
            print("Your HEV Suit protects you from the headcrab's attack!")
        else:
            damage = random.randint(10, 25)
            self.player_health -= damage
            print(f"The headcrab damages you for {damage} HP!")
        self.headcrabs_encountered += 1

    def encounter_gman(self):
        print("\nThe G-Man appears, watching you silently...")
        time.sleep(2)
        print('"The right man in the wrong place can make all the difference."')
        self.gman_encounters += 1

    def move(self, direction):
        if direction == "forward" and self.locations.index(self.current_location) < len(self.locations) - 1:
            self.current_location = self.locations[self.locations.index(self.current_location) + 1]
            print(f"\nYou move to {self.current_location}.")
            if random.random() < 0.5:
                self.encounter_headcrab()
            if random.random() < 0.2:
                self.encounter_gman()
        elif direction == "back" and self.locations.index(self.current_location) > 0:
            self.current_location = self.locations[self.locations.index(self.current_location) - 1]
            print(f"\nYou move back to {self.current_location}.")
        else:
            print("\nYou can't go that way!")

    def play(self):
        print("Welcome to the Black Mesa Incident Mini-Game!\n")
        print("You are a scientist trying to escape the facility. Move forward to reach the surface, but beware of headcrabs!")
        while self.player_health > 0 and self.current_location != self.locations[-1]:
            self.print_status()
            action = input("\nWhat do you do? (forward/back/quit): ").strip().lower()
            if action == "quit":
                print("You gave up. The facility claims another victim.")
                break
            elif action in ["forward", "back"]:
                self.move(action)
            else:
                print("Invalid action. Try again.")

        if self.player_health <= 0:
            print("\nYou have been overwhelmed by headcrabs. Game over.")
        elif self.current_location == self.locations[-1]:
            print("\nYou reach the surface! The Black Mesa Incident is behind you... for now.")
            if self.gman_encounters > 0:
