```javascript
// cloudfunctions/transferPoints/index.js
const cloud = require('wx-server-sdk');
cloud.init();
const db = cloud.database();

exports.main = async (event, context) => {
  const { fromOpenid, toOpenid, amount } = event;

  try {
    // 检查转出用户积分是否足够
    const fromUser = await db.collection('users').doc(fromOpenid).get();
    if (fromUser.data.points < amount) {
      return { success: false, message: '积分不足' };
    }

    // 原子操作：转出和转入
    await db.collection('users').doc(fromOpenid).update({
      data: {
        points: _.inc(-amount)
      }
    });

    await db.collection('users').doc(toOpenid).update({
      data: {
        points: _.inc(amount)
      }
    });

    return { success: true, message: '转账成功' };
  } catch (error) {
    return { success: false, message: '转账失败' };
  }
};
```

