Voici un exemple de script Python Flask qui répond à vos exigences. Ce script copie tous les fichiers `.mp4` d'un répertoire spécifié vers une clé USB montée sur `/media/usb`, et affiche une page web avec un bouton pour lancer la copie et une barre de progression dynamique.

### Prérequis :
1. Assurez-vous que Flask est installé (`pip install flask`).
2. La clé USB doit être montée sur `/media/usb`.
3. Le répertoire source des fichiers `.mp4` doit être accessible.

### Script Python (`app.py`) :

```python
from flask import Flask, render_template, jsonify, request
import os
import shutil
import threading

app = Flask(__name__)

# Configuration
SOURCE_DIR = '/chemin/vers/repertoire/source'  # Remplacez par le chemin de votre répertoire source
DEST_DIR = '/media/usb'

# Variables globales pour la progression
total_files = 0
copied_files = 0
lock = threading.Lock()
copy_in_progress = False

def copy_mp4_files():
    global total_files, copied_files, copy_in_progress
    copy_in_progress = True
    total_files = 0
    copied_files = 0

    # Compter le nombre total de fichiers mp4
    for root, _, files in os.walk(SOURCE_DIR):
        for file in files:
            if file.endswith('.mp4'):
                total_files += 1

    # Copier les fichiers
    for root, _, files in os.walk(SOURCE_DIR):
        for file in files:
            if file.endswith('.mp4'):
                src_path = os.path.join(root, file)
                dest_path = os.path.join(DEST_DIR, file)
                try:
                    shutil.copy2(src_path, dest_path)
                    with lock:
                        copied_files += 1
                except Exception as e:
                    print(f"Erreur lors de la copie de {src_path}: {e}")

    copy_in_progress = False

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/start_copy', methods=['POST'])
def start_copy():
    global copy_in_progress
    if not copy_in_progress:
        threading.Thread(target=copy_mp4_files).start()
        return jsonify({'status': 'started'})
    else:
        return jsonify({'status': 'already_running'}), 400

@app.route('/progress')
def progress():
    global total_files, copied_files
    if total_files == 0:
        return jsonify({'progress': 0})
    progress_percent = (copied_files / total_files) * 100
    return jsonify({'progress': progress_percent})

if __name__ == '__main__':
    app.run(debug=True)
```

