Ниже приведен пример кода на C++, который позволяет вручную вводить ориентированный граф. Этот код использует структуру данных `std::map` для хранения списка смежности графа.

```cpp
#include <iostream>
#include <map>
#include <vector>
#include <string>

// Структура для представления ориентированного графа
class DirectedGraph {
private:
    std::map<std::string, std::vector<std::string>> adjacencyList;

public:
    // Добавление вершины в граф
    void addVertex(const std::string& vertex) {
        if (adjacencyList.find(vertex) == adjacencyList.end()) {
            adjacencyList[vertex] = {};
        }
    }

    // Добавление ребра в граф
    void addEdge(const std::string& from, const std::string& to) {
        if (adjacencyList.find(from) != adjacencyList.end() &&
            adjacencyList.find(to) != adjacencyList.end()) {
            adjacencyList[from].push_back(to);
        } else {
            std::cerr << "Одна или обе вершины не существуют в графе." << std::endl;
        }
    }

    // Печать графа
    void printGraph() const {
        for (const auto& pair : adjacencyList) {
            std::cout << pair.first << " -> ";
            for (const auto& neighbor : pair.second) {
                std::cout << neighbor << " ";
            }
            std::cout << std::endl;
        }
