```c
#include <stdio.h>
#include <stdlib.h>

// 定义链表节点结构体
typedef struct ListNode {
    int val;
    struct ListNode *next;
} ListNode;

// 创建新节点
ListNode* createNode(int val) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (newNode == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    newNode->val = val;
    newNode->next = NULL;
    return newNode;
}

// 合并两个升序链表
ListNode* mergeTwoLists(ListNode* l1, ListNode* l2) {
    ListNode dummy = {0}; // 虚拟头节点
    ListNode* current = &dummy;

    while (l1 != NULL && l2 != NULL) {
        if (l1->val <= l2->val) {
            current->next = l1;
            l1 = l1->next;
        } else {
            current->next = l2;
            l2 = l2->next;
        }
        current = current->next;
    }

    // 将剩余的节点直接连接到结果链表上
    if (l1 != NULL) {
        current->next = l1;
    } else {
        current->next = l2;
    }

    return dummy.next; // 返回合并后的链表头节点
}

// 释放链表内存
void freeList(ListNode* head) {
    while (head != NULL) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

// 打印链表
void printList(ListNode* head) {
    while (head != NULL) {
        printf("%d -> ", head->val);
        head = head->next;
    }
    printf("NULL\n");
}

int main() {
    // 创建第一个链表: 1 -> 2 -> 4
    ListNode* l1 = createNode(1);
    l1->next = createNode(2);
    l1->next->next = createNode(4);

    // 创建第二个链表: 1 -> 3 -> 4
    ListNode* l2 = createNode(1);
    l2->next = createNode(3);
    l2->next->next = createNode(4);

    // 合并链表
    ListNode* mergedList = mergeTwoLists(l1, l2);

    // 打印合并后的链表
    printList(mergedList);

    // 释放内存
    freeList(mergedList);

    return 0;
}
```

### 安全性考虑：
1. **内存分配失败处理**：在`createNode`函数中，检查`malloc`是否返回`NULL`，如果是，则输出错误信息并退出程序。
2. **空指针检查**：在`mergeTwoLists`函数中，确保`l1`和`l2`不为`NULL`时才进行操作，避免空指针引用。
3. **内存泄漏**：在`main`函数结束时，调用`freeList`函数释放所有分配的内存，防止内存泄漏。

### 代码功能：
- `createNode`：创建一个新的链表节点。
