### Реализация на C с использованием mjson:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "mjson.h"

#define NUM_BUTTONS 6
#define NUM_RELAYS 6

typedef struct {
    int buttons[NUM_BUTTONS];
    int relays[NUM_RELAYS];
    int** mapping; // Двумерный массив для хранения цепочек
} Controller;

void init_controller(Controller* ctrl, const char* json_str) {
    mjson_token_t const tokens[128];
    mjson_err_t err = mjson_parse(json_str, json_str + strlen(json_str), tokens, 128);
    if (err) {
        printf("JSON parse error: %d\n", err);
        exit(1);
    }

    mjson_token_t const* arr = mjson_get(tokens, "$");
    if (arr->type != MJSON_ARRAY) {
        printf("Root is not an array\n");
        exit(1);
    }

    ctrl->mapping = (int**)malloc(NUM_BUTTONS * sizeof(int*));
    for (int i = 0; i < NUM_BUTTONS; i++) {
        ctrl->mapping[i] = (int*)malloc(NUM_RELAYS * sizeof(int));
        memset(ctrl->mapping[i], -1, NUM_RELAYS * sizeof(int));
    }

    for (int i = 0; i < arr->size; i++) {
        mjson_token_t const* obj = mjson_get_idx(tokens, arr, i);
        int button = mjson_get_number(tokens, obj, "button", -1);
        mjson_token_t const* chain = mjson_get(tokens, obj, "chain");

        if (button < 0 || button >= NUM_BUTTONS || chain->type != MJSON_ARRAY) {
            continue;
        }

        int relay_idx = 0;
        for (int j = 0; j < chain->size; j++) {
            int relay = mjson_get_idx_number(tokens, chain, j, -1);
            if (relay >= 0 && relay < NUM_RELAYS && relay_idx < NUM_RELAYS) {
                ctrl->mapping[button][relay_idx++] = relay;
            }
        }
        ctrl->mapping[button][relay_idx] = -1; // Окончание цепочки
    }

    memset(ctrl->buttons, 0, NUM_BUTTONS * sizeof(int));
    memset(ctrl->relays, 0, NUM_RELAYS * sizeof(int));
}

void process_button(Controller* ctrl, int button) {
    if (button < 0 || button >= NUM_BUTTONS || ctrl->buttons[button] == 0) {
        return;
    }

    int* chain = ctrl->mapping[button];
    for (int i = 0; chain[i] != -1; i++) {
        int relay = chain[i];
        ctrl->relays[relay] = !ctrl->relays[relay]; // Переключение реле
    }
}

void update_controller(Controller* ctrl) {
    for (int i = 0; i < NUM_BUTTONS; i++) {
        if (ctrl->buttons[i] == 1) {
            process_button(ctrl, i);
            ctrl->buttons[i] = 0; // Сброс состояния кнопки после обработки
        }
    }
}

int main() {
    Controller ctrl;
    const char* json_str = "[{\"button\": 0, \"chain\": [1, 3]}, {\"button\": 1, \"chain\": [2, 4, 5]}]";

    init_controller(&ctrl, json_str);

    // Симуляция работы
    ctrl.buttons[0] = 1; // Кнопка 0 нажата
    update_controller(&ctrl);

    for (int i = 0; i < NUM_RELAYS; i++) {
        printf("Relay %d: %d\n", i, ctrl.relays[i]);
    }

    // Освобождение памяти
    for (int i = 0; i < NUM_BUTTONS; i++) {
        free(ctrl.mapping[i]);
    }
    free(ctrl.mapping);

    return 0;
