下面是一个用C语言实现的简单银行家算法模拟操作系统资源分配的示例代码。该代码实现了题目中描述的功能，包括进程调度、资源分配、银行家算法避免死锁以及状态输出。

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_PROCESSES 5
#define MAX_RESOURCES 3
#define TIME_SLICE 1

typedef enum { W, R, B, F } ProcessState;

typedef struct {
    char name[10];
    int max_resources[MAX_RESOURCES];
    int allocated_resources[MAX_RESOURCES];
    int need_resources[MAX_RESOURCES];
    ProcessState state;
} PCB;

int available[MAX_RESOURCES] = {10, 15, 8}; // A, B, C
PCB processes[MAX_PROCESSES];
int current_process = -1;
int completed_count = 0;

void initialize_processes() {
    const char* names[] = {"P1", "P2", "P3", "P4", "P5"};
    int max_resources[][MAX_RESOURCES] = {
        {7, 5, 3},
        {3, 2, 2},
        {9, 0, 2},
        {2, 2, 2},
        {4, 3, 3}
    };

    for (int i = 0; i < MAX_PROCESSES; i++) {
        strcpy(processes[i].name, names[i]);
        memcpy(processes[i].max_resources, max_resources[i], sizeof(int) * MAX_RESOURCES);
        memset(processes[i].allocated_resources, 0, sizeof(int) * MAX_RESOURCES);
        for (int j = 0; j < MAX_RESOURCES; j++) {
            processes[i].need_resources[j] = processes[i].max_resources[j];
        }
        processes[i].state = W;
    }
}

int is_safe_state(int request[], int process_id) {
    int work[MAX_RESOURCES];
    memcpy(work, available, sizeof(int) * MAX_RESOURCES);

    PCB finish[MAX_PROCESSES];
    int finish_count = 0;

    for (int i = 0; i < MAX_PROCESSES; i++) {
        finish[i] = processes[i];
    }

    while (1) {
        int found = -1;
        for (int i = 0; i < MAX_PROCESSES; i++) {
            if (finish[i].state == W) {
                int can_allocate = 1;
                for (int j = 0; j < MAX_RESOURCES; j++) {
                    if (finish[i].need_resources[j] > work[j]) {
                        can_allocate = 0;
                        break;
                    }
                }
                if (can_allocate) {
                    found = i;
                    break;
                }
            }
        }
        if (found == -1) break;

        finish[found].state = F;
        for (int j = 0; j < MAX_RESOURCES; j++) {
            work[j] += finish[found].allocated_resources[j];
        }
        finish_count++;
    }

    if (finish_count < MAX_PROCESSES) return 0;

    for (int i = 0; i < MAX_RESOURCES; i++) {
        available[i] -= request[i];
        processes[process_id].allocated_resources[i] += request[i];
        processes[process_id].need_resources[i] -= request[i];
    }

    return 1;
}

void print_system_state() {
    printf("Current Process: %s\n", current_process == -1 ? "None" : processes[current_process].name);
    printf("Ready Queue: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == W && i != current_process) {
            printf("%s ", processes[i].name);
        }
    }
    printf("\nBlocked Queue: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == B) {
            printf("%s ", processes[i].name);
        }
    }
    printf("\nCompleted Processes: ");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == F) {
            printf("%s ", processes[i].name);
        }
    }
    printf("\nPCB Information:\n");
    for (int i = 0; i < MAX_PROCESSES; i++) {
        printf("Process: %s | Max: [%d, %d, %d] | Allocated: [%d, %d, %d] | Need: [%d, %d, %d] | State: %c\n",
               processes[i].name,
               processes[i].max_resources[0], processes[i].max_resources[1], processes[i].max_resources[2],
               processes[i].allocated_resources[0], processes[i].allocated_resources[1], processes[i].allocated_resources[2],
               processes[i].need_resources[0], processes[i].need_resources[1], processes[i].need_resources[2],
               processes[i].state);
    }
    printf("Available Resources: [%d, %d, %d]\n\n", available[0], available[1], available[2]);
}

void create_new_process() {
    for (int i = 0; i < MAX_PROCESSES; i++) {
        if (processes[i].state == F) {
            strcpy(processes[i].name, "P1"); // 简单起见，完成后重新创建P1
            memcpy(processes[i].max_resources, (int[]){7, 5, 3}, sizeof(int) * MAX_RESOURCES);
            memset(processes[i].allocated_resources, 0, sizeof(int) * MAX_RESOURCES);
            for (int j = 0; j < MAX_RESOURCES; j++) {
                processes[i].need_resources[j] = processes[i].max_resources[j];
            }
            processes[i].state = W;
            break;
        }
    }
}

int main() {
    srand(time(NULL));
    initialize_processes();

    int time = 0;
    while (completed_count < MAX_PROCESSES) {
        if (current_process == -1) {
            for (int i = 0; i < MAX_PROCESSES; i++) {
                if (processes[i].state == W) {
                    current_process = i;
                    processes[i].state = R;
                    break;
                }
            }
        }

        if (current_process != -1) {
            int request[MAX_RESOURCES] = {0, 0, 0};
            for (int j = 0; j < MAX_RESOURCES; j++) {
                if (processes[current_process].need_resources[j] > 0) {
                    request[j] = rand() % (processes[current_process].need_resources[j] + 1);
                }
            }

            if (request[0] == 0 && request[1] == 0 && request[2] == 0) {
                processes[current_process].state = B;
            } else {
                if (is_safe_state(request, current_process)) {
                    printf("Process %s requests [%d, %d, %d] - Granted\n", processes[current_process].name, request[0], request[1], request[2]);
                } else {
                    printf("Process %s requests [%d, %d, %d] - Denied (Blocked)\n", processes[current_process].name, request[0], request[1], request[2]);
                    processes[current_process].state = B;
                }
            }

            time++;
            if (time % TIME_SLICE == 0) {
                processes[current_process].state = W;
                current_process = -1;
            }

            if (processes[current_process].state == B) {
                current_process = -1;
            }

            if (processes[current_process].state == R) {
                int is_finished = 1;
                for (int j = 0; j < MAX_RESOURCES; j++) {
                    if (processes[current_process].need_resources[j] > 0) {
                        is_finished = 0;
                        break;
                    }
                }
                if (is_finished) {
                    processes[current_process].state = F;
                    completed_count++;
                    create_new_process();
                    current_process = -1;
                }
            }
        }

        print_system_state();

        // 检查是否有阻塞进程可以恢复
        for (int i = 0; i < MAX_PROCESSES; i++) {
            if (processes[i].state == B) {
                int can_resume = 1;
                for (int j = 0; j < MAX_RESOURCES; j++) {
                    if (processes[i].need_resources[j] > available[j]) {
                        can_resume = 0;
                        break;
                    }
                }
                if (can_resume) {
                    processes[i].state = W;
                }
            }
        }
    }

    return 0;
}
```

### 代码说明：
1. **初始化**：`initialize_processes()` 初始化所有进程的PCB，包括最大需求、已分配资源和需求资源。
2. **银行家算法**：`is_safe_state()` 检查当前资源分配是否处于安全状态。
3. **调度**：采用时间片轮转调度，每个进程运行一个时间片后切换到就绪状态。
4. **资源请求**：进程在运行时随机请求资源，如果请求被批准，则更新资源分配；否则进程被阻塞。
5. **状态输出**：`print_system_state()` 输出当前系统状态，包括正在运行的进程、就绪队列、阻塞队列、完成队列以及每个进程的PCB信息。
6. **进程完成与创建**：进程完成后释放资源，并随机创建新进程。

### 注意事项：
- 代码中的随机资源请求是简化的，实际应用中可能需要更复杂的逻辑。
- 进程完成后重新创建新进程的逻辑简单，实际中可能需要更复杂的进程管理机制。

这个代码是一个基本的实现，可以根据具体需求进行扩展和优化。

