```c
#include <stdio.h>
#include <math.h>

// Function to calculate the distance between two points (x1, y1) and (x2, y2)
double distance(double x1, double y1, double x2, double y2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

// Function to determine the number of intersection points of two circles
int intersection_points(double x1, double y1, double r1, double x2, double y2, double r2) {
    double d = distance(x1, y1, x2, y2);
    double sum_radii = r1 + r2;
    double diff_radii = fabs(r1 - r2);

    if (d > sum_radii) {
        // Circles are separate
        return 0;
    } else if (d < diff_radii) {
        // One circle is inside the other without touching
        return 0;
    } else if (d == 0 && r1 == r2) {
        // Circles are coincident (infinite intersection points)
        return -1;
    } else if (d == sum_radii || d == diff_radii) {
        // Circles touch at one point (tangent)
        return 1;
    } else {
        // Circles intersect at two points
        return 2;
    }
}

int main() {
    double x1, y1, r1, x2, y2, r2;

    // Input coordinates and radii of the circles
    printf("Enter coordinates of the center of the first circle (x1 y1) and its radius r1: ");
    scanf("%lf %lf %lf", &x1, &y1, &r1);

    printf("Enter coordinates of the center of the second circle (x2 y2) and its radius r2: ");
    scanf("%lf %lf %lf", &x2, &y2, &r2);

    // Determine the number of intersection points
    int result = intersection_points(x1, y1, r1, x2, y2, r2);

    // Output the result
    if (result == -1) {
        printf("The circles are coincident (infinite intersection points).\n");
    } else {
        printf("The circles intersect at %d point(s).\n", result);
    }

    return 0;
}
```

### Explanation:
1. **Distance Calculation**: The `distance` function calculates the Euclidean distance between the centers of the two circles.
2. **Intersection Logic**:
   - If the distance between the centers is greater than the sum of the radii, the circles do not intersect.
   - If the distance is less than the absolute difference of the radii, one circle is inside the other without touching.
   - If the circles are coincident (same center and radius), they have infinite intersection points.
   - If the distance equals the sum or difference of the radii, the circles touch at exactly one point (tangent).
   - Otherwise, the circles intersect at two points.
3. **User Input**: The program prompts the user to input the coordinates of the centers and the radii of both circles.
4. **Output**: The program outputs the number of intersection points based on the calculated conditions.

This program is a robust solution for determining the intersection points of two circles in a 2D plane.

