    int count_array[MAX_SIZE] = {0};  // Array to count occurrences of each number

    // Count occurrences of each number
    for (int i = 0; i < size; i++) {
        if (arr[i] < 0 || arr[i] >= MAX_SIZE) {
            fprintf(stderr, "Warning: Number %d is out of range for counting.\n", arr[i]);
            continue;
        }
        count_array[arr[i]]++;
    }

    // Count how many numbers appear more than once
    *repetitious_count = 0;
    for (int i = 0; i < MAX_SIZE; i++) {
        if (count_array[i] > 1) {
            (*repetitious_count)++;
        }
    }

    return 0;
}

