 * @param chickens 指向鸡的数量的指针
 * @param rabbits 指向兔的数量的指针
 *
 * @return 0 如果问题有解，-1 如果问题无解
 */
int solve_chicken_rabbit_problem(int total_animals, int total_legs, int *chickens, int *rabbits) {
    // 鸡有2条腿，兔有4条腿
    // 我们可以建立如下方程：
    // 2 * chickens + 4 * rabbits = total_legs
    // chickens + rabbits = total_animals

