Voici un programme C qui répond à vos exigences. Ce programme utilise les sockets UDP pour envoyer et recevoir des messages. Il crée deux processus : le processus père envoie périodiquement un message, tandis que le processus fils reçoit les messages et met à jour un tableau partagé (`tb`) avec les adresses IP et les ports des expéditeurs qui envoient le message attendu.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <signal.h>
#include <time.h>

#define PORT 2346
#define MAX_ENTRIES 100
#define MAX_IP_LEN 16

struct Entry {
    char ip[MAX_IP_LEN];
    int port;
};

struct Entry tb[MAX_ENTRIES];
int tb_index = 0;

void handle_sigint(int sig) {
    printf("Arrêt du programme...\n");
    exit(0);
}

void sender(char *message) {
    int sockfd;
    struct sockaddr_in broadcast_addr;

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Erreur lors de la création du socket");
        exit(EXIT_FAILURE);
    }

    int broadcast = 1;
    if (setsockopt(sockfd, SOL_SOCKET, SO_BROADCAST, &broadcast, sizeof(broadcast)) < 0) {
        perror("Erreur lors de la configuration du socket en mode broadcast");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    memset(&broadcast_addr, 0, sizeof(broadcast_addr));
    broadcast_addr.sin_family = AF_INET;
    broadcast_addr.sin_addr.s_addr = INADDR_BROADCAST;
    broadcast_addr.sin_port = htons(PORT);

    while (1) {
        if (sendto(sockfd, message, strlen(message), 0, (struct sockaddr *)&broadcast_addr, sizeof(broadcast_addr)) < 0) {
            perror("Erreur lors de l'envoi du message");
        }
        sleep(1);

        // Affichage du tableau toutes les 30 secondes
        static time_t last_display = 0;
        time_t now = time(NULL);
        if (now - last_display >= 30) {
            printf("Tableau tb:\n");
            for (int i = 0; i < tb_index; i++) {
                printf("IP: %s, Port: %d\n", tb[i].ip, tb[i].port);
            }
            last_display = now;
        }
    }

    close(sockfd);
}

void receiver(char *expected_message) {
    int sockfd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t addr_len = sizeof(client_addr);
    char buffer[256];

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Erreur lors de la création du socket");
        exit(EXIT_FAILURE);
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(PORT);

    if (bind(sockfd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Erreur lors du bind");
        close(sockfd);
        exit(EXIT_FAILURE);
    }

    while (1) {
        memset(buffer, 0, sizeof(buffer));
        if (recvfrom(sockfd, buffer, sizeof(buffer), 0, (struct sockaddr *)&client_addr, &addr_len) < 0) {
            perror("Erreur lors de la réception du message");
            continue;
        }

        if (strcmp(buffer, expected_message) == 0) {
            if (tb_index < MAX_ENTRIES) {
                inet_ntop(AF_INET, &(client_addr.sin_addr), tb[tb_index].ip, MAX_IP_LEN);
                tb[tb_index].port = ntohs(client_addr.sin_port);
                tb_index++;
            }
        }
    }

    close(sockfd);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <message>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    signal(SIGINT, handle_sigint);

    pid_t pid = fork();
    if (pid < 0) {
        perror("Erreur lors du fork");
        exit(EXIT_FAILURE);
    }

    if (pid == 0) {
        // Processus fils (récepteur)
        receiver(argv[1]);
    } else {
        // Processus père (émetteur)
        sender(argv[1]);
    }

    return 0;
}
```

### Explications :
1. **Tableau `tb`** : Stocke les adresses IP et les ports des expéditeurs qui envoient le message attendu.
2. **Processus père** : Envoie périodiquement le message passé en argument à l'adresse de broadcast `255.255.255.255` sur le port `2346`. Toutes les 30 secondes, il affiche le contenu du tableau `tb`.
3. **Processus fils** : Attend les messages sur le port `2346`. Si un message reçu correspond à celui passé en argument, il ajoute l'adresse IP et le port de l'expéditeur dans le tableau `tb`.
4. **Gestion des signaux** : Le programme peut être arrêté proprement avec `Ctrl+C` grâce au gestionnaire de signal `SIGINT`.

### Compilation et exécution :
Compilez le programme avec :
```bash
