} FunctionCallNode;

FunctionCallNode* createNode(const char* functionName) {
    FunctionCallNode* node = (FunctionCallNode*)malloc(sizeof(FunctionCallNode));
    strcpy(node->functionName, functionName);
    node->children = NULL;
    node->nextSibling = NULL;
    return node;
}

void addChild(FunctionCallNode* parent, FunctionCallNode* child) {
    if (parent->children == NULL) {
        parent->children = child;
    } else {
        FunctionCallNode* current = parent->children;
        while (current->nextSibling != NULL) {
            current = current->nextSibling;
