#include "magazzino.h"

int leggi_magazzino(FILE *file, Prodotto *magazzino) {
    int n_prodotti = 0;
    while (fscanf(file, "%31s %f %d", magazzino[n_prodotti].codice, &magazzino[n_prodotti].costo, &magazzino[n_prodotti].quantita) == 3) {
        n_prodotti++;
        if (n_prodotti >= MAX_PRODOTTI) {
            break;
        }
    }
    return n_prodotti;
}

int controlla_aggiornamento(Prodotto *magazzino, int n_prodotti, const char *codice, int variazione) {
    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            if (variazione < 0 && -variazione > magazzino[i].quantita) {
                return -2; // Decremento non realizzabile
            } else if (variazione > 0 && magazzino[i].quantita + variazione > 10000) {
                return -2; // Incremento non realizzabile
            } else {
                printf("Variazione di %d per il prodotto %s\n", variazione, codice);
                return 1; // Variazione realizzabile
            }
        }
    }
    return -1; // Prodotto non trovato
}

void aggiorna_magazzino(Prodotto *magazzino, int n_prodotti, const char *codice, int variazione) {
    float valore_prima = 0.0;
    float valore_dopo = 0.0;

    for (int i = 0; i < n_prodotti; i++) {
        if (strcmp(magazzino[i].codice, codice) == 0) {
            valore_prima += magazzino[i].costo * magazzino[i].quantita;
            magazzino[i].quantita += variazione;
            valore_dopo += magazzino[i].costo * magazzino[i].quantita;
            break;
        }
    }

    printf("Valore complessivo prima: %.2f€\n", valore_prima);
    printf("Valore complessivo dopo: %.2f€\n", valore_dopo);
}

int compara_prodotti(const void *a, const void *b) {
    Prodotto *pa = (Prodotto *)a;
    Prodotto *pb = (Prodotto *)b;
    float valore_a = pa->costo * pa->quantita;
    float valore_b = pb->costo * pb->quantita;
    if (valore_a > valore_b) return -1;
    if (valore_a < valore_b) return 1;
    return 0;
}

void ordina_stampa_magazzino(Prodotto *magazzino, int n_prodotti, FILE *file) {
    qsort(magazzino, n_prodotti, sizeof(Prodotto), compara_prodotti);
    for (int i = 0; i < n_prodotti; i++) {
        fprintf(file, "%s %.2f %d\n", magazzino[i].codice, magazzino[i].costo, magazzino[i].quantita);
    }
}
