```c
#include <stdio.h>
#include <limits.h>
#include <stdbool.h>

#define V 6  // 图中顶点的数量
#define INF INT_MAX  // 表示无穷大

// 邻接矩阵表示图
int graph[V][V] = {
    {0, 4, 0, 0, 0, 0},
    {4, 0, 8, 0, 0, 0},
    {0, 8, 0, 7, 0, 4},
    {0, 0, 7, 0, 9, 14},
    {0, 0, 0, 9, 0, 10},
    {0, 0, 4, 14, 10, 0}
};

// 从顶点u到顶点v是否存在直接路径
int minDistance(int dist[], bool sptSet[]) {
    int min = INF, min_index;

    for (int v = 0; v < V; v++) {
        if (!sptSet[v] && dist[v] <= min) {
            min = dist[v];
            min_index = v;
        }
    }

    return min_index;
}

void dijkstra(int graph[V][V], int src) {
    int dist[V];  // 存储从源顶点到各顶点的最短距离
    bool sptSet[V];  // 标记顶点是否被纳入最短路径树

    // 初始化
    for (int i = 0; i < V; i++) {
        dist[i] = INF;
        sptSet[i] = false;
    }

    dist[src] = 0;  // 源顶点到自身的距离为0

    // 遍历所有顶点
    for (int count = 0; count < V - 1; count++) {
        int u = minDistance(dist, sptSet);

        sptSet[u] = true;  // 标记当前顶点为已访问

        // 更新与当前顶点相邻的顶点的距离
        for (int v = 0; v < V; v++) {
            if (!sptSet[v] && graph[u][v] && dist[u] != INF &&
                dist[u] + graph[u][v] < dist[v]) {
                dist[v] = dist[u] + graph[u][v];
            }
        }
    }

    // 打印最短距离
    printf("顶点   距离  路径\n");
    for (int i = 0; i < V; i++) {
        if (i != src) {
            printf("V%d     %d     V%d->V%d\n", i, dist[i], src, i);
        }
    }
}

int main() {
    int src = 0;  // 源顶点为V0
    dijkstra(graph, src);
    return 0;
}
```

### 代码说明：
1. **初始化**：
   - `dist[]` 数组用于存储从源顶点到各顶点的最短距离，初始化为 `INF`（无穷大）。
   - `sptSet[]` 数组用于标记顶点是否已被纳入最短路径树，初始化为 `false`。
   - 源顶点到自身的距离设置为 `0`。

2. **求最小**：
   - `minDistance()` 函数用于找到尚未被纳入最短路径树且具有最小距离的顶点。

3. **更新**：
   - 对于当前选定的顶点 `u`，更新其所有相邻顶点的距离。如果通过 `u` 到达 `v` 的距离更短，则更新 `dist[v]`。

4. **重复**：
   - 重复上述步骤，直到所有顶点都被纳入最短路径树。

5. **输出**：
   - 最后输出从源顶点到其他所有顶点的最短距离及路径。

