const int MAX_DIGITS = 31; // Максимальное количество цифр для чисел до 10^30

// Функция для преобразования строки в массив цифр
void stringToDigits(const char* str, char* digits) {
    int len = strlen(str);
    for (int i = 0; i < len; ++i) {
        digits[i] = str[len - 1 - i] - '0';
    }
    for (int i = len; i < MAX_DIGITS; ++i) {
        digits[i] = 0;
    }
}

// Функция для преобразования массива цифр в строку
void digitsToString(const char* digits, char* str) {
    int start = MAX_DIGITS - 1;
    while (start > 0 && digits[start] == 0) --start;
    for (int i = start; i >= 0; --i) {
        str[MAX_DIGITS - 1 - i] = digits[i] + '0';
    }
    str[MAX_DIGITS] = '\0';
    if (start == MAX_DIGITS - 1) {
        for (int i = MAX_DIGITS - 1; i > 0; --i) {
            str[i] = str[i - 1];
        }
        str[0] = '0';
    }
}

// Сложение двух чисел
void add(const char* a, const char* b, char* result) {
    int carry = 0;
    for (int i = 0; i < MAX_DIGITS; ++i) {
        int sum = a[i] + b[i] + carry;
        result[i] = sum % 10;
        carry = sum / 10;
    }
    assert(carry == 0); // Проверка на переполнение
}

// Вычитание двух чисел (a - b)
void subtract(const char* a, const char* b, char* result) {
    int borrow = 0;
    for (int i = 0; i < MAX_DIGITS; ++i) {
        int diff = a[i] - b[i] - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        result[i] = diff;
    }
    assert(borrow == 0); // Проверка на недопустимое вычитание
}

// Умножение двух чисел
void multiply(const char* a, const char* b, char* result) {
    for (int i = 0; i < MAX_DIGITS; ++i) {
        result[i] = 0;
    }
    for (int i = 0; i < MAX_DIGITS; ++i) {
        int carry = 0;
        for (int j = 0; j < MAX_DIGITS; ++j) {
            if (i + j < MAX_DIGITS) {
                int prod = a[i] * b[j] + result[i + j] + carry;
                result[i + j] = prod % 10;
                carry = prod / 10;
            } else {
                carry += a[i] * b[j];
            }
        }
        if (i + MAX_DIGITS < MAX_DIGITS) {
            result[i + MAX_DIGITS] = carry;
