#include <stdio.h>

/**
 * Решает систему уравнений:
 * 1. ax + by = c
 * 2. x - y = d
 *
 * Параметры:
 * a, b, c, d - коэффициенты и свободные члены уравнений.
 * x, y - указатели на переменные, куда будут сохранены решения.
 *
 * Возвращает:
 * 0 - если решение существует и найдено.
 * 1 - если система имеет бесконечно много решений (определитель равен 0).
 * 2 - если система несовместна (определитель равен 0, но свободные члены не удовлетворяют условиям).
 */
int solve_system(int a, int b, int c, int d, double *x, double *y) {
    // Вычисляем определитель системы
    double determinant = a + b;

    // Проверяем, не равен ли определитель нулю
    if (determinant == 0) {
        // Если определитель равен 0, проверяем, есть ли бесконечно много решений
        if (a * d + c == 0) {
            return 1; // Бесконечно много решений
        } else {
            return 2; // Система несовместна
        }
    }

    // Вычисляем решения системы
    *x = (c + b * d) / determinant;
    *y = (a * d + c) / determinant;

    return 0; // Решение существует
}

int main() {
    int a, b, c, d;
    double x, y;

    // Ввод коэффициентов и свободных членов
    printf("Введите значения a, b, c, d: ");
    scanf("%d %d %d %d", &a, &b, &c, &d);

    // Решаем систему уравнений
    int result = solve_system(a, b, c, d, &x, &y);

    // Выводим результат
    if (result == 0) {
        printf("Решение системы: x = %.2f, y = %.2f\n", x, y);
    } else if (result == 1) {
        printf("Система имеет бесконечно много решений.\n");
    } else {
        printf("Система несовместна.\n");
    }

    return 0;
}
