1. **Read Input**: Read the values of `n` (number of elements in the array) and `k` (the maximum digit to check for).
2. **Process Each Number**: For each number in the array, check if it contains all digits from `0` to `k`.
3. **Count k-good Numbers**: Maintain a count of how many numbers satisfy the **k-good** condition.
4. **Output the Result**: Print the count of **k-good** numbers.

Here’s the C code implementation:

```c
#include <stdio.h>
#include <stdbool.h>

// Function to check if a number is k-good
bool is_k_good(int number, int k) {
    // Array to keep track of digits seen (0-9)
    bool digit_seen[10] = {false};

    // Convert the number to a string and iterate through each character
    while (number > 0) {
        int digit = number % 10;
        digit_seen[digit] = true;
        number /= 10;
    }

    // Check if all digits from 0 to k are present
    for (int i = 0; i <= k; i++) {
        if (!digit_seen[i]) {
            return false;
        }
    }

    return true;
}

int main() {
    int n, k;
    scanf("%d %d", &n, &k);

    int count = 0;

    for (int i = 0; i < n; i++) {
        int number;
        scanf("%d", &number);

        if (is_k_good(number, k)) {
            count++;
        }
    }

    printf("%d\n", count);

    return 0;
}
