int isPowerOfTwo(int n) {
    return (n != 0) && ((n & (n - 1)) == 0);
}

// Function to tile the board with trominoes
void tromino(int x_board, int y_board, int x_missing, int y_missing, int board_size) {
    if (board_size == 2) {
        // Base case: board_size is 2x2
        int x_rel = x_missing - x_board;
        int y_rel = y_missing - y_board;

        // Determine the position of the missing square relative to the current board
        if (x_rel == 0 && y_rel == 1) { // Upper left corner missing
            printf("MS\tLR\nLR\tLR\n");
        } else if (x_rel == 1 && y_rel == 1) { // Upper right corner missing
            printf("LR\tMS\nLR\tLR\n");
        } else if (x_rel == 1 && y_rel == 0) { // Lower right corner missing
            printf("LR\tLR\nLR\tMS\n");
        } else if (x_rel == 0 && y_rel == 0) { // Lower left corner missing
            printf("LR\tLR\nMS\tLR\n");
        }
        return;
    }

    // Divide the board into four subboards
    int half_size = board_size / 2;

    // Determine which subboard contains the missing square
    int x_upper_left = (x_missing < x_board + half_size) ? x_missing : -1;
    int y_upper_left = (y_missing >= y_board + half_size) ? y_missing : -1;

    int x_upper_right = (x_missing >= x_board + half_size) ? x_missing : -1;
