        x_lower_left == -1 && y_lower_left == -1 &&
        x_lower_right == -1 && y_lower_right == -1) {
        x_upper_left = x_upper_right = x_lower_left = x_lower_right = -1;
        y_upper_left = y_upper_right = y_lower_left = y_lower_right = -1;
    }

    // Recursively tile the four subboards
    tromino(x_board, y_board + half_size, x_upper_left, y_upper_left, half_size);
    tromino(x_board + half_size, y_board + half_size, x_upper_right, y_upper_right, half_size);
