                listarFila();
                break;
            case 5:
                atualizarDisponibilidade();
                break;
            case 6:
                removerPessoaFila();
                break;
            case 0:
                printf("Saindo...\n");
                break;
            default:
                printf("Opção inválida!\n");
        }
    } while (opcao != 0);
}

void inserirLivro() {
    if (totalLivros >= MAX_LIVROS) {
        printf("Vetor de livros está cheio!\n");
        return;
    }

    Livro novoLivro;
    printf("Código do livro: ");
    scanf("%d", &novoLivro.codigo);
    printf("Nome do livro: ");
