        printf("Nome da pessoa: ");
        scanf("%s", nome);
        printf("Contato telefônico: ");
        scanf("%s", contato);
        adicionarFila(nome, livros[indice].nome, contato);
        printf("Pessoa adicionada à fila de espera!\n");
    }
}

void listarLivros() {
    if (totalLivros == 0) {
        printf("Nenhum livro cadastrado!\n");
        return;
    }

    printf("\n--- Lista de Livros ---\n");
    for (int i = 0; i < totalLivros; i++) {
