        return;
    }

    if (strcmp(livros[indice].disponibilidade, "disponivel") == 0) {
        strcpy(livros[indice].disponibilidade, "emprestado");
    } else {
        strcpy(livros[indice].disponibilidade, "disponivel");
        atenderProximaPessoa(codigo);
    }

    printf("Disponibilidade atualizada!\n");
}

void removerPessoaFila() {
    if (totalFila == 0) {
        printf("Fila de espera vazia!\n");
        return;
    }

    for (int i = 0; i < totalFila - 1; i++) {
        filaEspera[i] = filaEspera[i + 1];
    }
    totalFila--;
    printf("Pessoa removida da fila!\n");
}

int verificarDisponibilidade(int codigo) {
    for (int i = 0; i < totalLivros; i++) {
        if (livros[i].codigo == codigo) {
            return i;
        }
