#include <stdio.h>
#include <ctype.h>  // For isalpha() function
#include <limits.h> // For INT_MAX

int main() {
    char input[2];  // Buffer to hold the input (1 character + null terminator)
    int ch;

    printf("Enter a single letter: ");

    // Read characters until newline or EOF
    ch = 0;
    while ((ch = getchar()) != '\n' && ch != EOF) {
        if (isalpha(ch)) {
            if (input[0] != '\0') {
                // More than one letter entered
                printf("Error: Only one letter is allowed.\n");
                // Clear the input buffer to avoid infinite loop
                int c;
                while ((c = getchar()) != '\n' && c != EOF);
                return 1; // Exit with error code
            }
            input[0] = ch;
            input[1] = '\0'; // Null terminate the string
        } else {
            printf("Error: Invalid input. Please enter a letter.\n");
            // Clear the input buffer
            int c;
            while ((c = getchar()) != '\n' && c != EOF);
            return 1; // Exit with error code
        }
    }

    if (input[0] != '\0') {
        printf("You entered: %c\n", input[0]);
    } else {
        printf("Error: No input provided.\n");
        return 1; // Exit with error code
    }

    return 0; // Exit successfully
}
```

