int *formResultRow(int *srcRow, int cols, int *resultCols) {
    int count = 0;
    for (int i = 0; i < cols - 1; i++) {
        if (srcRow[i] <= srcRow[i + 1]) {
            count++;
        }
    }

    *resultCols = count + 1; // +1 для последнего элемента, если он не нарушает неубывание
    int *resultRow = (int *)malloc(*resultCols * sizeof(int));

