    resultRow[j++] = srcRow[0]; // Первый элемент всегда включаем
    for (int i = 0; i < cols - 1; i++) {
        if (srcRow[i] <= srcRow[i + 1]) {
            resultRow[j++] = srcRow[i + 1];
