To solve this problem, we need to determine the maximum number of fiber connections that can be removed while ensuring that the latency of the smallest latency path between the HQ (office 1) and any other office remains the same. This can be approached using a combination of Dijkstra's algorithm and some careful analysis of the paths.

Here’s a C++ implementation that solves the problem:

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <climits>
#include <algorithm>

using namespace std;

typedef pair<int, int> pii;

const int INF = INT_MAX;

vector<int> dijkstra(int n, vector<vector<pii>>& adj, int start) {
    vector<int> dist(n + 1, INF);
    dist[start] = 0;
    priority_queue<pii, vector<pii>, greater<pii>> pq;
    pq.push({0, start});

    while (!pq.empty()) {
        int u = pq.top().second;
        int d = pq.top().first;
        pq.pop();

        if (d > dist[u]) continue;

        for (auto& edge : adj[u]) {
            int v = edge.first;
            int w = edge.second;

            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }

    return dist;
}

int main() {
    int n, m, k;
    cin >> n >> m >> k;

    vector<vector<pii>> adj(n + 1);
    vector<int> fiber_latencies(k);
    vector<int> fiber_offices(k);

    for (int i = 0; i < m; ++i) {
        int a, b, l;
        cin >> a >> b >> l;
        adj[a].push_back({b, l});
        adj[b].push_back({a, l});
    }

    for (int i = 0; i < k; ++i) {
        cin >> fiber_offices[i] >> fiber_latencies[i];
        adj[1].push_back({fiber_offices[i], fiber_latencies[i]});
        adj[fiber_offices[i]].push_back({1, fiber_latencies[i]});
    }

    // Compute shortest paths without removing any fiber connections
    vector<int> original_dist = dijkstra(n, adj, 1);

    int removable = 0;

    for (int i = 0; i < k; ++i) {
        // Temporarily remove the ith fiber connection
        adj[1].pop_back();
        adj[fiber_offices[i]].pop_back();

        // Recompute shortest paths
        vector<int> new_dist = dijkstra(n, adj, 1);

        // Check if the shortest paths remain the same
        bool same = true;
        for (int j = 2; j <= n; ++j) {
            if (new_dist[j] != original_dist[j]) {
                same = false;
                break;
            }
        }

        if (same) {
            removable++;
        }

        // Restore the fiber connection
        adj[1].push_back({fiber_offices[i], fiber_latencies[i]});
        adj[fiber_offices[i]].push_back({1, fiber_latencies[i]});
    }

    cout << removable << endl;

    return 0;
}
```

### Explanation:

1. **Input Reading**: The code reads the number of offices `n`, normal connections `m`, and fiber connections `k`. It then reads the normal connections and fiber connections, storing them in an adjacency list `adj`.

2. **Dijkstra's Algorithm**: The `dijkstra` function computes the shortest paths from the HQ (office 1) to all other offices using Dijkstra's algorithm. This is done twice: once with all fiber connections and once with each fiber connection temporarily removed.

3. **Checking Removability**: For each fiber connection, the code temporarily removes it from the adjacency list and recomputes the shortest paths. If the shortest paths remain the same as the original, the fiber connection is considered removable, and the count `removable` is incremented.

4. **Output**: Finally, the code outputs the maximum number of fiber connections that can be removed without affecting the shortest paths.

This approach ensures that we correctly identify the maximum number of fiber connections that can be removed while maintaining the same shortest path latencies.

