#include <string.h>
#include <ctype.h>
#include <stdbool.h>

#define MAX_LINE_LENGTH 1024

// Функция для проверки, является ли символ шестнадцатеричным
bool is_hex_digit(char c) {
    return (c >= '0' && c <= '9') || 
           (c >= 'a' && c <= 'f') || 
           (c >= 'A' && c <= 'F');
}

// Функция для выделения шестнадцатеричных констант в строке
void highlight_hex_constants(const char *line) {
    bool in_hex = false;
    bool after_0x = false;

    for (size_t i = 0; line[i] != '\0'; ++i) {
        if (after_0x) {
            if (is_hex_digit(line[i])) {
                in_hex = true;
                printf("\033[1;31m%c\033[0m", line[i]); // Выделяем красный цвет
            } else {
                after_0x = false;
                in_hex = false;
                printf("%c", line[i]);
