        // Удаляем символ новой строки, если он есть
        size_t len = strlen(line);
        if (len > 0 && line[len - 1] == '\n') {
            line[len - 1] = '\0';
        }
        highlight_hex_constants(line);
    }

    fclose(file);
    return EXIT_SUCCESS;
}
