### **server.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <unistd.h>
#include <pthread.h>
#include <fcntl.h>

#define SHM_SIZE 1024
#define SEM_KEY 1234
#define SHM_KEY 5678

int sem_id;
int shm_id;
char *shm_ptr;

void *handle_command(void *arg) {
    // Parse command
    char command[SHM_SIZE];
    strcpy(command, shm_ptr);
    struct sembuf sem_unlock = {0, 1}; // Unlock semaphore
    semop(sem_id, &sem_unlock, 1);

    // Clear shared memory
    memset(shm_ptr, 0, SHM_SIZE);

    char *token = strtok(command, " ");
    if (strcmp(token, "read") == 0) {
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Invalid read command\n");
            return NULL;
        }
        char filename[256];
        strcpy(filename, token);

        // Create new shared memory for file content
        int new_shm_id = shmget(SHM_KEY + 1, SHM_SIZE, IPC_CREAT | 0666);
        char *new_shm_ptr = shmat(new_shm_id, NULL, 0);

        // Read file content
        FILE *fp = fopen(filename, "r");
        if (fp == NULL) {
            printf("File not found\n");
            return NULL;
        }
        fread(new_shm_ptr, 1, SHM_SIZE, fp);
        fclose(fp);

        // Share new shared memory key with client
        sprintf(shm_ptr, "%d", new_shm_id);
        shmdt(new_shm_ptr);
    } else if (strcmp(token, "write") == 0) {
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Invalid write command\n");
            return NULL;
        }
        char filename[256];
        strcpy(filename, token);

        token = strtok(NULL, "");
        if (token == NULL) {
            printf("No data provided for write\n");
            return NULL;
        }
        char data[SHM_SIZE];
        strcpy(data, token);

        // Write data to file
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            printf("Failed to open file for writing\n");
            return NULL;
        }
        fprintf(fp, "%s", data);
        fclose(fp);
    } else {
        printf("Invalid command\n");
    }

    return NULL;
}

int main() {
    // Create shared memory
    shm_id = shmget(SHM_KEY, SHM_SIZE, IPC_CREAT | 0666);
    shm_ptr = shmat(shm_id, NULL, 0);

    // Create semaphore
    sem_id = semget(SEM_KEY, 1, IPC_CREAT | 0666);
    semctl(sem_id, 0, SETVAL, 1); // Initialize semaphore to 1

    while (1) {
        // Wait for client command
        struct sembuf sem_lock = {0, -1}; // Lock semaphore
        semop(sem_id, &sem_lock, 1);

        // Create a new thread to handle the command
        pthread_t thread_id;
        pthread_create(&thread_id, NULL, handle_command, NULL);
        pthread_detach(thread_id);
    }

    // Cleanup (not reached in infinite loop)
    shmdt(shm_ptr);
    shmctl(shm_id, IPC_RMID, NULL);
    semctl(sem_id, 0, IPC_RMID, NULL);

    return 0;
}
```

