### **client.c**

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>
#include <unistd.h>

#define SHM_SIZE 1024
#define SEM_KEY 1234
#define SHM_KEY 5678

int sem_id;
int shm_id;
char *shm_ptr;

void send_command(char *command) {
    // Lock semaphore
    struct sembuf sem_lock = {0, -1};
    semop(sem_id, &sem_lock, 1);

    // Write command to shared memory
    strcpy(shm_ptr, command);
}

int main() {
    // Get shared memory and semaphore
    shm_id = shmget(SHM_KEY, SHM_SIZE, 0666);
    shm_ptr = shmat(shm_id, NULL, 0);
    sem_id = semget(SEM_KEY, 1, 0666);

    char command[SHM_SIZE];
    printf("Enter command (read <filename> or write <filename> <data>): ");
    fgets(command, SHM_SIZE, stdin);
    command[strcspn(command, "\n")] = 0; // Remove newline

    // Validate command format
    char *token = strtok(command, " ");
    if (token == NULL) {
        printf("Invalid command\n");
        exit(1);
    }

    if (strcmp(token, "read") == 0) {
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Invalid read command\n");
            exit(1);
        }
    } else if (strcmp(token, "write") == 0) {
        token = strtok(NULL, " ");
        if (token == NULL) {
            printf("Invalid write command\n");
            exit(1);
        }
        strtok(NULL, ""); // Check for data
    } else {
        printf("Invalid command\n");
        exit(1);
    }

    // Send command to server
    send_command(command);

    if (strstr(command, "read") != NULL) {
        // Wait for server response
        while (shm_ptr[0] == 0) {
            sleep(1); // Busy waiting (not ideal, but simple)
        }

        // Get new shared memory key from server
        int new_shm_id = atoi(shm_ptr);
        char *new_shm_ptr = shmat(new_shm_id, NULL, 0);

        // Print file content
        printf("File content: %s\n", new_shm_ptr);

        // Cleanup
        shmdt(new_shm_ptr);
        shmctl(new_shm_id, IPC_RMID, NULL);
    }

    // Cleanup
    shmdt(shm_ptr);
    return 0;
}
```

---

### **Explanation**

1. **Shared Memory and Semaphores**:
   - Shared memory (`shmget`, `shmat`) is used for communication between the client and server.
   - Semaphores (`semget`, `semop`) ensure mutual exclusion and avoid race conditions.

2. **Server**:
   - The server allocates shared memory and waits for client commands.
   - It handles `read` and `write` commands by creating threads.
   - For `read`, it creates a new shared memory segment to send the file content.
   - For `write`, it writes the data to the specified file.

3. **Client**:
   - The client reads commands from the terminal and validates their format.
   - It uses semaphores to ensure exclusive access to shared memory.
   - For `read` commands, it waits for the server's response and prints the file content.

---

### **Compilation and Execution**

1. Compile the programs:
