float calculateSeekTime(int *sequence, int n, int *order) {
    float totalSeekTime = 0;
    int currentPosition = sequence[order[0]];
    for (int i = 1; i < n; i++) {
        totalSeekTime += abs(sequence[order[i]] - currentPosition);
        currentPosition = sequence[order[i]];
    }
    return totalSeekTime / n;
}

// FCFS算法
void fcfs(int *sequence, int n, int *order) {
    for (int i = 0; i < n; i++) {
        order[i] = i;
    }
}

// SSTF算法
void sstf(int *sequence, int n, int initialHead, int *order) {
    bool visited[n];
    for (int i = 0; i < n; i++) {
        visited[i] = false;
    }
    int currentPosition = initialHead;
    for (int i = 0; i < n; i++) {
