        int minDistance = INT_MAX;
        for (int j = 0; j < n; j++) {
            if (!visited[j] && abs(sequence[j] - currentPosition) < minDistance) {
                minDistance = abs(sequence[j] - currentPosition);
                minIndex = j;
            }
        }
        order[i] = minIndex;
        visited[minIndex] = true;
        currentPosition = sequence[minIndex];
    }
}

// SCAN算法
void scan(int *sequence, int n, int initialHead, int initialDirection, int *order) {
    bool visited[n];
    for (int i = 0; i < n; i++) {
        visited[i] = false;
