char last_operated_operator(const char *expression) {
    int len = strlen(expression);
    char stack[len];
    int top = -1;
    char last_op = '\0';

    for (int i = 0; i < len; i++) {
        char ch = expression[i];

        if (isalpha(ch) || isdigit(ch)) {
            // 忽略操作数
        } else if (ch == '(') {
            stack[++top] = ch;
        } else if (ch == ')') {
            while (top >= 0 && stack[top] != '(') {
                last_op = stack[top--];
            }
            if (top >= 0) top--; // 弹出'('
        } else if (ch == '+' || ch == '-' || ch == '*' || ch == '/' || ch == '^') {
            while (top >= 0 && precedence(stack[top]) >= precedence(ch)) {
                last_op = stack[top--];
            }
            stack[++top] = ch;
        }
    }

