```cpp
#include <iostream>
#include <queue>

// Определение структуры узла дерева
struct TreeNode {
    int data;
    TreeNode* left;
    TreeNode* right;

    TreeNode(int value) : data(value), left(nullptr), right(nullptr) {}
};

// Функция для добавления одного узла в дерево
TreeNode* AddNode(TreeNode* root, int data) {
    if (root == nullptr) {
        return new TreeNode(data);
    }

    std::queue<TreeNode*> queue;
    queue.push(root);

    while (!queue.empty()) {
        TreeNode* current = queue.front();
        queue.pop();

        if (current->left == nullptr) {
            current->left = new TreeNode(data);
            return root;
        } else {
            queue.push(current->left);
        }

        if (current->right == nullptr) {
            current->right = new TreeNode(data);
            return root;
        } else {
            queue.push(current->right);
        }
    }

    return root;
}

// Функция для заполнения дерева произвольным количеством элементов
TreeNode* fullTree(TreeNode* root, const std::vector<int>& elements) {
    for (int element : elements) {
        root = AddNode(root, element);
    }
    return root;
}

// Функция для освобождения памяти дерева (опционально)
void deleteTree(TreeNode* root) {
    if (root == nullptr) return;

    deleteTree(root->left);
    deleteTree(root->right);
    delete root;
}

