 * @param data 用于存储数据的byte数组
 * @param max_size data数组的最大大小
 * @return 实际读取的字节数，或-1表示错误
 */
int read_csv_to_byte_array(const char *filename, unsigned char *data, size_t max_size) {
    if (filename == NULL || data == NULL || max_size == 0) {
        return -1; // 参数无效
    }

    FILE *file = fopen(filename, "rb"); // 以二进制模式打开文件
    if (file == NULL) {
        perror("fopen failed");
        return -1; // 无法打开文件
    }

    size_t total_bytes = 0;
    char line[MAX_LINE_LENGTH];

    while (fgets(line, sizeof(line), file) != NULL) {
        size_t line_length = strlen(line);

        // 检查是否有足够的空间来存储当前行
        if (total_bytes + line_length >= max_size) {
            break; // 数组已满，停止读取
        }

        // 将当前行复制到byte数组中
        memcpy(data + total_bytes, line, line_length);
        total_bytes += line_length;
    }

    fclose(file);
    return total_bytes;
}

int main() {
