Below is a C program that solves the problem of determining the number of different routes between intersections in a city with one-way streets. The program uses a graph representation and Floyd-Warshall algorithm to compute the number of routes. If there are cycles that cause infinite routes, it marks the entry as `-1`.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_INTERSECTIONS 31
#define INF -1  // Represents infinite routes

void initialize_matrix(int matrix[MAX_INTERSECTIONS][MAX_INTERSECTIONS], int size) {
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (i == j) {
                matrix[i][j] = 0;  // No route from an intersection to itself
            } else {
                matrix[i][j] = 0;  // Initialize all other entries to 0
            }
        }
    }
}

void floyd_warshall(int matrix[MAX_INTERSECTIONS][MAX_INTERSECTIONS], int size) {
    for (int k = 0; k < size; k++) {
        for (int i = 0; i < size; i++) {
            for (int j = 0; j < size; j++) {
                if (matrix[i][k] > 0 && matrix[k][j] > 0) {
                    if (matrix[i][j] == INF || matrix[i][j] < matrix[i][k] * matrix[k][j]) {
                        if (matrix[i][j] != INF && matrix[i][k] * matrix[k][j] == INF) {
                            matrix[i][j] = INF;
                        } else if (matrix[i][j] != INF && matrix[i][k] * matrix[k][j] != INF) {
                            matrix[i][j] += matrix[i][k] * matrix[k][j];
                        }
                    }
                }
            }
        }
    }
}

void detect_cycles(int matrix[MAX_INTERSECTIONS][MAX_INTERSECTIONS], int size) {
    for (int i = 0; i < size; i++) {
        if (matrix[i][i] > 0) {
            // If there's a cycle, mark all reachable paths as INF
            for (int j = 0; j < size; j++) {
                if (matrix[i][j] > 0) {
                    matrix[i][j] = INF;
                }
            }
            for (int j = 0; j < size; j++) {
                if (matrix[j][i] > 0) {
                    matrix[j][i] = INF;
                }
            }
        }
    }
}

void print_matrix(int matrix[MAX_INTERSECTIONS][MAX_INTERSECTIONS], int size, int city_id) {
    printf("matrix for city %d\n", city_id);
    for (int i = 0; i < size; i++) {
        for (int j = 0; j < size; j++) {
            if (j > 0) printf(" ");
            printf("%d", matrix[i][j]);
        }
        printf("\n");
    }
}

int main() {
    int city_id = 0;
    int num_streets, from, to;

    while (scanf("%d", &num_streets) == 1) {
        int max_intersection = 0;
        int matrix[MAX_INTERSECTIONS][MAX_INTERSECTIONS];

        // Find the largest intersection number
        for (int i = 0; i < num_streets; i++) {
            scanf("%d %d", &from, &to);
            if (from > max_intersection) max_intersection = from;
            if (to > max_intersection) max_intersection = to;
        }

        // Re-read the streets since scanf doesn't reset the input buffer
        int streets[num_streets][2];
        for (int i = 0; i < num_streets; i++) {
            scanf("%d %d", &streets[i][0], &streets[i][1]);
        }

        int size = max_intersection + 1;
        initialize_matrix(matrix, size);

        // Populate the adjacency matrix
        for (int i = 0; i < num_streets; i++) {
            matrix[streets[i][0]][streets[i][1]] = 1;
        }

        // Apply Floyd-Warshall algorithm
        floyd_warshall(matrix, size);

        // Detect cycles and mark infinite routes
        detect_cycles(matrix, size);

        // Print the result matrix
        print_matrix(matrix, size, city_id);

        city_id++;
    }

    return 0;
}
```

### Explanation:
1. **Graph Representation**: The city's intersections and streets are represented as a graph where intersections are nodes, and streets are directed edges.
2. **Initialization**: The adjacency matrix is initialized with zeros, except for the diagonal, which remains zero (no route from an intersection to itself).
3. **Floyd-Warshall Algorithm**: This algorithm is used to compute the number of routes between all pairs of intersections. It iteratively updates the number of routes by considering intermediate intersections.
4. **Cycle Detection**: After computing the routes, the program checks for cycles that could lead to infinite routes. If a cycle is detected, the corresponding entries are marked as `-1`.
5. **Output**: The program prints the matrix of routes for each city, prefixed by "matrix for city k".

### Notes:
- The program assumes that intersections are numbered sequentially from `0` to the largest intersection.
- The Floyd-Warshall algorithm is modified to handle the counting of routes rather than just detecting reachability.
- Infinite routes are detected by checking if there's a cycle in the graph.

