        printFile();

        HANDLE pipe = CreateNamedPipe(
            TEXT("\\\\.\\pipe\\employee_pipe"),
            PIPE_ACCESS_DUPLEX,
            PIPE_TYPE_MESSAGE | PIPE_READMODE_MESSAGE | PIPE_WAIT,
            PIPE_UNLIMITED_INSTANCES,
            4096, 4096,
            0,
            NULL
        );

        if (pipe == INVALID_HANDLE_VALUE) {
            cerr << "Ошибка создания именованного канала." << endl;
            return;
        }

        cout << "Сервер ожидает подключения клиента..." << endl;

        while (true) {
            if (ConnectNamedPipe(pipe, NULL) != FALSE) {
                cout << "Клиент подключен." << endl;

                DWORD bytesRead, bytesWritten;
                int id;
                bool isWrite;
                employee data;

                while (true) {
                    if (ReadFile(pipe, &id, sizeof(id), &bytesRead, NULL) && bytesRead > 0) {
                        if (ReadFile(pipe, &isWrite, sizeof(isWrite), &bytesRead, NULL) && bytesRead > 0) {
