// Structure to represent a process
typedef struct {
    pid_t pid;
    pid_t ppid;
    bool is_defunct;
} Process;

// Global array to store all processes
Process processes[MAX_PROCESSES];
int process_count = 0;

// Function to read process information from /proc
void read_processes() {
    DIR *dir;
    struct dirent *entry;
    dir = opendir("/proc");
    if (dir == NULL) {
        perror("opendir");
        exit(EXIT_FAILURE);
    }

    while ((entry = readdir(dir)) != NULL) {
        if (entry->d_type == DT_DIR && atoi(entry->d_name) > 0) {
            pid_t pid = atoi(entry->d_name);
            char path[256];
            snprintf(path, sizeof(path), "/proc/%d/stat", pid);
            FILE *file = fopen(path, "r");
            if (file != NULL) {
                int ppid;
                char state;
                fscanf(file, "%*d %*s %c %d", &state, &ppid);
                bool is_defunct = (state == 'Z');
                processes[process_count].pid = pid;
                processes[process_count].ppid = ppid;
                processes[process_count].is_defunct = is_defunct;
                process_count++;
                fclose(file);
            }
        }
    }
    closedir(dir);
}

// Function to check if a process is in the tree rooted at root_pid
bool is_in_tree(pid_t pid, pid_t root_pid) {
    while (pid != root_pid && pid != 1) {
        for (int i = 0; i < process_count; i++) {
            if (processes[i].pid == pid) {
                pid = processes[i].ppid;
                break;
            }
        }
    }
    return (pid == root_pid);
}

// Function to print PID and PPID of a process
void print_pid_ppid(pid_t pid) {
    for (int i = 0; i < process_count; i++) {
        if (processes[i].pid == pid) {
            printf("PID: %d, PPID: %d\n", processes[i].pid, processes[i].ppid);
            return;
        }
    }
}

// Function to print non-direct descendants of a process
void print_non_direct_descendants(pid_t pid) {
    for (int i = 0; i < process_count; i++) {
        if (processes[i].ppid != pid && is_in_tree(processes[i].pid, pid)) {
