sem_t *sem1, *sem2;

void initialize_semaphores() {
    // Create or open named semaphores with initial value 1
    sem1 = sem_open("/sem1", O_CREAT, 0644, 1);
    sem2 = sem_open("/sem2", O_CREAT, 0644, 1);
    if (sem1 == SEM_FAILED || sem2 == SEM_FAILED) {
        perror("sem_open failed");
        exit(EXIT_FAILURE);
    }
}

void cleanup_semaphores() {
    sem_close(sem1);
    sem_close(sem2);
    sem_unlink("/sem1");
    sem_unlink("/sem2");
}

void handle_input() {
    char ch;
    while (1) {
        printf("Enter command (1/q/2/w): ");
        ch = getchar();
        switch (ch) {
            case '1':
                printf("Instance: Acquiring semaphore 1...\n");
                sem_wait(sem1);
                printf("Instance: Acquired semaphore 1.\n");
                break;
            case 'q':
                printf("Instance: Releasing semaphore 1...\n");
                sem_post(sem1);
                printf("Instance: Released semaphore 1.\n");
                break;
            case '2':
                printf("Instance: Acquiring semaphore 2...\n");
                sem_wait(sem2);
                printf("Instance: Acquired semaphore 2.\n");
                break;
            case 'w':
                printf("Instance: Releasing semaphore 2...\n");
                sem_post(sem2);
                printf("Instance: Released semaphore 2.\n");
                break;
            default:
                printf("Invalid command.\n");
        }
    }
}

int main() {
    initialize_semaphores();
    handle_input();
    cleanup_semaphores();
    return 0;
}
