        for (int i = 0; cleaned_line[i]; i++) {
            char answer = cleaned_line[i];
            int question_number = i + 1;
            int point_value = (question_number >= boundary) ? 2 : 1;

            if (answer == '$' && !joker_used) {
                joker_used = true;
                joker_category = category_count;
                joker_in_category = true;
                continue;
            }

            if (answer == 'o') {
                int earned = point_value;
                if (joker_in_category) {
                    earned *= 2;
                }
                points += earned;
                if (category_count <= 2) {
                    halftime += earned;
                }
            }
