#include <stdio.h>
#include <stdbool.h>

// 定义运算符
typedef enum { ADD, SUB, MUL, DIV } Operator;

// 定义运算函数
double apply_operator(double a, double b, Operator op) {
    switch (op) {
        case ADD: return a + b;
        case SUB: return a - b;
        case MUL: return a * b;
        case DIV: 
            if (b == 0) return 0; // 避免除零错误
            return a / b;
        default: return 0;
    }
}

// 检查是否可以得到24
bool check24(double a, double b, double c, double d) {
    // 尝试所有可能的组合
    double results[4] = {a, b, c, d};
    bool used[4] = {false, false, false, false};
    return try_combination(results, used, 0, 1);
}

// 递归尝试所有组合
bool try_combination(double results[], bool used[], int depth, int target) {
    if (depth == 3) {
        return fabs(results[0] - 24) < 1e-6; // 检查是否等于24
    }

    for (int i = 0; i < 4; i++) {
        if (used[i]) continue;
        for (int j = 0; j < 4; j++) {
            if (i == j || used[j]) continue;
            for (int op = 0; op < 4; op++) {
                Operator operator = (Operator)op;
                double new_value = apply_operator(results[i], results[j], operator);
                if (new_value == 0 && operator == DIV) continue; // 避免除零错误

                used[i] = used[j] = true;
                results[i] = new_value;
                if (try_combination(results, used, depth + 1, target)) {
                    return true;
                }
                used[i] = used[j] = false;
                results[i] = (i < j) ? results[i] : results[j];
            }
        }
    }
    return false;
}

int main() {
    double cards[4] = {3, 3, 8, 10}; // 示例牌组
    if (check24(cards[0], cards[1], cards[2], cards[3])) {
        printf("可以得到24!\n");
    } else {
        printf("无法得到24.\n");
    }
    return 0;
}
```

### 算法复杂度分析
- **时间复杂度**：在最坏情况下，需要尝试所有可能的运算组合。由于有4个数和4种运算符，每次选择2个数和1种运算符，复杂度约为 \(O(4! \times 4^3)\)，即 \(O(384)\)。通过剪枝，实际复杂度会更低。
- **空间复杂度**：递归深度最大为3，因此空间复杂度为 \(O(1)\)。

