size_t utf8_strlen(const char *str) {
    size_t len = 0;
    while (*str) {
        if ((*str & 0xC0) != 0x80) len++;
        str++;
    }
    return len;
}

// Функция для извлечения подстроки из UTF-8 строки
char* utf8_substr(const char *str, size_t start, size_t end) {
    size_t len = utf8_strlen(str);
    if (start >= len || end <= start || end > len) {
        return NULL; // Неверные индексы
    }

    size_t byte_start = 0, byte_end = 0;
    size_t pos = 0;

    // Находим начало подстроки в байтах
    while (pos < start && str[byte_start]) {
        if ((str[byte_start] & 0xC0) != 0x80) pos++;
        byte_start++;
    }

    // Находим конец подстроки в байтах
    pos = 0;
    while (pos < end && str[byte_end]) {
        if ((str[byte_end] & 0xC0) != 0x80) pos++;
        byte_end++;
