    char *substr = (char*)malloc(byte_end - byte_start + 1);
    if (!substr) {
        return NULL; // Ошибка выделения памяти
    }

    // Копируем подстроку
    strncpy(substr, str + byte_start, byte_end - byte_start);
    substr[byte_end - byte_start] = '\0';

    return substr;
}

