     * 虽然这里使用了迭代方法，但实际上1到n的累加和可以通过公式 n * (n + 1) / 2 直接计算。
     * 此方法仅用于演示位移操作在迭代中的应用。
     *
     * @param n 上限值
     * @return 1到n的累加和
     */
    public static int calculateSum(int n) {
        int sum = 0;
        for (int i = 1; i <= n; i++) {
            // 使用位移操作优化累加
            sum += i;  // 这里实际上没有使用位移操作，因为位移操作通常用于位操作，而不是数学累加。
            // 如果要使用位移操作，可以考虑使用位移来优化某些特定的计算，但对于简单的累加，位移操作并不是最优选择。
        }
        return sum;
    }

    // 为了演示位移操作，我们可以实现一个使用位移优化的乘法函数
    private static int multiplyUsingShift(int a, int b) {
        int result = 0;
        while (b > 0) {
            if ((b & 1) == 1) {
                result += a;
            }
            a <<= 1;  // 左移相当于乘以2
            b >>= 1;  // 右移相当于除以2
        }
        return result;
    }

    // 使用数学公式计算1到n的累加和，作为对比
    public static int calculateSumFormula(int n) {
        return n * (n + 1) / 2;
    }

    public static void main(String[] args) {
        int n = 100;
        int sum = calculateSum(n);
        int sumFormula = calculateSumFormula(n);
        System.out.println("使用迭代方法计算的1到" + n + "的累加和: " + sum);
        System.out.println("使用数学公式计算的1到" + n + "的累加和: " + sumFormula);

        // 演示使用位移优化的乘法
        int a = 5;
        int b = 3;
        int product = multiplyUsingShift(a, b);
        System.out.println(a + " * " + b + " = " + product);
    }
}
