import java.io.*;
import java.net.*;
import java.util.*;

public class CustomerServiceServer {
    private static final int PORT = 12345;
    private static Map<String, ClientHandler> clients = new HashMap<>();
    private static Map<String, String> chatHistory = new HashMap<>();

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(PORT)) {
            System.out.println("客服端启动，等待用户连接...");
            while (true) {
                Socket socket = serverSocket.accept();
                new Thread(new ClientHandler(socket)).start();
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    static class ClientHandler implements Runnable {
        private Socket socket;
        private String clientId;
        private PrintWriter out;
        private BufferedReader in;

        public ClientHandler(Socket socket) {
            this.socket = socket;
        }

        @Override
        public void run() {
            try {
                in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
                out = new PrintWriter(socket.getOutputStream(), true);

                clientId = in.readLine(); // 读取客户端ID
                System.out.println("新用户连接：" + clientId);

                // 加载历史聊天记录
                if (chatHistory.containsKey(clientId)) {
                    out.println("HISTORY:" + chatHistory.get(clientId));
                }

                String message;
                while ((message = in.readLine()) != null) {
                    if (message.startsWith("FILE:")) {
                        // 处理文件接收
                        receiveFile(message.substring(5));
                    } else {
                        // 保存聊天记录
                        String response = "客服：" + message;
                        chatHistory.put(clientId, chatHistory.getOrDefault(clientId, "") + "\n" + response);
                        System.out.println("用户 " + clientId + "：" + message);
                        out.println(response);
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            } finally {
                clients.remove(clientId);
                try {
                    socket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
