public class SecureImageSocket {

    private static final int MAX_IMAGE_SIZE = 10 * 1024 * 1024; // 10MB
    private static final String HMAC_KEY = "secure-key-123"; // 实际应从安全存储中获取

    public static void sendImage(SSLSocket socket, byte[] imageData) throws Exception {
        // 完整性校验
        byte[] hmac = calculateHmac(imageData);

        // 发送数据长度 + HMAC + 图片数据
        try (DataOutputStream dos = new DataOutputStream(socket.getOutputStream())) {
            dos.writeInt(imageData.length);
            dos.write(hmac);
            dos.write(imageData);
        }
    }

    public static byte[] receiveImage(SSLSocket socket) throws Exception {
        try (DataInputStream dis = new DataInputStream(socket.getInputStream())) {
            int length = dis.readInt();
            if (length > MAX_IMAGE_SIZE) {
                throw new IOException("Image too large");
            }

            byte[] hmacReceived = new byte[32];
            dis.readFully(hmacReceived);

            byte[] imageData = new byte[length];
            dis.readFully(imageData);

            // 验证HMAC
            byte[] hmacCalculated = calculateHmac(imageData);
            if (!MessageDigest.isEqual(hmacReceived, hmacCalculated)) {
                throw new SecurityException("Data tampered");
            }

            return imageData;
        }
    }

    private static byte[] calculateHmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(HMAC_KEY.getBytes(), "HmacSHA256"));
        return mac.doFinal(data);
    }

    public static void main(String[] args) throws Exception {
        // SSL配置（省略证书加载）
        SSLContext sslContext = SSLContext.getInstance("TLS");
        sslContext.init(null, null, new SecureRandom());
        SSLSocket socket = (SSLSocket) sslContext.getSocketFactory().createSocket("server.com", 443);

        // 发送/接收图片
        byte[] image = readImageFromFile("image.jpg");
        sendImage(socket, image);
        byte[] receivedImage = receiveImage(socket);
    }
}
```

---

### **4. 测试与审计**
