            @Override
            public void actionPerformed(ActionEvent e) {
                handleClient(false);
            }
        });

        frame.setVisible(true);
    }

    private void startServer() {
        try {
            serverSocket = new ServerSocket(1234);
            new Thread(() -> {
                while (true) {
                    try {
                        Socket socket = serverSocket.accept();
                        chatArea.append("新用户连接: " + socket.getInetAddress() + "\n");
                        ClientHandler handler = new ClientHandler(socket);
                        clients.put(socket.getInetAddress().toString(), handler);
                        pool.execute(handler);
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }).start();
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

