### **TCPPacketServer.java**
```java
import java.io.*;
import java.net.*;
import java.util.concurrent.*;

public class TCPPacketServer {
    private static int port = 1024;
    private static ExecutorService pool = Executors.newFixedThreadPool(10);

    public static void main(String[] args) {
        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("Server started on port " + port);
            while (true) {
                Socket clientSocket = serverSocket.accept();
                pool.execute(new ClientHandler(clientSocket));
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private static class ClientHandler implements Runnable {
        private Socket clientSocket;

        public ClientHandler(Socket socket) {
            this.clientSocket = socket;
        }

        @Override
        public void run() {
            try (ObjectInputStream ois = new ObjectInputStream(clientSocket.getInputStream());
                 ObjectOutputStream oos = new ObjectOutputStream(clientSocket.getOutputStream())) {

                while (true) {
                    Packet packet = (Packet) ois.readObject();
                    if (packet.getData().equalsIgnoreCase("CLOSE")) {
                        System.out.println("Client requested to close the connection.");
                        break;
                    }
                    System.out.println("FROM CLIENT " + clientSocket.getRemoteSocketAddress() + ": Packet SerialNo#" + packet.getSerialNo() + " with data: " + packet.getData());

                    String upperCaseData = packet.getData().toUpperCase();
                    Packet responsePacket = new Packet(packet.getSerialNo(), upperCaseData);
                    oos.writeObject(responsePacket);
                    oos.flush();
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            } finally {
                try {
                    clientSocket.close();
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
```

