Below is a detailed approach to developing parallel codes for a sample problem in both Java and C++. I'll use **matrix multiplication** as the example problem, as it's well-suited for parallelization. I'll also provide guidance on measuring speedup using `gettimeofday()` in C++ and `System.nanoTime()` in Java.

---

### **Problem: Parallel Matrix Multiplication**
Given two matrices \( A \) and \( B \) of size \( n \times n \), compute the product matrix \( C \) in parallel.

---

### **C++ Implementation**

```cpp
#include <iostream>
#include <thread>
#include <vector>
#include <chrono>
#include <sys/time.h>

using namespace std;

// Function to measure time using gettimeofday()
double get_time() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    return tv.tv_sec + tv.tv_usec * 1e-6;
}

// Parallel matrix multiplication function
void parallelMatrixMultiply(const vector<vector<int>>& A, const vector<vector<int>>& B, vector<vector<int>>& C, int n, int numThreads) {
    vector<thread> threads;
    int rowsPerThread = n / numThreads;

    auto multiplyBlock = [&](int startRow) {
        for (int i = startRow; i < startRow + rowsPerThread; ++i) {
            for (int j = 0; j < n; ++j) {
                C[i][j] = 0;
                for (int k = 0; k < n; ++k) {
                    C[i][j] += A[i][k] * B[k][j];
                }
            }
        }
    };

    for (int t = 0; t < numThreads; ++t) {
        int startRow = t * rowsPerThread;
        threads.emplace_back(multiplyBlock, startRow);
    }

    for (auto& t : threads) {
        t.join();
    }
}

int main() {
    int n = 1000; // Matrix size
    int numThreads[] = {1, 2, 4, 6, 8, 10, 12, 14, 16};

    vector<vector<int>> A(n, vector<int>(n, 1));
    vector<vector<int>> B(n, vector<int>(n, 1));
    vector<vector<int>> C(n, vector<int>(n, 0));

    for (int t : numThreads) {
        double start = get_time();
        parallelMatrixMultiply(A, B, C, n, t);
        double end = get_time();
        cout << "Threads: " << t << ", Time: " << (end - start) << " seconds" << endl;
    }

    return 0;
}
```

---

### **Java Implementation**

```java
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class ParallelMatrixMultiply {

    static int n = 1000; // Matrix size
    static int[][] A = new int[n][n];
    static int[][] B = new int[n][n];
    static int[][] C = new int[n][n];

    static {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                A[i][j] = 1;
                B[i][j] = 1;
            }
        }
    }

    static class MatrixBlock implements Runnable {
        private int startRow;
        private int endRow;

        public MatrixBlock(int startRow, int endRow) {
            this.startRow = startRow;
            this.endRow = endRow;
        }

        @Override
        public void run() {
            for (int i = startRow; i < endRow; i++) {
                for (int j = 0; j < n; j++) {
                    C[i][j] = 0;
                    for (int k = 0; k < n; k++) {
                        C[i][j] += A[i][k] * B[k][j];
                    }
                }
            }
        }
    }

    public static void parallelMatrixMultiply(int numThreads) throws InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(numThreads);
        int rowsPerThread = n / numThreads;

        for (int t = 0; t < numThreads; t++) {
            int startRow = t * rowsPerThread;
            int endRow = (t == numThreads - 1) ? n : startRow + rowsPerThread;
            executor.submit(new MatrixBlock(startRow, endRow));
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);
    }

    public static void main(String[] args) throws InterruptedException {
        int[] numThreads = {1, 2, 4, 6, 8, 10, 12, 14, 16};

        for (int t : numThreads) {
            long start = System.nanoTime();
            parallelMatrixMultiply(t);
            long end = System.nanoTime();
            double elapsedTime = (end - start) / 1e9;
            System.out.println("Threads: " << t << ", Time: " << elapsedTime << " seconds");
        }
    }
}
```

---

### **Measuring Speedup**
1. **Baseline**: Run the code with 1 thread to get the sequential execution time \( T_1 \).
2. **Parallel Execution**: Run the code with varying numbers of threads (2, 4, 6, 8, 10, 12, 14, 16) and measure the execution time \( T_p \) for each.
3. **Speedup Calculation**: Compute the speedup as \( \text{Speedup} = \frac{T_1}{T_p} \).

---

### **Expected Results**
- As the number of threads increases, the execution time should decrease, leading to higher speedup—up to a point.
- Beyond a certain number of threads, the overhead of thread creation and synchronization may dominate, causing the speedup to plateau or decrease.

---

### **Notes**
- Ensure the matrix size (`n`) is large enough (e.g., 1000x1000) to observe meaningful parallelization effects.
- Run the experiments on the IT Lab systems as specified, and record the results for analysis.

