                // 读取H.264数据并解码显示
                try {
                    while (true) {
                        int bytesRead = socket.getInputStream().read(buffer.array());
                        if (bytesRead == -1) {
                            break; // 连接关闭
                        }

                        // 将ByteBuffer转换为BytePointer
                        BytePointer ptr = new BytePointer(buffer.array(), bytesRead);

                        // 创建FFmpegFrameGrabber用于解码H.264数据
                        FFmpegFrameGrabber grabber = new FFmpegFrameGrabber(ptr);
                        grabber.setFormat("h264");
                        grabber.start();

                        Frame frame;
                        while ((frame = grabber.grab()) != null) {
                            recorder.record(frame);
                        }

                        grabber.stop();
                        grabber.release();
                    }
                } catch (Exception e) {
                    e.printStackTrace();
                } finally {
                    recorder.stop();
                    recorder.release();
                }
            }
        }
    }
}
