Если вы хотите более гибкое и контролируемое взаимодействие с PowerShell, рассмотрите использование библиотеки JNA. Вот пример с использованием JNA для выполнения нескольких команд PowerShell:

```java
import com.sun.jna.platform.win32.Kernel32;
import com.sun.jna.platform.win32.WinNT;
import com.sun.jna.ptr.IntByReference;

public class PowerShellJNA {

    public static void main(String[] args) {
        String[] commands = {
            "Get-Process",
            "Get-Service",
            "Get-ChildItem -Path C:\\Windows"
        };

        try {
            // Создаем процесс PowerShell
            ProcessBuilder processBuilder = new ProcessBuilder("powershell.exe", "-Command", "-");
            processBuilder.redirectErrorStream(true);

            // Запускаем PowerShell
            Process process = processBuilder.start();

            // Получаем дескриптор процесса
            IntByReference pHandle = new IntByReference();
            Kernel32 kernel = Kernel32.INSTANCE;
            boolean result = kernel.GetExitCodeProcess(process.hashCode(), pHandle);

            // Выполняем команды по очереди
            for (String command : commands) {
                process.getOutputStream().write((command + "\n").getBytes());
                process.getOutputStream().flush();
            }

            // Закрываем поток ввода
            process.getOutputStream().close();

            // Читаем вывод команд
            BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
            String line;
            while ((line = reader.readLine()) != null) {
                System.out.println(line);
            }

            // Ждем завершения процесса
            process.waitFor();

        } catch (IOException | InterruptedException e) {
            e.printStackTrace();
        }
    }
}
```

