### Java代码实现

```java
import javax.swing.*;
import java.awt.*;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.net.ServerSocket;
import java.net.Socket;
import uk.co.caprica.vlcj.player.embedded.EmbeddedMediaPlayer;
import uk.co.caprica.vlcj.player.embedded.videosurface.callback.BufferFormat;
import uk.co.caprica.vlcj.player.embedded.videosurface.callback.BufferFormatCallback;
import uk.co.caprica.vlcj.player.embedded.videosurface.callback.RenderCallback;
import uk.co.caprica.vlcj.runtime.RuntimeUtil;

public class H264StreamReceiver extends JFrame implements Runnable, BufferFormatCallback, RenderCallback {

    private EmbeddedMediaPlayer mediaPlayer;
    private ServerSocket serverSocket;
    private volatile boolean running = true;
    private ByteArrayOutputStream frameBuffer = new ByteArrayOutputStream();

    public H264StreamReceiver() {
        // 初始化VLC媒体播放器
        mediaPlayer = new EmbeddedMediaPlayer.Builder()
                .videoSurface(this, this, this)
                .build();

        // 创建服务器Socket，监听指定端口
        try {
            serverSocket = new ServerSocket(8080);
        } catch (IOException e) {
            e.printStackTrace();
            System.exit(1);
        }

        // 启动接收线程
        new Thread(this).start();
    }

    @Override
    public void run() {
        try (Socket socket = serverSocket.accept();
             DataInputStream inputStream = new DataInputStream(socket.getInputStream())) {

            byte[] buffer = new byte[1024];
            int bytesRead;

            while (running && (bytesRead = inputStream.read(buffer)) != -1) {
                // 处理接收到的H.264帧数据
                handleH264Frame(buffer, bytesRead);
            }
        } catch (IOException e) {
            e.printStackTrace();
        } finally {
            // 关闭资源
            try {
                serverSocket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    private void handleH264Frame(byte[] buffer, int length) {
        // 这里假设H.264帧数据以NAL单元开头（0x00 0x00 0x00 0x01）
        // 实际应用中可能需要更复杂的解析逻辑
        frameBuffer.write(buffer, 0, length);

        // 查找NAL单元起始码
        int startCodeIndex = findStartCode(frameBuffer.toByteArray());
        if (startCodeIndex != -1) {
            byte[] frameData = frameBuffer.toByteArray();
            byte[] nalUnit = new byte[frameData.length - startCodeIndex];
            System.arraycopy(frameData, startCodeIndex, nalUnit, 0, nalUnit.length);

            // 清空缓冲区
            frameBuffer.reset();

            // 将NAL单元传递给VLC播放器
            mediaPlayer.playMedia("memory://", ":input-format=h264", ":input-slave=memory://");
            mediaPlayer.setMediaInput(nalUnit);
        }
    }

    private int findStartCode(byte[] data) {
        for (int i = 0; i < data.length - 3; i++) {
            if (data[i] == 0x00 && data[i + 1] == 0x00 && data[i + 2] == 0x00 && data[i + 3] == 0x01) {
                return i;
            }
        }
        return -1;
    }

