    public void display(MediaPlayer mediaPlayer, BufferFormat bufferFormat, byte[] bytes) {
        // 更新UI组件以显示视频帧
        // 这里省略具体实现，通常涉及到将字节数据绘制到JPanel或其他组件上
    }

