### 2. 配置Spring Security
在`SecurityConfig`类中配置Spring Security，包括登录、登出、Session管理和Remember Me功能。

```java
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configuration.WebSecurityConfigurerAdapter;
import org.springframework.security.web.authentication.rememberme.JdbcTokenRepositoryImpl;
import org.springframework.security.web.authentication.rememberme.PersistentTokenRepository;

import javax.sql.DataSource;

@Configuration
@EnableWebSecurity
public class SecurityConfig extends WebSecurityConfigurerAdapter {

    private final DataSource dataSource;

    public SecurityConfig(DataSource dataSource) {
        this.dataSource = dataSource;
    }

    @Override
    protected void configure(HttpSecurity http) throws Exception {
        http
            .authorizeRequests()
                .antMatchers("/public/**").permitAll()
                .anyRequest().authenticated()
                .and()
            .formLogin()
                .loginPage("/login")
                .permitAll()
                .and()
            .logout()
                .permitAll()
                .and()
            .sessionManagement()
                .maximumSessions(1) // 限制用户最多同时登录的Session数量
                .maxSessionsPreventsLogin(false) // 如果达到最大Session数，阻止新登录
                .expiredUrl("/login?expired") // Session过期后重定向的URL
                .and()
            .rememberMe()
                .tokenRepository(persistentTokenRepository())
                .tokenValiditySeconds(1209600) // Remember Me有效期，单位秒（14天）
                .key("uniqueAndSecret") // 用于加密Token的密钥
                .and()
            .csrf().disable(); // 根据需要启用或禁用CSRF保护
    }

    private PersistentTokenRepository persistentTokenRepository() {
        JdbcTokenRepositoryImpl tokenRepository = new JdbcTokenRepositoryImpl();
        tokenRepository.setDataSource(dataSource);
        // 如果表不存在，可以先创建表
        // tokenRepository.setCreateTableOnStartup(true);
        return tokenRepository;
    }
}
```

### 3. 配置Session超时时间
在`application.properties`或`application.yml`中配置Session的超时时间：

```properties
server.servlet.session.timeout=30m # Session超时时间，30分钟
