import java.nio.file.Paths;
import java.util.UUID;

@RestController
@RequestMapping("/api/files")
public class FileUploadController {

    @Value("${upload.path}")
    private String uploadPath;

    // Ограничение размера файла (например, 10 МБ)
    private static final long MAX_FILE_SIZE = 10 * 1024 * 1024;

    // Разрешенные типы файлов (например, изображения)
    private static final String[] ALLOWED_CONTENT_TYPES = {
        "image/jpeg",
        "image/png",
        "image/gif"
    };

    /**
     * Загрузка файла с проверкой размера, типа и сохранением на диск.
     *
     * @param file Загружаемый файл
     * @return Ответ с результатом загрузки
     */
    @PostMapping("/upload")
    public ResponseEntity<String> uploadFile(@RequestParam("file") MultipartFile file) {
        // Проверка наличия файла
        if (file.isEmpty()) {
            return ResponseEntity.badRequest().body("Файл не выбран");
        }

        // Проверка размера файла
        if (file.getSize() > MAX_FILE_SIZE) {
            return ResponseEntity.status(HttpStatus.PAYLOAD_TOO_LARGE)
                    .body("Превышен максимальный размер файла (10 МБ)");
        }

        // Проверка типа файла
        if (!isContentTypeAllowed(file.getContentType())) {
            return ResponseEntity.badRequest().body("Недопустимый тип файла");
        }

        // Генерация уникального имени файла
        String fileExtension = getFileExtension(file.getOriginalFilename());
        String uniqueFileName = UUID.randomUUID().toString() + fileExtension;

        try {
            // Сохранение файла на диск
            Path filePath = Paths.get(uploadPath, uniqueFileName);
            Files.copy(file.getInputStream(), filePath);

            // Возврат результат загрузки
            return ResponseEntity.ok("Файл успешно загружен: " + uniqueFileName);
        } catch (IOException e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                    .body("Ошибка при сохранении файла");
        }
    }

    /**
     * Проверка типа файла на соответствие разрешенным типам.
     *
     * @param contentType Тип файла
     * @return true, если тип файла разрешен, иначе false
     */
    private boolean isContentTypeAllowed(String contentType) {
        for (String allowedType : ALLOWED_CONTENT_TYPES) {
            if (allowedType.equals(contentType)) {
                return true;
            }
        }
        return false;
    }

    /**
     * Получение расширения файла из его имени.
     *
     * @param fileName Имя файла
     * @return Расширение файла (например, ".jpg")
     */
    private String getFileExtension(String fileName) {
        int extensionIndex = fileName.lastIndexOf(".");
        if (extensionIndex > 0) {
            return fileName.substring(extensionIndex);
        }
        return "";
    }
}
```

**Меры безопасности:**

1.  **Ограничение размера файла**: Предотвращает загрузку больших файлов, которые могут привести к переполнению памяти или атаке типа "Denial of Service" (DoS).
2.  **Проверка типа файла**: Разрешает только определенные типы файлов (например, изображения), предотвращая загрузку вредоносных файлов (например, исполняемых файлов).
3.  **Генерация уникального имени файла**: Предотвращает перезапись существующих файлов и потенциальные атаки типа "Path Traversal".
4.  **Валидация входных данных**: Проверяет наличие файла, его размер и тип перед сохранением.
5.  **Обработка ошибок**: Возвращает соответствующие коды состояния HTTP и сообщения об ошибках, не раскрывая внутреннюю информацию.

**Дополнительные рекомендации:**

*   Используйте HTTPS для шифрования данных при передаче.
*   Регулярно обновляйте зависимости и библиотеку Spring.
*   Проверяйте файлы на наличие вирусов с помощью антивирусного программного обеспечения.
*   Ограничьте доступ к загруженным файлам только для авторизованных пользователей.

Помните, что безопасность - это непрерывный процесс, и вам необходимо регулярно обновлять и тестировать свой код на наличие уязвимостей.

