import java.io.*;
import java.net.Socket;

public class Client {
    private Socket socket;
    private PrintWriter out;
    private BufferedReader in;
    private TicTacToeApp app;

    public Client(String host, int port, TicTacToeApp app) throws IOException {
        this.app = app;
        socket = new Socket(host, port);
        out = new PrintWriter(socket.getOutputStream(), true);
        in = new BufferedReader(new InputStreamReader(socket.getInputStream()));
        new Thread(this::listenForMessages).start();
    }

    public void sendMove(int row, int col) {
        out.println(row + "," + col);
    }

    private void listenForMessages() {
        try {
            while (true) {
                String message = in.readLine();
                if (message == null || message.equals("exit")) break;
                String[] parts = message.split(",");
                if (parts[0].equals("OPPONENT_MOVE")) {
                    Platform.runLater(() -> app.handleOpponentMove(Integer.parseInt(parts[1]), Integer.parseInt(parts[2])));
                } else if (parts[0].equals("WIN")) {
                    Platform.runLater(() -> app.showAlert("You Win!"));
                } else if (parts[0].equals("LOSE")) {
                    Platform.runLater(() -> app.showAlert("You Lose!"));
                } else if (parts[0].equals("DRAW")) {
                    Platform.runLater(() -> app.showAlert("It's a Draw!"));
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public void close() throws IOException {
        in.close();
        out.close();
        socket.close();
    }
}
