                  messageField.setText("");
              }
          });

          add(scrollPane, BorderLayout.CENTER);
          add(messageField, BorderLayout.SOUTH);
          add(sendButton, BorderLayout.EAST);

          try {
              client = new Client(serverAddress, serverPort);
              client.connect();
          } catch (IOException ex) {
              ex.printStackTrace();
          }
      }
  }
