import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.*;
import java.net.Socket;
import java.util.Base64;

public class UserClient {
    private JFrame frame;
    private JTextArea chatArea;
    private JTextField inputField;
    private JButton sendButton, sendImageButton;
    private Socket socket;
    private DataInputStream dis;
    private DataOutputStream dos;
    private String userId;

    public UserClient(String userId) {
        this.userId = userId;
        initializeUI();
        connectToServer();
    }

    private void initializeUI() {
        frame = new JFrame("用户端 - " + userId);
        frame.setSize(400, 500);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        frame.add(new JScrollPane(chatArea), BorderLayout.CENTER);

        inputField = new JTextField();
        sendButton = new JButton("发送");
        sendImageButton = new JButton("发送图片");

        JPanel bottomPanel = new JPanel();
        bottomPanel.setLayout(new BorderLayout());
        bottomPanel.add(inputField, BorderLayout.CENTER);
        bottomPanel.add(sendButton, BorderLayout.EAST);
        bottomPanel.add(sendImageButton, BorderLayout.WEST);

        frame.add(bottomPanel, BorderLayout.SOUTH);

        sendButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                sendMessage(inputField.getText());
                inputField.setText("");
            }
        });

        sendImageButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                JFileChooser fileChooser = new JFileChooser();
                int result = fileChooser.showOpenDialog(frame);
                if (result == JFileChooser.APPROVE_OPTION) {
                    File file = fileChooser.getSelectedFile();
                    sendImage(file);
                }
            }
        });

        frame.setVisible(true);
    }

    private void connectToServer() {
        try {
            socket = new Socket("localhost", 12345);
            dis = new DataInputStream(socket.getInputStream());
            dos = new DataOutputStream(socket.getOutputStream());

            new Thread(() -> {
                try {
                    while (true) {
                        String message = dis.readUTF();
                        if (message.startsWith("IMAGE:")) {
                            String base64Image = message.substring(6);
                            ImageIcon icon = new ImageIcon(Base64.getDecoder().decode(base64Image));
                            chatArea.append("客服: [图片]\n");
                            chatArea.insertIcon(icon);
                        } else if (message.startsWith("FILE:")) {
                            String fileName = message.substring(5);
                            receiveFile(fileName);
                        } else {
                            chatArea.append("客服: " + message + "\n");
                        }
                    }
                } catch (IOException e) {
                    chatArea.append("客服已断开连接\n");
                }
            }).start();

            dos.writeUTF("CONNECT:" + userId);
        } catch (IOException e) {
            JOptionPane.showMessageDialog(frame, "连接客服失败，客服忙!");
        }
    }

    private void sendMessage(String message) {
        try {
            dos.writeUTF("MESSAGE:" + message);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void sendImage(File file) {
        try {
            byte[] imageBytes = Files.readAllBytes(file.toPath());
            String base64Image = Base64.getEncoder().encodeToString(imageBytes);
            dos.writeUTF("IMAGE:" + base64Image);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void receiveFile(String fileName) {
        try {
            FileOutputStream fos = new FileOutputStream(fileName);
            byte[] buffer = new byte[4096];
            int bytesRead;
            while ((bytesRead = dis.read(buffer)) != -1) {
                fos.write(buffer, 0, bytesRead);
            }
            fos.close();
            chatArea.append("客服: 文件已接收 - " + fileName + "\n");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static void main(String[] args) {
        new UserClient("user1");
    }
}
```

