import java.util.Map;

public class SupportServer {
    private JFrame frame;
    private JTextArea activeUsersArea;
    private Map<String, ClientHandler> clients = new HashMap<>();

    public SupportServer() {
        initializeUI();
        startServer();
    }

    private void initializeUI() {
        frame = new JFrame("客服端");
        frame.setSize(400, 300);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setLayout(new BorderLayout());

        activeUsersArea = new JTextArea();
        activeUsersArea.setEditable(false);
        frame.add(new JScrollPane(activeUsersArea), BorderLayout.CENTER);

        JButton refreshButton = new JButton("刷新用户列表");
        refreshButton.addActionListener(new ActionListener() {
            @Override
            public void actionPerformed(ActionEvent e) {
                updateActiveUsers();
            }
        });

        frame.add(refreshButton, BorderLayout.SOUTH);
        frame.setVisible(true);
    }

    private void startServer() {
        new Thread(() -> {
            try (ServerSocket serverSocket = new ServerSocket(12345)) {
                while (true) {
                    Socket socket = serverSocket.accept();
                    DataInputStream dis = new DataInputStream(socket.getInputStream());
                    String userId = dis.readUTF().split(":")[1];
                    JOptionPane.showMessageDialog(frame, "新用户请求: " + userId);
                    int choice = JOptionPane.showConfirmDialog(frame, "是否接受用户 " + userId + " 的请求?");
                    if (choice == JOptionPane.YES_OPTION) {
                        ClientHandler handler = new ClientHandler(socket, userId);
                        clients.put(userId, handler);
                        updateActiveUsers();
                    } else {
                        socket.close();
                    }
                }
            } catch (IOException e) {
                e.printStackTrace();
            }
        }).start();
    }

    private void updateActiveUsers() {
        activeUsersArea.setText("");
        for (String userId : clients.keySet()) {
            activeUsersArea.append(userId + "\n");
        }
    }

    private class ClientHandler {
        private Socket socket;
        private String userId;
        private DataInputStream dis;
        private DataOutputStream dos;
        private JFrame chatFrame;
        private JTextArea chatArea;
        private JTextField inputField;

        public ClientHandler(Socket socket, String userId) {
            this.socket = socket;
            this.userId = userId;
            try {
                dis = new DataInputStream(socket.getInputStream());
                dos = new DataOutputStream(socket.getOutputStream());
                initializeChatUI();
                loadChatHistory();
                startListening();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void initializeChatUI() {
            chatFrame = new JFrame("聊天 - " + userId);
            chatFrame.setSize(400, 500);
