            chatArea.setEditable(false);
            chatFrame.add(new JScrollPane(chatArea), BorderLayout.CENTER);

            inputField = new JTextField();
            JButton sendButton = new JButton("发送");
            JButton sendFileButton = new JButton("发送文件");

            JPanel bottomPanel = new JPanel();
            bottomPanel.setLayout(new BorderLayout());
            bottomPanel.add(inputField, BorderLayout.CENTER);
            bottomPanel.add(sendButton, BorderLayout.EAST);
            bottomPanel.add(sendFileButton, BorderLayout.WEST);

            chatFrame.add(bottomPanel, BorderLayout.SOUTH);

            sendButton.addActionListener(new ActionListener() {
                @Override
                public void actionPerformed(ActionEvent e) {
                    sendMessage(inputField.getText());
                    inputField.setText("");
                }
            });

            sendFileButton.addActionListener(new ActionListener() {
                @Override
                public void actionPerformed(ActionEvent e) {
                    JFileChooser fileChooser = new JFileChooser();
                    int result = fileChooser.showOpenDialog(chatFrame);
                    if (result == JFileChooser.APPROVE_OPTION) {
                        File file = fileChooser.getSelectedFile();
                        sendFile(file);
                    }
                }
            });

            chatFrame.setVisible(true);
        }

        private void startListening() {
            new Thread(() -> {
                try {
                    while (true) {
                        String message = dis.readUTF();
                        if (message.startsWith("IMAGE:")) {
                            String base64Image = message.substring(6);
                            ImageIcon icon = new ImageIcon(Base64.getDecoder().decode(base64Image));
                            chatArea.append("用户: [图片]\n");
                            chatArea.insertIcon(icon);
                        } else {
                            chatArea.append("用户: " + message + "\n");
                        }
                        saveChatHistory();
                    }
                } catch (IOException e) {
                    chatArea.append("用户已断开连接\n");
                    clients.remove(userId);
                    updateActiveUsers();
                    chatFrame.dispose();
                }
            }).start();
        }

        private void sendMessage(String message) {
            try {
                dos.writeUTF("MESSAGE:" + message);
                chatArea.append("客服: " + message + "\n");
                saveChatHistory();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void sendFile(File file) {
            try {
                dos.writeUTF("FILE:" + file.getName());
                FileInputStream fis = new FileInputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    dos.write(buffer, 0, bytesRead);
                }
                fis.close();
                chatArea.append("客服: 文件已发送 - " + file.getName() + "\n");
                saveChatHistory();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void loadChatHistory() {
            File file = new File("chat_history_" + userId + ".txt");
            if (file.exists()) {
                try (BufferedReader br = new BufferedReader(new FileReader(file))) {
                    String line;
                    while ((line = br.readLine()) != null) {
                        chatArea.append(line + "\n");
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void saveChatHistory() {
            try (BufferedWriter bw = new BufferedWriter(new FileWriter("chat_history_" + userId + ".txt", true))) {
                bw.write(chatArea.getText());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        new SupportServer();
    }
}
