```java
import javax.swing.*;
import java.awt.*;
import java.awt.event.KeyEvent;
import java.awt.event.KeyListener;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.io.*;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class MouseRecorderReplayer implements KeyListener {

    private boolean isRecording = false;
    private List<Point> recordedMovements = new ArrayList<>();
    private Thread replayThread;
    private Map<String, List<Point>> recordings = new HashMap<>();
    private JTable table;
    private JFrame frame;
    private int screenWidth;
    private int screenHeight;

    public MouseRecorderReplayer() {
        screenWidth = Toolkit.getDefaultToolkit().getScreenSize().width;
        screenHeight = Toolkit.getDefaultToolkit().getScreenSize().height;

        // Initialize GUI
        frame = new JFrame("Mouse Recorder & Replayer");
        frame.setSize(600, 400);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);

        // Load recordings from file
        loadRecordings();

        // Initialize table
        String[] columnNames = {"Recording Name"};
        String[][] data = recordings.keySet().stream().map(name -> new String[]{name}).toArray(String[][]::new);
        table = new JTable(data, columnNames);
        JScrollPane scrollPane = new JScrollPane(table);
        frame.add(scrollPane, BorderLayout.CENTER);

        // Add mouse listener for replay
        table.addMouseListener(new MouseAdapter() {
            @Override
            public void mouseClicked(MouseEvent e) {
                int row = table.rowAtPoint(e.getPoint());
                if (row >= 0) {
                    String recordingName = (String) table.getValueAt(row, 0);
                    replayRecording(recordings.get(recordingName));
                }
            }
        });

        frame.addKeyListener(this);
        frame.setFocusable(true);
        frame.setVisible(true);
    }

    private void loadRecordings() {
        File file = new File("recordings.dat");
        if (file.exists()) {
            try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
                recordings = (Map<String, List<Point>>) ois.readObject();
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
            }
        }
    }

    private void saveRecordings() {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream("recordings.dat"))) {
            oos.writeObject(recordings);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private void startRecording() {
        isRecording = true;
        recordedMovements.clear();
        JOptionPane.showMessageDialog(frame, "Recording started. Press Shift + L to stop.");
    }

    private void stopRecording() {
        isRecording = false;
        String recordingName = JOptionPane.showInputDialog(frame, "Enter recording name:");
        if (recordingName != null && !recordingName.isEmpty()) {
            recordings.put(recordingName, new ArrayList<>(recordedMovements));
            saveRecordings();
            updateTable();
        }
    }

    private void updateTable() {
        String[][] data = recordings.keySet().stream().map(name -> new String[]{name}).toArray(String[][]::new);
        table.setModel(new javax.swing.table.DefaultTableModel(data, new String[]{"Recording Name"}));
    }

    private void replayRecording(List<Point> movements) {
        if (replayThread != null && replayThread.isAlive()) {
            return; // Prevent multiple replays
        }

        replayThread = new Thread(() -> {
            for (Point point : movements) {
                Robot robot;
                try {
                    robot = new Robot();
                    robot.mouseMove(point.x, point.y);
                    Thread.sleep(50); // Adjust speed as needed
                } catch (AWTException | InterruptedException e) {
                    e.printStackTrace();
                }
            }
        });
        replayThread.start();
    }

    @Override
    public void keyPressed(KeyEvent e) {
        if (e.isShiftDown()) {
            if (e.getKeyCode() == KeyEvent.VK_P) {
                startRecording();
            } else if (e.getKeyCode() == KeyEvent.VK_L) {
                stopRecording();
            }
        }
    }

    @Override
    public void keyReleased(KeyEvent e) {}

    @Override
    public void keyTyped(KeyEvent e) {}

    public static void main(String[] args) {
        new MouseRecorderReplayer();
    }
}
```

### Explanation:
1. **Recording and Replaying**:
   - Mouse movements are recorded when `Shift + P` is pressed and stopped with `Shift + L`.
   - Recordings are stored in a `HashMap` with a user-defined name as the key.
   - Recordings are saved to a file (`recordings.dat`) using serialization.

2. **GUI Table**:
   - A `JTable` displays all saved recordings.
   - Clicking on a recording in the table replays the mouse movements.

3. **Thread for Replay**:
   - A separate thread is used for replaying mouse movements to avoid blocking the UI.

4. **Screen Size Detection**:
   - Screen dimensions are detected using `Toolkit.getDefaultToolkit().getScreenSize()`.

5. **Serialization**:
   - Recordings are serialized to a file for persistence across application runs.

### Notes:
- Ensure the application has permission to use `Robot` for mouse control.
- Adjust the replay speed by modifying the `Thread.sleep()` duration in the `replayRecording` method.
- Handle exceptions and edge cases as needed for production use.

