import javax.net.ssl.SSLServerSocketFactory;
import javax.net.ssl.SSLSocket;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;

public class SecureH264Receiver {
    private static final int PORT = 12345;
    private static final String OUTPUT_FILE = "output.h264";
    private static final int MAX_CLIENTS = 10;

    public static void main(String[] args) {
        try {
            // 使用SSL加密通信
            System.setProperty("javax.net.ssl.keyStore", "keystore.jks");
            System.setProperty("javax.net.ssl.keyStorePassword", "password");
            SSLServerSocketFactory sslServerSocketFactory = (SSLServerSocketFactory) SSLServerSocketFactory.getDefault();
            try (ServerSocket serverSocket = sslServerSocketFactory.createServerSocket(PORT)) {
                System.out.println("Secure server started. Waiting for clients...");
                int clientCount = 0;
                while (clientCount < MAX_CLIENTS) {
                    try (SSLSocket clientSocket = (SSLSocket) serverSocket.accept();
                         FileOutputStream fos = new FileOutputStream(OUTPUT_FILE, true)) {

                        clientCount++;
                        byte[] buffer = new byte[1024];
                        InputStream is = clientSocket.getInputStream();
                        int bytesRead;
                        while ((bytesRead = is.read(buffer)) != -1) {
                            // 简单的数据验证（检查NAL单元起始码）
                            if (!isValidH264NALUnit(buffer, bytesRead)) {
                                System.err.println("Invalid H.264 data received. Discarding.");
                                break;
                            }
                            fos.write(buffer, 0, bytesRead);
                        }
                        System.out.println("Data received and saved to " + OUTPUT_FILE);
                    } catch (IOException e) {
                        System.err.println("Error handling client: " + e.getMessage());
                    } finally {
                        clientCount--;
                    }
                }
            }
        } catch (IOException e) {
            System.err.println("Server error: " + e.getMessage());
        }
    }

    private static boolean isValidH264NALUnit(byte[] buffer, int length) {
        // 简单验证NAL单元起始码
        if (length < 3) return false;
        return (buffer[0] == 0x00 && buffer[1] == 0x00 && buffer[2] == 0x01) ||
               (length < 4) || (buffer[0] == 0x00 && buffer[1] == 0x00 && buffer[2] == 0x00 && buffer[3] == 0x01);
    }
}
