Ниже приведен пример простого сетевого чата на Java, использующего TCP для связи. Этот пример включает в себя два класса: `ChatServer` и `ChatClient`.

**ChatServer.java**
```java
import java.io.*;
import java.net.*;
import java.util.*;

public class ChatServer {
    private int port;
    private Set<String> userNames = new HashSet<>();
    private Set<UserThread> userThreads = new HashSet<>();

    public ChatServer(int port) {
        this.port = port;
    }

    public void execute() {
        try (ServerSocket serverSocket = new ServerSocket(port)) {
            System.out.println("Chat Server is listening on port " + port);

            while (true) {
                Socket socket = serverSocket.accept();
                UserThread userThread = new UserThread(socket, this);
                userThreads.add(userThread);
                userThread.start();
            }
        } catch (IOException ex) {
            System.out.println("Error in the server: " + ex.getMessage());
            ex.printStackTrace();
        }
    }

    public void broadcast(String message, UserThread excludeUser) {
        for (UserThread user : userThreads) {
            if (user != excludeUser) {
                user.sendMessage(message);
            }
        }
    }

    public void removeUser(UserThread userThread) {
        userNames.remove(userThread.getUsername());
        userThreads.remove(userThread);
    }

    public boolean hasUsers() {
        return !userThreads.isEmpty();
    }

    public boolean hasUserName(String userName) {
        return userNames.contains(userName);
    }

    public void addUserName(String userName) {
        userNames.add(userName);
    }

    public static void main(String[] args) {
        if (args.length < 1) {
            System.out.println("Syntax: java ChatServer <port-number>");
            System.exit(0);
        }

        int port = Integer.parseInt(args[0]);

        ChatServer server = new ChatServer(port);
        server.execute();
    }
}

class UserThread extends Thread {
    private Socket socket;
    private ChatServer server;
    private PrintWriter writer;

    public UserThread(Socket socket, ChatServer server) {
        this.socket = socket;
        this.server = server;
    }

    public void run() {
        try {
            InputStream input = socket.getInputStream();
            BufferedReader reader = new BufferedReader(new InputStreamReader(input));

            OutputStream output = socket.getOutputStream();
            writer = new PrintWriter(output, true);

            writer.println("Please enter your name:");
            String userName = reader.readLine();

            if (server.hasUserName(userName)) {
                writer.println("The user name " + userName + " is already taken.");
                writer.println("Please enter another user name:");
                userName = reader.readLine();
            }

            server.addUserName(userName);

            String serverMessage = "New user connected: " + userName;
            server.broadcast(serverMessage, this);

            String clientMessage;

            do {
                clientMessage = reader.readLine();
                serverMessage = "[" + userName + "]: " + clientMessage;
                server.broadcast(serverMessage, this);
            } while (!clientMessage.equals("bye"));

            server.removeUser(this);
            socket.close();

            serverMessage = userName + " has left the chat.";
            server.broadcast(serverMessage, this);

