```java
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;
import org.springframework.data.redis.connection.lettuce.LettuceConnectionFactory;
import org.springframework.data.redis.core.RedisTemplate;
import org.springframework.data.redis.serializer.GenericJackson2JsonRedisSerializer;
import org.springframework.data.redis.serializer.StringRedisSerializer;

@Configuration
public class RedisConfig {

    @Value("${spring.redis.host}")
    private String redisHost;

    @Value("${spring.redis.port}")
    private int redisPort;

    @Bean
    public RedisConnectionFactory redisConnectionFactory() {
        return new LettuceConnectionFactory(redisHost, redisPort);
    }

    @Bean
    public RedisTemplate<String, Object> redisTemplate(RedisConnectionFactory connectionFactory) {
        RedisTemplate<String, Object> template = new RedisTemplate<>();
        template.setConnectionFactory(connectionFactory);
        template.setKeySerializer(new StringRedisSerializer());
        template.setValueSerializer(new GenericJackson2JsonRedisSerializer());
        return template;
    }
}
```

#### **Rate Limiting Configuration**
Create a Bucket4j configuration class:

```java
import io.github.bucket4j.Bandwidth;
import io.github.bucket4j.Bucket;
import io.github.bucket4j.Bucket4j;
import io.github.bucket4j.grid.jcache.JCacheProxyManager;
import io.github.bucket4j.redis.cas.RedisProxyManager;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.data.redis.connection.RedisConnectionFactory;

import java.time.Duration;

@Configuration
public class RateLimitingConfig {

    @Value("${rate-limiting.capacity}")
    private int capacity;

    @Value("${rate-limiting.refill-tokens}")
    private int refillTokens;

    @Value("${rate-limiting.refill-interval}")
    private int refillInterval;

    @Value("${rate-limiting.interval-unit}")
    private String intervalUnit;

    private final RedisConnectionFactory redisConnectionFactory;

    public RateLimitingConfig(RedisConnectionFactory redisConnectionFactory) {
        this.redisConnectionFactory = redisConnectionFactory;
    }

    @Bean
    public RedisProxyManager<String> redisProxyManager() {
        return RedisProxyManager.builderFor(redisConnectionFactory).build();
    }

    @Bean
    public Bucket bucket(RedisProxyManager<String> redisProxyManager) {
        Bandwidth bandwidth = Bandwidth.classic(capacity, Duration.ofSeconds(refillInterval));
        return Bucket4j.builder()
                .addLimit(bandwidth)
                .build(redisProxyManager.proxy("my-rate-limit", Bandwidth.classic(capacity, Duration.ofSeconds(refillInterval))));
    }
}
```

