### Java Code:

```java
import javax.mail.*;
import javax.mail.internet.InternetAddress;
import javax.mail.internet.MimeMessage;
import javax.mail.search.SubjectTerm;
import java.util.Hashtable;
import java.util.Properties;

public class ImapMailFetcher {

    private static final String IMAP_HOST = "imap.example.com"; // Replace with your IMAP server
    private static final String USERNAME = "your_username";    // Replace with your email username
    private static final String PASSWORD = "your_password";    // Replace with your email password

    public static void main(String[] args) {
        Hashtable<String, String> emailData = new Hashtable<>();

        try {
            // Set up IMAP properties
            Properties props = new Properties();
            props.put("mail.imap.host", IMAP_HOST);
            props.put("mail.imap.port", "993"); // Use 143 for non-SSL
            props.put("mail.imap.ssl.enable", "true"); // Set to false for non-SSL

            // Create a session
            Session session = Session.getInstance(props, null);
            Store store = session.getStore("imaps"); // Use "imap" for non-SSL
            store.connect(IMAP_HOST, USERNAME, PASSWORD);

            // Open the inbox folder
            Folder inbox = store.getFolder("INBOX");
            inbox.open(Folder.READ_ONLY);

            // Search for emails with a subject containing "number"
            Message[] messages = inbox.search(new SubjectTerm("number"));

            // Process each message
            for (Message message : messages) {
                if (message instanceof MimeMessage) {
                    MimeMessage mimeMessage = (MimeMessage) message;
                    String subject = mimeMessage.getSubject();
                    String from = InternetAddress.toString(mimeMessage.getFrom());
                    String content = getTextFromMessage(mimeMessage);

                    // Extract the "number" from the subject (e.g., "Your number: 12345678")
                    String number = extractNumberFromSubject(subject);

                    if (number != null && content != null) {
                        emailData.put(number, content);
                    }
                }
            }

            // Close the folder and store
            inbox.close(false);
            store.close();

            // Print the results
            for (String key : emailData.keySet()) {
                System.out.println("Number: " + key + ", Message: " + emailData.get(key));
            }

        } catch (Exception e) {
            e.printStackTrace();
        }
    }

    private static String getTextFromMessage(MimeMessage mimeMessage) throws Exception {
        if (mimeMessage.isMimeType("text/plain")) {
            return mimeMessage.getContent().toString();
        } else {
            return "Unsupported message type";
        }
    }

    private static String extractNumberFromSubject(String subject) {
        // Simple extraction logic: assumes the number follows "number:"
        int index = subject.indexOf("number:");
        if (index != -1) {
            String numberStr = subject.substring(index + "number:".length()).trim();
            if (numberStr.matches("\\d+")) {
                return numberStr;
            }
        }
        return null;
    }
}
```

### Explanation:
1. **IMAP Connection**: The code connects to an IMAP server using SSL (`imaps`). Replace the `IMAP_HOST`, `USERNAME`, and `PASSWORD` with your email credentials.
2. **Email Search**: It searches for emails with a subject containing the word "number".
3. **Data Extraction**: The subject is parsed to extract the "number" (e.g., `"12345678"`), and the email content is stored in a `Hashtable` with the number as the key.
