                            DHPublicKeyParameters serverDHParams = dhKeyExchange.getAgreedDHParameters();

                            System.out.println("Server's DH Parameters:");
                            System.out.println("P (Prime): " + serverDHParams.getP().toString(16));
                            System.out.println("G (Generator): " + serverDHParams.getG().toString(16));
                        } else {
