import javax.crypto.Cipher;
import javax.crypto.KeyGenerator;
import javax.crypto.SecretKey;
import javax.crypto.spec.GCMParameterSpec;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

public class NFCEncryption {
    public static void main(String[] args) throws Exception {
        // Encryption Key (32 bytes for AES-256)
        byte[] key = "0123456789abcdef0123456789abcdef".getBytes(StandardCharsets.UTF_8); // Replace with a secure key

        // Plaintext Data
        String plaintext = "A0123456|99999|XYZ";

        // Generate a random 12-byte nonce
        byte[] nonce = new byte[12];
        new java.security.SecureRandom().nextBytes(nonce);

        // Encrypt the data using AES-256-GCM
        Cipher cipher = Cipher.getInstance("AES/GCM/NoPadding");
        SecretKeySpec keySpec = new SecretKeySpec(key, "AES");
        GCMParameterSpec gcmParameterSpec = new GCMParameterSpec(128, nonce); // 128-bit tag
        cipher.init(Cipher.ENCRYPT_MODE, keySpec, gcmParameterSpec);
        byte[] ciphertext = cipher.doFinal(plaintext.getBytes(StandardCharsets.UTF_8));

        // Get the authentication tag
        byte[] tag = cipher.getTag();

        // Combine nonce, ciphertext, and tag
        byte[] encryptedData = new byte[nonce.length + ciphertext.length + tag.length];
        System.arraycopy(nonce, 0, encryptedData, 0, nonce.length);
        System.arraycopy(ciphertext, 0, encryptedData, nonce.length, ciphertext.length);
        System.arraycopy(tag, 0, encryptedData, nonce.length + ciphertext.length, tag.length);

        // Check size (must be <= 136 bytes)
        if (encryptedData.length > 136) {
            throw new Exception("Encrypted data exceeds 136 bytes.");
        }

        // Write encryptedData to NFC chip
        System.out.println("Encrypted Data (Base64): " + Base64.getEncoder().encodeToString(encryptedData));
    }
}
