@Service
public class CaptchaService {
    private static final String CAPTCHA_KEY = "captcha:";
    private final RedisTemplate<String, String> redisTemplate;

    @Autowired
    public CaptchaService(RedisTemplate<String, String> redisTemplate) {
        this.redisTemplate = redisTemplate;
    }

    public String generateCaptcha() {
        // 生成验证码逻辑
        String captcha = "1234"; // 替换为实际验证码生成逻辑
        String key = CAPTCHA_KEY + UUID.randomUUID();
        redisTemplate.opsForValue().set(key, captcha, 5, TimeUnit.MINUTES);
        return key;
    }

    public boolean validateCaptcha(String key, String userInput) {
        String storedCaptcha = redisTemplate.opsForValue().get(CAPTCHA_KEY + key);
        if (storedCaptcha == null || !storedCaptcha.equals(userInput)) {
            return false;
        }
        redisTemplate.delete(CAPTCHA_KEY + key);
        return true;
    }
}
