@RestController
@RequestMapping("/api/auth")
public class AuthController {

    @Autowired
    private UserService userService;

    @Autowired
    private CaptchaService captchaService;

    @Autowired
    private JwtTokenProvider tokenProvider;

    @PostMapping("/login")
    public ResponseEntity<?> login(@RequestBody LoginRequest request) {
        // 1. 参数校验
        if (request.getTimestamp() < System.currentTimeMillis() - 5 * 60 * 1000) {
            return ResponseEntity.badRequest().body("请求过期");
        }

        // 2. 验证码校验
        if (!captchaService.validateCaptcha(request.getCaptchaKey(), request.getCaptcha())) {
            return ResponseEntity.badRequest().body("验证码错误");
        }

        // 3. 用户认证
        User user = userService.findByUsername(request.getUsername());
        if (user == null || !passwordEncoder.matches(request.getPassword(), user.getPassword())) {
            return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("用户名或密码错误");
        }

        // 4. 生成JWT令牌
        String token = tokenProvider.generateToken(user);

        // 5. 返回结果
        return ResponseEntity.ok(new LoginResponse(token, 3600));
    }
}
