import javax.swing.*;
import java.awt.*;
import java.awt.event.ActionEvent;
import java.awt.event.ActionListener;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;

public class ServerGUI extends JFrame {
    private JTextArea chatArea;
    private JButton acceptButton, rejectButton, sendFileButton;
    private ServerSocket serverSocket;
    private Map<String, ClientHandler> clients = new HashMap<>();

    public ServerGUI() {
        setTitle("客服端");
        setSize(400, 500);
        setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        setLayout(new BorderLayout());

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        add(new JScrollPane(chatArea), BorderLayout.CENTER);

        acceptButton = new JButton("接受");
        rejectButton = new JButton("拒绝");
        sendFileButton = new JButton("发送文件");

        JPanel bottomPanel = new JPanel();
        bottomPanel.add(acceptButton);
        bottomPanel.add(rejectButton);
        bottomPanel.add(sendFileButton);
        add(bottomPanel, BorderLayout.SOUTH);

        try {
            serverSocket = new ServerSocket(1234);
            new Thread(() -> {
                while (true) {
                    try {
                        Socket socket = serverSocket.accept();
                        String clientId = socket.getInetAddress().getHostAddress();
                        chatArea.append("新用户连接: " + clientId + "\n");
                        clients.put(clientId, new ClientHandler(socket, clientId));
                    } catch (IOException e) {
                        e.printStackTrace();
                    }
                }
            }).start();
        } catch (IOException e) {
            e.printStackTrace();
        }

        acceptButton.addActionListener(e -> handleClient(true));
        rejectButton.addActionListener(e -> handleClient(false));
        sendFileButton.addActionListener(e -> sendFile());
    }

    private void handleClient(boolean accept) {
        String clientId = (String) JOptionPane.showInputDialog(this, "输入用户ID:");
        ClientHandler handler = clients.get(clientId);
        if (handler != null) {
            if (accept) {
                handler.startChat();
                chatArea.append("接受用户: " + clientId + "\n");
            } else {
                handler.rejectChat();
                chatArea.append("拒绝用户: " + clientId + "\n");
            }
        }
    }

    private void sendFile() {
        String clientId = (String) JOptionPane.showInputDialog(this, "输入用户ID:");
        ClientHandler handler = clients.get(clientId);
        if (handler != null) {
            JFileChooser fileChooser = new JFileChooser();
            if (fileChooser.showOpenDialog(this) == JFileChooser.APPROVE_OPTION) {
                File file = fileChooser.getSelectedFile();
                handler.sendFile(file);
            }
        }
    }

    private class ClientHandler {
        private Socket socket;
        private String clientId;
        private DataInputStream dis;
        private DataOutputStream dos;
        private boolean isAccepted = false;

        public ClientHandler(Socket socket, String clientId) {
            this.socket = socket;
            this.clientId = clientId;
            try {
                dis = new DataInputStream(socket.getInputStream());
                dos = new DataOutputStream(socket.getOutputStream());
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void startChat() {
            isAccepted = true;
            new Thread(() -> {
                try {
                    while (true) {
                        String msg = dis.readUTF();
                        if (msg.startsWith("IMAGE:")) {
                            String fileName = msg.substring(6);
                            chatArea.append(clientId + " 发送了图片: " + fileName + "\n");
                            receiveImage(fileName);
                        } else {
                            chatArea.append(clientId + ": " + msg + "\n");
                            saveChat(clientId, "客服: " + msg);
                        }
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }).start();
        }

        public void rejectChat() {
            try {
                dos.writeUTF("客服忙，请稍后再试。");
                socket.close();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public void sendFile(File file) {
            try {
                dos.writeUTF("FILE:" + file.getName());
                FileInputStream fis = new FileInputStream(file);
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = fis.read(buffer)) != -1) {
                    dos.write(buffer, 0, bytesRead);
