```java
import org.apache.doris.udf.ScalarFunction;
import org.apache.doris.udf.FunctionContext;
import org.dom4j.*;
import javax.xml.parsers.DocumentBuilderFactory;
import org.w3c.dom.Document;
import org.w3c.dom.NodeList;
import java.io.ByteArrayInputStream;
import java.nio.charset.StandardCharsets;

public class XmlParserUDF extends ScalarFunction {

    @Override
    public String evaluate(String xmlString, String xpath) {
        try {
            // 使用 DOM4J 解析 XML
            Document document = DocumentBuilderFactory.newInstance().newDocumentBuilder()
                    .parse(new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8)));

            // 执行 XPath 查询
            NodeList nodes = (NodeList) document.evaluate(xpath, document, null, XPathResult.ORDERED_NODE_SNAPSHOT_TYPE, null);
            if (nodes.getLength() > 0) {
                return nodes.item(0).getTextContent();
            }
            return null;
        } catch (Exception e) {
            throw new RuntimeException("XML parsing failed: " + e.getMessage());
        }
    }
}
```

