```java
import org.apache.doris.udf.ScalarFunction;
import org.dom4j.Document;
import org.dom4j.DocumentException;
import org.dom4j.Node;
import org.dom4j.io.SAXReader;

public class XmlParserUDF extends ScalarFunction {

    private SAXReader reader = new SAXReader();

    @Override
    public String evaluate(String xmlString, String xpath) {
        try {
            Document document = reader.read(new ByteArrayInputStream(xmlString.getBytes(StandardCharsets.UTF_8)));
            Node node = document.selectSingleNode(xpath);
            return node != null ? node.getText() : null;
        } catch (DocumentException e) {
            throw new RuntimeException("XML parsing failed: " + e.getMessage());
        }
    }
}
