        inputField.addActionListener(e -> sendMessage(inputField.getText()));

        JButton sendButton = new JButton("发送");
        sendButton.addActionListener(e -> sendMessage(inputField.getText()));

        JButton sendImageButton = new JButton("发送图片");
        sendImageButton.addActionListener(e -> sendImage());

        JPanel panel = new JPanel();
        panel.add(inputField);
        panel.add(sendButton);
        panel.add(sendImageButton);

        frame.add(scrollPane, BorderLayout.CENTER);
        frame.add(panel, BorderLayout.SOUTH);
        frame.setVisible(true);
    }

    private void connectToServer() {
        try {
            socket = new Socket("localhost", 12345);
            out = new ObjectOutputStream(socket.getOutputStream());
            in = new ObjectInputStream(socket.getInputStream());

            ExecutorService executor = Executors.newSingleThreadExecutor();
            executor.submit(() -> {
                try {
                    while (true) {
                        Message message = (Message) in.readObject();
                        if (message.getType() == Message.TEXT) {
                            chatArea.append("客服: " + message.getContent() + "\n");
                        } else if (message.getType() == Message.STATUS) {
                            chatArea.append("系统: " + message.getContent() + "\n");
