import javax.swing.*;
import java.awt.*;
import java.io.*;
import java.net.ServerSocket;
import java.net.Socket;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Server {
    private JFrame frame;
    private JTextArea chatArea;
    private Map<String, ClientHandler> clients = new HashMap<>();
    private ExecutorService executor = Executors.newCachedThreadPool();

    public Server() {
        initializeUI();
        startServer();
    }

    private void initializeUI() {
        frame = new JFrame("客服端");
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setSize(600, 500);

        chatArea = new JTextArea();
        chatArea.setEditable(false);
        JScrollPane scrollPane = new JScrollPane(chatArea);

        frame.add(scrollPane, BorderLayout.CENTER);
        frame.setVisible(true);
    }

    private void startServer() {
        try (ServerSocket serverSocket = new ServerSocket(12345)) {
            while (true) {
                Socket socket = serverSocket.accept();
                ClientHandler handler = new ClientHandler(socket);
                clients.put(handler.getUserId(), handler);
                executor.submit(handler);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    private class ClientHandler implements Runnable {
        private Socket socket;
        private ObjectOutputStream out;
        private ObjectInputStream in;
        private String userId;

        public ClientHandler(Socket socket) {
            this.socket = socket;
            try {
                out = new ObjectOutputStream(socket.getOutputStream());
                in = new ObjectInputStream(socket.getInputStream());
                userId = "user" + (clients.size() + 1);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        public String getUserId() {
            return userId;
        }

        @Override
        public void run() {
            try {
                chatArea.append("新用户连接: " + userId + "\n");
                loadChatHistory(userId);

                while (true) {
                    Message message = (Message) in.readObject();
                    if (message.getType() == Message.TEXT) {
                        chatArea.append(userId + ": " + message.getContent() + "\n");
                        saveChatHistory(userId, "User: " + message.getContent());
                        sendMessage(userId, "客服: 已收到您的消息");
                    } else if (message.getType() == Message.IMAGE) {
                        chatArea.append(userId + ": [图片] " + message.getFilename() + "\n");
                        saveChatHistory(userId, "User: [图片] " + message.getFilename());
                    }
                }
            } catch (IOException | ClassNotFoundException e) {
                e.printStackTrace();
                clients.remove(userId);
                chatArea.append("用户断开连接: " + userId + "\n");
            }
        }

        private void sendMessage(String userId, String text) {
            try {
                Message message = new Message();
                message.setType(Message.TEXT);
                message.setContent(text);
                out.writeObject(message);
                out.flush();
                saveChatHistory(userId, "Server: " + text);
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void loadChatHistory(String userId) {
            File file = new File("chat_history_" + userId + ".txt");
            if (file.exists()) {
                try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
                    String line;
                    while ((line = reader.readLine()) != null) {
                        chatArea.append(line + "\n");
                    }
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
        }

        private void saveChatHistory(String userId, String message) {
            try (BufferedWriter writer = new BufferedWriter(new FileWriter("chat_history_" + userId + ".txt", true))) {
                writer.write(message + "\n");
            } catch (IOException e) {
                e.printStackTrace();
            }
        }
    }

    public static void main(String[] args) {
        new Server();
    }
}
