                int pivotIndex = partition(start, end, arr);

                // Divide array
                QuickSortMultiThreading left = new QuickSortMultiThreading(start, pivotIndex - 1, arr);
                QuickSortMultiThreading right = new QuickSortMultiThreading(pivotIndex + 1, end, arr);

                // Left subproblem as separate task
                left.fork();
                right.compute();

                // Wait until left task completes
                left.join();
            }
        }
        return null;
    }

    private void sequentialQuickSort(int start, int end) {
        if (start < end) {
            int pivotIndex = partition(start, end, arr);
            sequentialQuickSort(start, pivotIndex - 1);
            sequentialQuickSort(pivotIndex + 1, end);
        }
    }

