public class SSLPinningTrustManager implements X509TrustManager {
    private final Set<PublicKey> pinnedKeys;

    public SSLPinningTrustManager(Set<PublicKey> pinnedKeys) {
        this.pinnedKeys = pinnedKeys;
    }

    @Override
    public void checkClientTrusted(X509Certificate[] chain, String authType) throws CertificateException {
        throw new UnsupportedOperationException();
    }

    @Override
    public void checkServerTrusted(X509Certificate[] chain, String authType) throws CertificateException {
        if (chain == null || chain.length == 0) {
            throw new CertificateException("Certificate chain is empty");
        }

        X509Certificate serverCert = chain[0];
        PublicKey serverKey = serverCert.getPublicKey();

        if (!pinnedKeys.contains(serverKey)) {
            throw new CertificateException("Server certificate public key is not pinned");
        }

        // Verify the certificate chain using the default trust manager
        TrustManagerFactory tmf = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm());
        tmf.init((KeyStore) null);
        X509TrustManager defaultTm = null;
        for (TrustManager tm : tmf.getTrustManagers()) {
            if (tm instanceof X509TrustManager) {
                defaultTm = (X509TrustManager) tm;
                break;
            }
        }
        if (defaultTm != null) {
            defaultTm.checkServerTrusted(chain, authType);
        }
    }

    @Override
    public X509Certificate[] getAcceptedIssuers() {
        return new X509Certificate[0];
    }
}
