class MiniDB implements Serializable {
    private Hashtable<String, String> database;

    public MiniDB() {
        this.database = new Hashtable<>();
    }

    // Insert or update a key-value pair
    public void put(String key, String value) {
        database.put(key, value);
    }

    // Retrieve a value by key
    public String get(String key) {
        return database.get(key);
    }

    // Delete a key-value pair
    public void delete(String key) {
        database.remove(key);
    }

    // Save the database to a file using serialization
    public void saveToFile(String filename) throws IOException {
        try (ObjectOutputStream oos = new ObjectOutputStream(new FileOutputStream(filename))) {
            oos.writeObject(this);
            System.out.println("Database saved to " + filename);
        }
    }

    // Load the database from a file using serialization
    public static MiniDB loadFromFile(String filename) throws IOException, ClassNotFoundException {
        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(filename))) {
            MiniDB db = (MiniDB) ois.readObject();
            System.out.println("Database loaded from " + filename);
            return db;
        }
    }

    // Display all key-value pairs
    public void display() {
        for (String key : database.keySet()) {
