        return "Student ID: " + studentId + ", Name: " + name + ", Course: " + course + ", GPA: " + gpa;
    }
}

// StudentManagementSystem class using generics and collections
class StudentManagementSystem {
    private Map<String, Student> studentMap; // Map to store students by ID

    public StudentManagementSystem() {
        this.studentMap = new HashMap<>();
    }

    // Add a student record
    public void addStudent(Student student) {
        if (studentMap.containsKey(student.getStudentId())) {
            System.out.println("Student with ID " + student.getStudentId() + " already exists.");
        } else {
            studentMap.put(student.getStudentId(), student);
            System.out.println("Student added successfully.");
        }
    }

    // Remove a student record
    public void removeStudent(String studentId) {
        if (studentMap.containsKey(studentId)) {
            studentMap.remove(studentId);
            System.out.println("Student with ID " + studentId + " removed successfully.");
        } else {
            System.out.println("Student with ID " + studentId + " not found.");
        }
    }

    // Update a student record
    public void updateStudent(String studentId, String course, double gpa) {
        if (studentMap.containsKey(studentId)) {
            Student student = studentMap.get(studentId);
            student.setCourse(course);
            student.setGpa(gpa);
            System.out.println("Student with ID " + studentId + " updated successfully.");
        } else {
            System.out.println("Student with ID " + studentId + " not found.");
        }
    }

    // Search for a student by ID
    public Student searchStudentById(String studentId) {
        return studentMap.getOrDefault(studentId, null);
    }

    // Search for students by name (case-insensitive)
    public List<Student> searchStudentByName(String name) {
        List<Student> result = new ArrayList<>();
        for (Student student : studentMap.values()) {
            if (student.getName().toLowerCase().contains(name.toLowerCase())) {
                result.add(student);
            }
        }
        return result;
    }

    // Generate a report of all students
    public void generateReport() {
        if (studentMap.isEmpty()) {
            System.out.println("No student records found.");
        } else {
            System.out.println("Student Report:");
            for (Student student : studentMap.values()) {
                System.out.println(student);
            }
        }
    }
