```java
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.Date;
import java.util.List;

class Block {
    private int index;
    private long timestamp;
    private String data;
    private String previousHash;
    private String hash;
    private int nonce;

    public Block(int index, String data, String previousHash) {
        this.index = index;
        this.timestamp = new Date().getTime();
        this.data = data;
        this.previousHash = previousHash;
        this.nonce = 0;
        this.hash = calculateHash();
    }

    public String calculateHash() {
        String input = index + timestamp + data + previousHash + nonce;
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hashBytes = digest.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder hexString = new StringBuilder();
            for (byte b : hashBytes) {
                String hex = Integer.toHexString(0xff & b);
                if (hex.length() == 1) hexString.append('0');
                hexString.append(hex);
            }
            return hexString.toString();
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
    }

    public void mineBlock(int difficulty) {
        String target = new String(new char[difficulty]).replace('\0', '0');
        while (!hash.substring(0, difficulty).equals(target)) {
            nonce++;
            hash = calculateHash();
        }
        System.out.println("Block mined: " + hash);
    }

    // Getters and Setters
    public String getHash() { return hash; }
    public String getPreviousHash() { return previousHash; }
}

class Blockchain {
    private List<Block> chain;
    private int difficulty;

    public Blockchain(int difficulty) {
        this.chain = new ArrayList<>();
        this.difficulty = difficulty;
        // Create genesis block
        Block genesisBlock = new Block(0, "Genesis Block", "0");
        genesisBlock.mineBlock(difficulty);
        chain.add(genesisBlock);
    }

    public Block getLatestBlock() {
        return chain.get(chain.size() - 1);
    }

    public void addBlock(String data) {
        Block latestBlock = getLatestBlock();
        Block newBlock = new Block(latestBlock.getHash().length(), data, latestBlock.getHash());
        newBlock.mineBlock(difficulty);
        chain.add(newBlock);
    }

    public boolean isChainValid() {
        for (int i = 1; i < chain.size(); i++) {
            Block currentBlock = chain.get(i);
            Block previousBlock = chain.get(i - 1);

            if (!currentBlock.getHash().equals(currentBlock.calculateHash())) {
                System.out.println("Current block hash is invalid!");
                return false;
            }

            if (!previousBlock.getHash().equals(currentBlock.getPreviousHash())) {
                System.out.println("Previous block hash is invalid!");
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        Blockchain blockchain = new Blockchain(4); // Difficulty level

        blockchain.addBlock("First block");
        blockchain.addBlock("Second block");
        blockchain.addBlock("Third block");

        System.out.println("Is blockchain valid? " + blockchain.isChainValid());
    }
}
```

### Explanation:
1. **Block Class**:
   - Represents a single block in the blockchain.
   - Contains an index, timestamp, data, previous hash, current hash, and a nonce for proof of work.
   - `calculateHash()` computes the SHA-256 hash of the block's contents.
   - `mineBlock()` performs proof of work by finding a hash that meets the difficulty requirement.

2. **Blockchain Class**:
   - Manages the chain of blocks.
   - `addBlock()` adds a new block to the chain after mining it.
   - `isChainValid()` verifies the integrity of the blockchain by checking hashes and links.

3. **Main Method**:
   - Initializes a blockchain with a difficulty level.
   - Adds a few blocks and checks if the blockchain is valid.

### Security Considerations:
- **Hashing**: SHA-256 is used for cryptographic hashing, ensuring data integrity.
- **Proof of Work**: The mining process ensures that blocks are computationally expensive to produce, deterring malicious actors.
- **Chain Validation**: The `isChainValid()` method ensures no block has been tampered with.

### Limitations:
- No networking or peer-to-peer communication.
- No transaction handling or digital signatures.
- Simplified proof of work; real blockchains use more complex algorithms.

This code serves as a foundation for understanding blockchain concepts. For a production system, consider using established libraries like **Web3j** or **EthereumJ** and implementing additional security measures.

