import java.io.IOException;
import java.net.Socket;

public class PortChecker {

    public static boolean isPortOpen(String host, int port, int timeout) {
        Socket socket = null;
        try {
            socket = new Socket(host, port);
            socket.setSoTimeout(timeout);
            return true; // 端口开放
        } catch (IOException e) {
            return false; // 端口关闭或不可达
        } finally {
            if (socket != null) {
                try {
                    socket.close();
                } catch (IOException e) {
                    // 忽略关闭异常
                }
            }
        }
    }

    public static void main(String[] args) {
        String host = "example.com"; // 替换为目标服务器地址
        int port = 80; // 替换为目标端口号
        int timeout = 2000; // 超时时间，单位为毫秒

        boolean isOpen = isPortOpen(host, port, timeout);
        if (isOpen) {
            System.out.println("Port " + port + " on " + host + " is open.");
        } else {
            System.out.println("Port " + port + " on " + host + " is closed or unreachable.");
        }
    }
}
