        x: cx + x2 * scale,
        y: cy - y2 * scale,
      };
    }

    // Draw grid
    function drawGrid() {
      ctx.strokeStyle = '#444';
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      for (let i = 0; i < gridPoints.length; i++) {
        const p = project(gridPoints[i]);
        ctx.beginPath();
        ctx.arc(p.x, p.y, 2, 0, Math.PI * 2);
        ctx.fillStyle = '#888';
        ctx.fill();
      }
    }

    // Draw wireframe model
    function drawModel() {
      ctx.strokeStyle = '#0f0';
      ctx.lineWidth = 2;

      for (let i = 0; i < wireframeModel.length; i++) {
        const start = project(wireframeModel[i].start);
        const end = project(wireframeModel[i].end);
        ctx.beginPath();
        ctx.moveTo(start.x, start.y);
        ctx.lineTo(end.x, end.y);
        ctx.stroke();
      }
    }

    // Snap to grid
    function snapToGrid(x, y) {
      const cx = canvas.width / 2;
      const cy = canvas.height / 2;
      const mouse = { x: x - cx, y: cy - y };
      const scale = 200;

      const x3 = mouse.x / scale;
      const y3 = -mouse.y / scale;

      const x2 = x3 * Math.cos(-angleZ) - y3 * Math.sin(-angleZ);
      const y2 = y3 * Math.cos(-angleZ) + x3 * Math.sin(-angleZ);

      const y = y2 * Math.cos(-angleX) + z * Math.sin(-angleX);
      const z = z * Math.cos(-angleX) - y2 * Math.sin(-angleX);

      const x = x2 * Math.cos(-angleY) - z * Math.sin(-angleY);
      const z2 = z * Math.cos(-angleY) + x2 * Math.sin(-angleY);

      const snappedX = Math.round(x / gridSize) * gridSize;
      const snappedY = Math.round(y / gridSize) * gridSize;
      const snappedZ = Math.round(z2 / gridSize) * gridSize;

      return { x: snappedX, y: snappedY, z: snappedZ };
    }

    // Event listeners
    canvas.addEventListener('mousemove', (e) => {
      if (isDragging) {
        const snapped = snapToGrid(e.clientX, e.clientY);
        if (selectedPoint) {
          if (selectedPoint.type === 'grid') {
            selectedPoint.x = snapped.x;
            selectedPoint.y = snapped.y;
            selectedPoint.z = snapped.z;
          } else if (selectedPoint.type === 'model') {
            selectedPoint.end.x = snapped.x;
            selectedPoint.end.y = snapped.y;
            selectedPoint.end.z = snapped.z;
          }
        }
      }
    });

    canvas.addEventListener('mousedown', (e) => {
      const rect = canvas.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      for (let i = 0; i < gridPoints.length; i++) {
        const p = project(gridPoints[i]);
        if (Math.hypot(p.x - mouseX, p.y - mouseY) < 5) {
          selectedPoint = { ...gridPoints[i], type: 'grid' };
          isDragging = true;
          return;
        }
      }

      for (let i = 0; i < wireframeModel.length; i++) {
        const start = project(wireframeModel[i].start);
        const end = project(wireframeModel[i].end);
        const dx = end.x - start.x;
        const dy = end.y - start.y;
        const len = Math.hypot(dx, dy);
        const dot = ((mouseX - start.x) * dx + (mouseY - start.y) * dy) / len**2;
        const closestX = start.x + dot * dx;
        const closestY = start.y + dot * dy;
        if (Math.hypot(closestX - mouseX, closestY - mouseY) < 5) {
          selectedPoint = { ...wireframeModel[i], type: 'model' };
          isDragging = true;
          return;
        }
      }
    });

    canvas.addEventListener('mouseup', () => {
      isDragging = false;
      selectedPoint = null;
    });

    canvas.addEventListener('contextmenu', (e) => {
      e.preventDefault();
      vmcMenu.style.display = 'block';
      vmcMenu.style.left = `${e.clientX}px`;
      vmcMenu.style.top = `${e.clientY}px`;
    });

    addLineBtn.addEventListener('click', () => {
      vmcMenu.style.display = 'none';
      const start = snapToGrid(mouseX, mouseY);
      let end = { ...start };
      wireframeModel.push({ start, end });
    });

    // Animation loop
    function animate() {
      drawGrid();
      drawModel();
      requestAnimationFrame(animate);
    }

    animate();
  </script>
</body>
</html>
```

### Explanation:
1. **Grid Points Array (`gridPoints`)**: Stores all possible snapping points in 3D space.
2. **Wireframe Model Array (`wireframeModel`)**: Stores the lines that make up the 3D model.
3. **Drawn Lines Array (`drawnLines`)**: Not fully implemented in this example but can be used to store temporary lines during drawing.

### Features:
- **Grid Snapping**: Mouse movements snap to the nearest grid point.
- **3D Rotation**: The model can be rotated along the X, Y, and Z axes.
- **Line Drawing**: Add lines to the model using the VMC menu.
- **Projection**: 3D points are projected onto the 2D canvas using basic projection math.

### Notes:
- This is a basic implementation. You can expand it by adding more controls for rotation, scaling, and more advanced menu options.
- The snapping and projection logic can be optimized for better performance with larger models.
- Error handling and edge cases (e.g., invalid inputs) are not included for brevity.

