  board[0][1] = { id: 'n-1-w', piece: 'knight', color: 'white' };
  board[0][7] = { id: 'r-2-w', piece: 'rook', color: 'white' };
  board[0][6] = { id: 'n-2-w', piece: 'knight', color: 'white' };

  // Black pieces
  board[7][0] = { id: 'r-1-b', piece: 'rook', color: 'black' };
  board[7][1] = { id: 'n-1-b', piece: 'knight', color: 'black' };
  board[7][7] = { id: 'r-2-b', piece: 'rook', color: 'black' };
  board[7][6] = { id: 'n-2-b', piece: 'knight', color: 'black' };

  return board;
}

// Get cell ID from coordinates
function getCellId(row, col) {
  return String.fromCharCode(97 + col) + (8 - row);
}

// Get piece element from the DOM
function getPieceElement(row, col) {
  const cellId = getCellId(row, col);
  const cell = document.getElementById(cellId);
  return cell ? cell.firstChild : null;
}

// Check if position is within bounds
function isInBounds(row, col) {
  return row >= 0 && row < 8 && col >= 0 && col < 8;
}

// Generate rook moves
function generateRookMoves(board, row, col, color) {
  const moves = [];
  const directions = [
    { dr: -1, dc: 0 }, // Up
    { dr: 1, dc: 0 },  // Down
    { dr: 0, dc: -1 }, // Left
    { dr: 0, dc: 1 }   // Right
  ];

  for (const dir of directions) {
    let r = row + dir.dr;
    let c = col + dir.dc;
    while (isInBounds(r, c)) {
      if (board[r][c] === null) {
        moves.push({ from: [row, col], to: [r, c] });
      } else if (board[r][c].color !== color) {
        moves.push({ from: [row, col], to: [r, c] });
        break;
      } else {
        break;
      }
      r += dir.dr;
      c += dir.dc;
    }
  }
  return moves;
}

// Generate knight moves
function generateKnightMoves(board, row, col, color) {
  const moves = [];
  const knightMoves = [
    { dr: -2, dc: -1 }, { dr: -2, dc: 1 },
    { dr: 2, dc: -1 }, { dr: 2, dc: 1 },
    { dr: -1, dc: -2 }, { dr: -1, dc: 2 },
    { dr: 1, dc: -2 }, { dr: 1, dc: 2 }
  ];

  for (const move of knightMoves) {
    const r = row + move.dr;
    const c = col + move.dc;
    if (isInBounds(r, c) && (board[r][c] === null || board[r][c].color !== color)) {
      moves.push({ from: [row, col], to: [r, c] });
    }
  }
  return moves;
}

// Generate moves for a piece
function generatePieceMoves(board, row, col) {
  const piece = board[row][col];
  if (!piece) return [];

  switch (piece.piece) {
    case 'rook':
      return generateRookMoves(board, row, col, piece.color);
    case 'knight':
      return generateKnightMoves(board, row, col, piece.color);
    default:
      return [];
  }
}

// Get all legal moves for the current player
function getAllLegalMoves(board, color) {
  const moves = [];
  for (let row = 0; row < 8; row++) {
    for (let col = 0; col < 8; col++) {
      const piece = board[row][col];
      if (piece && piece.color === color) {
        moves.push(...generatePieceMoves(board, row, col));
      }
    }
  }
  return moves;
}

// Apply a move to the board
function applyMove(board, move) {
  const [fromRow, fromCol] = move.from;
  const [toRow, toCol] = move.to;
  const piece = board[fromRow][fromCol];
  board[toRow][toCol] = piece;
  board[fromRow][fromCol] = null;

  // Update DOM
  const fromCellId = getCellId(fromRow, fromCol);
  const toCellId = getCellId(toRow, toCol);
  const pieceElement = document.getElementById(piece.id);
  document.getElementById(toCellId).appendChild(pieceElement);
  document.getElementById(fromCellId).innerHTML = '';

  // Switch turns
  gameState.turn = gameState.turn === 'white' ? 'black' : 'white';
}

// Select a random move
function selectRandomMove(moves) {
  return moves[Math.floor(Math.random() * moves.length)];
}

// Auto-play the game
function autoPlay() {
  const legalMoves = getAllLegalMoves(gameState.board, gameState.turn);
  if (legalMoves.length > 0) {
    const move = selectRandomMove(legalMoves);
    applyMove(gameState.board, move);
  }
  setTimeout(autoPlay, 1000);
}

// Start the game
autoPlay();
