                console.error('Microphone access denied or error:', err);
                startButton.disabled = false;
            }
        });

        function detectBeat(data) {
            const threshold = 0.1; // Adjust based on sensitivity
            for (let i = 0; i < data.length; i++) {
                if (data[i] > threshold && lastTime + 60 < Date.now()) {
                    intervalCount++;
                    if (intervalCount > 2) {
                        const currentTime = Date.now();
                        const interval = (currentTime - lastTime) / 1000;
                        bpm = Math.round(60 / (interval / (intervalCount - 1)));
                        socket.emit('bpm', bpm);
                        lastTime = currentTime;
                        intervalCount = 0;
                    }
                }
            }
        }
