class Unit {
    constructor(name, attack, defense, health) {
        this.name = name;
        this.attack = attack;
        this.defense = defense;
        this.health = health;
    }

    takeDamage(damage) {
        const actualDamage = Math.max(0, damage - this.defense);
        this.health -= actualDamage;
        if (this.health < 0) this.health = 0;
    }

    isAlive() {
        return this.health > 0;
    }
}

// Faction Class: Represents a military faction with multiple units
class Faction {
    constructor(name) {
        this.name = name;
        this.units = [];
    }

    addUnit(unit) {
        this.units.push(unit);
    }

    getAliveUnits() {
        return this.units.filter(unit => unit.isAlive());
    }
}

// Battle Class: Manages the combat between two factions
class Battle {
    constructor(faction1, faction2) {
        this.faction1 = faction1;
        this.faction2 = faction2;
    }

    startBattle() {
        console.log(`Battle started between ${this.faction1.name} and ${this.faction2.name}!`);

        while (this.faction1.getAliveUnits().length > 0 && this.faction2.getAliveUnits().length > 0) {
            this.executeRound();
        }

        this.declareWinner();
    }

    executeRound() {
        console.log("\n--- New Round ---");

        // Faction 1 attacks Faction 2
        this.faction1.getAliveUnits().forEach(attacker => {
            const defender = this.faction2.getAliveUnits()[0];
            if (defender) {
                console.log(`${attacker.name} from ${this.faction1.name} attacks ${defender.name} from ${this.faction2.name}!`);
                defender.takeDamage(attacker.attack);
                console.log(`${defender.name} now has ${defender.health} health left.`);
            }
        });

        // Faction 2 attacks Faction 1
        this.faction2.getAliveUnits().forEach(attacker => {
            const defender = this.faction1.getAliveUnits()[0];
            if (defender) {
                console.log(`${attacker.name} from ${this.faction2.name} attacks ${defender.name} from ${this.faction1.name}!`);
                defender.takeDamage(attacker.attack);
                console.log(`${defender.name} now has ${defender.health} health left.`);
            }
        });
    }

    declareWinner() {
        if (this.faction1.getAliveUnits().length > 0) {
            console.log(`\n${this.faction1.name} wins the battle!`);
        } else if (this.faction2.getAliveUnits().length > 0) {
            console.log(`\n${this.faction2.name} wins the battle!`);
        } else {
            console.log("\nThe battle ended in a draw!");
        }
    }
}

// Example Usage
const alpha = new Faction("Alpha");
const bravo = new Faction("Bravo");

alpha.addUnit(new Unit("Infantry 1", 10, 5, 50));
alpha.addUnit(new Unit("Tank 1", 20, 10, 100));

bravo.addUnit(new Unit("Infantry 2", 8, 6, 60));
bravo.addUnit(new Unit("Tank 2", 18, 12, 90));

const battle = new Battle(alpha, bravo);
battle.startBattle();
```

### Explanation:
1. **Unit Class**: Represents individual military units with attributes like attack, defense, and health.
2. **Faction Class**: Represents a military faction that holds multiple units.
3. **Battle Class**: Manages the combat logic between two factions, executing rounds until one faction is defeated.

### Security Considerations:
