```javascript
$(".custom-select").each(function () {
    var classes = $(this).attr("class"),
        id = $(this).attr("id"),
        name = $(this).attr("name"),
        placeholder = $(this).attr("placeholder");

    var template = '<div class="' + classes + '">';
    template += '<span class="custom-select-trigger">' + (placeholder || "") + "</span>";
    template += '<div class="custom-options">';

    $(this).find("option").each(function (index) {
        var isSelected = false;
        if (placeholder && $(this).attr("value") === placeholder) {
            isSelected = true;
            $(this).attr("selected", "selected"); // Устанавливаем selected для option
        }

        template += '<span class="custom-option ' + 
                    $(this).attr("class") + 
                    (isSelected ? ' selection' : '') + 
                    '" data-value="' + 
                    $(this).attr("value") + 
                    '">' + 
                    $(this).html() + 
                    "</span>";
    });

    template += "</div></div>";

    $(this).wrap('<div class="custom-select-wrapper"></div>');
    $(this).hide();
    $(this).after(template);

    // Обновляем trigger, если есть selected option
    var selectedOption = $(this).find("option:selected");
    if (selectedOption.length > 0) {
        $(this).next().find(".custom-select-trigger").text(selectedOption.text());
    }
});

$(".custom-option:first-of-type").hover(
    function () {
        $(this).parents(".custom-options").addClass("option-hover");
    },
    function () {
        $(this).parents(".custom-options").removeClass("option-hover");
    }
);

$(".custom-select-trigger").on("click", function (event) {
