Uploading large files to AWS S3 with chunking and progress tracking in an Express.js application involves several steps. Below is a detailed guide to achieve this:

---

### **Steps to Upload Large Files to S3 with Chunking and Progress Tracking**

#### **1. Set Up AWS SDK and Dependencies**
Install the necessary packages:
```bash
npm install aws-sdk multer multer-s3
```

- **`aws-sdk`**: AWS SDK for JavaScript to interact with S3.
- **`multer`**: Middleware for handling `multipart/form-data`, used for file uploads.
- **`multer-s3`**: Storage engine for Multer to upload files directly to S3.

---

#### **2. Configure AWS S3**
Set up AWS credentials and S3 configuration:
```javascript
const AWS = require("aws-sdk");
const multer = require("multer");
const multerS3 = require("multer-s3");

AWS.config.update({
  accessKeyId: process.env.AWS_ACCESS_KEY_ID,
  secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  region: process.env.AWS_REGION,
});

const s3 = new AWS.S3();

const upload = multer({
  storage: multerS3({
    s3: s3,
    bucket: process.env.S3_BUCKET_NAME,
    contentType: multerS3.AUTO_CONTENT_TYPE,
    key: (req, file, cb) => {
      cb(null, `uploads/${Date.now()}_${file.originalname}`); // Define file path in S3
    },
  }),
});
```

---

#### **3. Implement Chunked Upload with Progress Tracking**
For large files, you need to manually handle chunking and progress tracking. Here’s how:

```javascript
const express = require("express");
const app = express();
const { S3 } from "aws-sdk";
const s3 = new S3();
const fs = require("fs");
const path = require("path");

app.post("/upload", upload.single("file"), async (req, res) => {
  const file = req.file;
  const filePath = file.path;
  const fileStream = fs.createReadStream(filePath);
  const params = {
    Bucket: process.env.S3_BUCKET_NAME,
    Key: `uploads/${Date.now()}_${file.originalname}`,
    Body: fileStream,
  };

  try {
    // Track progress
    let bytesUploaded = 0;
    const totalBytes = file.size;

    fileStream.on("data", (chunk) => {
      bytesUploaded += chunk.length;
      const progress = (bytesUploaded / totalBytes) * 100;
      console.log(`Upload Progress: ${progress.toFixed(2)}%`);
      // Send progress to client if needed (e.g., via WebSocket or SSE)
    });

    const data = await s3.upload(params).promise();
    res.json({ message: "File uploaded successfully", s3Url: data.Location });
  } catch (error) {
    console.error("Error uploading file:", error);
    res.status(500).json({ error: "Failed to upload file" });
  }
});

app.listen(3000, () => {
  console.log("Server is running on port 3000");
});
```

---

#### **4. Client-Side Implementation (Optional)**
If you want to track progress on the client side, use the `xhr.upload.onprogress` event:

```javascript
const fileInput = document.getElementById("fileInput");
const progressBar = document.getElementById("progressBar");

fileInput.addEventListener("change", (e) => {
  const file = e.target.files[0];
  const formData = new FormData();
  formData.append("file", file);

  const xhr = new XMLHttpRequest();
  xhr.open("POST", "/upload", true);

  xhr.upload.onprogress = (e) => {
    if (e.lengthComputable) {
      const percentComplete = (e.loaded / e.total) * 100;
      progressBar.value = percentComplete;
    }
  };

  xhr.onload = () => {
    if (xhr.status === 200) {
      console.log("File uploaded successfully");
    } else {
      console.error("Upload failed");
    }
  };

  xhr.send(formData);
});
```

---

#### **5. Advanced Chunking (Manual)**
For very large files, you can manually split the file into chunks and upload them individually using the `S3.uploadPart` API. Here’s a basic example:

```javascript
const chunkSize = 10 * 1024 * 1024; // 10MB chunks
const fileStream = fs.createReadStream(filePath, { highWaterMark: chunkSize });

let partNumber = 1;
const uploadId = await s3.createMultipartUpload({ Bucket, Key }).promise();
const parts = [];

fileStream.on("data", async (chunk) => {
  const params = {
    Bucket,
    Key,
    UploadId: uploadId,
    PartNumber: partNumber,
    Body: chunk,
  };
  const { ETag } = await s3.uploadPart(params).promise();
  parts.push({ PartNumber: partNumber, ETag });
  partNumber++;
});

fileStream.on("end", async () => {
  await s3.completeMultipartUpload({ Bucket, Key, UploadId: uploadId, MultipartUpload: { Parts: parts } }).promise();
  console.log("Upload complete");
});
```

---

#### **6. Security Considerations**
- **Validate File Types**: Ensure only allowed file types are uploaded.
- **Limit File Size**: Set limits on file size to prevent abuse.
- **Use Presigned URLs**: For direct uploads from the client to S3, use presigned URLs to enhance security.

---

By following these steps, you can efficiently upload large files to AWS S3 with chunking and progress tracking in your Express.js application.

