          }

          case 'b': {
            newLine = { text, ...options, bold: true };
            break;
          }

          case 'i': {
            newLine = { text, ...options, italics: true };
            break;
          }

          case 'u': {
            newLine = { text, ...options, decoration: 'underline' };
            break;
