          }

          case 'h2': {
            newLine = { text, ...options, fontSize: 20 };
            break;
          }

          case 'h3': {
            newLine = { text, ...options, fontSize: 16 };
            break;
          }

          case 'h4': {
            newLine = { text, ...options, fontSize: 13 };
            break;
