        if (ul) lineType = 'ul';
        if (ol) lineType = 'ol';

        if (typeof targetString !== 'string') return line;

        const hasStyles = targetString.match(pattern);

        if (!hasStyles) return { [lineType]: targetString, ...options };

        const [match, tagType, value, innerText] = hasStyles;

