```javascript
// entities.js
class Leader {
    createGroups(alts) {
        const groups = [];
        for (let i = 0; i < alts.length; i += 3) {
            const group = alts.slice(i, i + 3);
            group.forEach(alt => alt.joinGroup(group));
            groups.push(group);
        }
        return groups;
    }

    dispatchEvent(event) {
        event.trigger();
    }
}

class Alt {
    constructor(id) {
        this.id = id;
        this.group = null;
    }

    joinGroup(group) {
        this.group = group;
    }

    isInGroup() {
        return this.group !== null;
    }
}

class GroupEvent {
    constructor(groups) {
        this.groups = groups;
    }

    trigger() {
        this.groups.forEach(group => {
            group.forEach(alt => {
                if (!alt.isInGroup()) {
                    throw new Error(`Alt ${alt.id} is not in a group`);
                }
            });
        });
    }
}

const createLeader = () => new Leader();
const createAlt = (id) => new Alt(id);
const createGroupEvent = (groups) => new GroupEvent(groups);

module.exports = { createLeader, createAlt, createGroupEvent };
```

