// Input validation middleware
const validateInput = (req, res, next) => {
  const cities = req.body.cities;
  if (!Array.isArray(cities) || cities.length === 0 || cities.some(city => typeof city !== "string")) {
    return res.status(400).json({ error: "Invalid input: 'cities' must be a non-empty array of strings." });
  }
  next();
};

