```javascript
const fs = require('fs');
const crypto = require('crypto');

// Klucz szyfrowania (musisz go bezpiecznie przechowywać!)
const encryptionKey = 'tajny-klucz-ktory-powinien-byc-dlugi-i-bezpieczny';
const iv = crypto.randomBytes(16); // Wektor inicjalizacyjny (IV)

// Funkcja do szyfrowania pliku
function encryptFile(inputFilePath, outputFilePath) {
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(encryptionKey), iv);

    const input = fs.createReadStream(inputFilePath);
    const output = fs.createWriteStream(outputFilePath);

    // Zapisujemy IV na początku zaszyfrowanego pliku, aby móc go później odczytać
    output.write(iv);

    input.pipe(cipher).pipe(output);

    return new Promise((resolve, reject) => {
        output.on('finish', resolve);
        output.on('error', reject);
    });
}

// Funkcja do odszyfrowywania pliku (dla kompletności)
function decryptFile(inputFilePath, outputFilePath) {
    const input = fs.createReadStream(inputFilePath);
    const iv = input.read(16); // Odczytujemy IV z początku pliku
    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(encryptionKey), iv);

    const output = fs.createWriteStream(outputFilePath);

    input.pipe(decipher).pipe(output);

    return new Promise((resolve, reject) => {
        output.on('finish', resolve);
        output.on('error', reject);
    });
}

// Użycie funkcji do zaszyfrowania pliku
const inputFile = 'plik.js';
const encryptedFile = 'plik.js.enc';

encryptFile(inputFile, encryptedFile)
    .then(() => console.log(`Plik ${inputFile} został zaszyfrowany do ${encryptedFile}`))
    .catch(err => console.error('Błąd podczas szyfrowania:', err));

// Jeśli chcesz odszyfrować plik, użyj funkcji decryptFile
// const decryptedFile = 'plik_odszyfrowany.js';
// decryptFile(encryptedFile, decryptedFile)
//     .then(() => console.log(`Plik ${encryptedFile} został odszyfrowany do ${decryptedFile}`))
//     .catch(err => console.error('Błąd podczas odszyfrowywania:', err));
```

### Ważne uwagi:
1. **Klucz szyfrowania**: Klucz `encryptionKey` powinien być długi i bezpieczny. W rzeczywistym zastosowaniu powinieneś go przechowywać w bezpiecznym miejscu, np. w zmiennych środowiskowych lub w menedżerze sekretów.
2. **IV (Initialization Vector)**: IV jest losowo generowany dla każdego szyfrowania i zapisywany na początku zaszyfrowanego pliku, aby móc go później odczytać podczas odszyfrowywania.
3. **Bezpieczeństwo**: Pamiętaj, że szyfrowanie plików to tylko część bezpieczeństwa. Musisz również zadbać o bezpieczne przechowywanie kluczy i ochronę przed atakami typu side-channel.

