    upgrade(db) {
        db.createObjectStore('posts', { keyPath: 'id' });
    },
});

// Store encrypted data
async function savePost(id, content) {
    const db = await dbPromise;
    const encryptedContent = await encryptData(content, encryptionKey);
    await db.put('posts', { id, content: encryptedContent, timestamp: Date.now() });
}

// Retrieve and decrypt data
async function getPost(id) {
    const db = await dbPromise;
    const post = await db.get('posts', id);
    if (post) {
        const decryptedContent = await decryptData(post.content, encryptionKey);
        return decryptedContent;
    }
    return null;
}

// Encryption and decryption functions (using Web Crypto API)
async function encryptData(data, key) {
    const encoder = new TextEncoder();
    const dataBuffer = encoder.encode(data);
    const iv = window.crypto.getRandomValues(new Uint8Array(12));
    const encryptedData = await window.crypto.subtle.encrypt(
        { name: "AES-GCM", iv },
        key,
