function transformArrayToObject(arr) {
    const result = {};
    let current = result;
    let stack = [];

    for (let i = 0; i < arr.length; i++) {
        const item = arr[i];
        if (Array.isArray(item)) {
            // If the item is an array, it means we need to process its elements
            const temp = {};
            current[stack[stack.length - 1]] = temp;
            stack.push(temp);
            current = temp;
            i--; // Re-process the current index after updating the stack
        } else if (typeof item === 'string') {
            // If the item is a string, it's a key in the hierarchy
            if (stack.length === 0) {
                // If stack is empty, initialize the root key
                result[item] = {};
                current = result[item];
            } else {
                // Otherwise, add the key to the current level
                current[item] = {};
                stack[stack.length - 1] = item;
            }
        } else if (item === undefined) {
            // If undefined, move up the stack
            stack.pop();
            if (stack.length > 0) {
                current = stack[stack.length - 1];
            } else {
                current = result;
            }
        }
    }

    // Helper function to recursively merge arrays
    function mergeArrays(target, source) {
        if (!target) target = [];
