    const steps = extendedEuclidean(a, b);
    let output = steps.map(step => `${step[0]} = ${step[1]} * ${step[2]} + ${step[3]}`).join('\n');
    output += '\n=> ';

    const modularInverse = computeModularInverse(a, b, steps);
    output += `\n${a}^-1 (mod ${b}) = ${modularInverse} (mod ${b})`;

    resultDiv.textContent = output;
});

function extendedEuclidean(a, b) {
    const steps = [];
    let r = [a, b];
    let q = [];
    let rPrev = [1, 0];
    let rCurr = [0, 1];

    while (r[1] !== 0) {
        q.push(Math.floor(r[0] / r[1]));
        steps.push([r[0], q[q.length - 1], r[1], r[0] - q[q.length - 1] * r[1]]);
        [r[0], r[1]] = [r[1], r[0] - q[q.length - 1] * r[1]];
        [rPrev[0], rPrev[1]] = [rCurr[0], rCurr[1]];
        rCurr[0] = rPrev[0] - q[q.length - 1] * rCurr[0];
        rCurr[1] = rPrev[1] - q[q.length - 1] * rCurr[1];
    }

    return steps;
}

function computeModularInverse(a, b, steps) {
    let x = 0, y = 1;
    for (let i = steps.length - 1; i >= 0; i--) {
        [x, y] = [y, x - steps[i][1] * y];
    }
    return (x % b + b) % b;
}
