class WebSocketManager {
  /**
   * Initializes the WebSocketManager instance with an event emitter.
   */
  constructor() {
    /**
     * Event emitter instance for handling WebSocket events.
     * @type {import('mitt').Emitter}
     */
    this.emitter = mitt()
  }

  /**
   * Opens a WebSocket connection to the specified server endpoint.
   * Listens for incoming messages and emits events based on the message payload.
   * @fires WebSocketManager#update_station
   * @fires WebSocketManager#update_station_list
   * @fires WebSocketManager#update_inventory
   */
  open() {
