    const bodyData = req.body;
    console.log('Body Data:', bodyData);
    res.send('Body data received');
});

// GET запрос с маршрутным параметром
app.get('/data/:id', (req, res) => {
    const paramData = req.params.id;
    console.log('Param Data:', paramData);
    res.send('Param data received');
});

// Запуск сервера
app.listen(3000, () => {
    console.log('Server is running on port 3000');
});
```

### Безопасность:
- **Валидация данных:** Всегда валидируйте и санитизируйте входные данные, чтобы предотвратить инъекции и другие атаки.
- **Ограничение размера тела запроса:** Используйте middleware для ограничения размера тела запроса, чтобы предотвратить атаки типа DoS.
- **CORS:** Настройте CORS (Cross-Origin Resource Sharing) правильно, чтобы избежать нежелательных кросс-доменных запросов.

```javascript
const cors = require('cors');
app.use(cors({ origin: 'http://example.com' })); // Разрешить запросы только с указанного домена
```

