    output: process.stdout
});

// Step 1: Get SQL schema input from user
function getSqlSchema() {
    return new Promise((resolve) => {
        rl.question('Enter SQL table schema (or provide a file path starting with "file:"): ', (input) => {
            if (input.startsWith('file:')) {
                const filePath = input.split('file:')[1].trim();
                fs.readFile(filePath, 'utf8', (err, data) => {
                    if (err) throw err;
                    resolve(data);
                });
            } else {
                resolve(input);
            }
        });
    });
}

// Step 2: Parse SQL schema
function parseSqlSchema(schema) {
    const parser = new SQLParser();
    const parsed = parser.parse(schema);
    const table = parsed[0].table;
    const columns = parsed[0].create_definitions.reduce((acc, def) => {
        acc[def.column_name] = {
            type: def.type,
            constraints: def.constraints || []
        };
        return acc;
    }, {});
    return { tableName: table.name, columns };
}

// Step 3: Generate model file using Sequelize
function generateModelFile(tableName, columns) {
    const modelTemplate = `
    const { DataTypes } = require('sequelize');
    const sequelize = require('../config/sequelize');

    const <%= tableName %> = sequelize.define('<%= tableName %>', {
        <% Object.keys(columns).forEach((column, index) => { %>
        <%= column %>: {
            type: DataTypes.<%= columns[column].type.toUpperCase() %>,
            <% if (columns[column].constraints.includes('NOT NULL')) { %>allowNull: false,<% } %>
            <% if (columns[column].constraints.includes('PRIMARY KEY')) { %>primaryKey: true,<% } %>
        }<%= index === Object.keys(columns).length - 1 ? '' : ',' %>
        <% }); %>
    }, {});

    module.exports = <%= tableName %>;
    `;
    return ejs.render(modelTemplate, { tableName, columns });
}

// Step 4: Generate controller file
function generateControllerFile(tableName) {
    const controllerTemplate = `
    const <%= tableName %> = require('../models/<%= tableName %>');

    exports.getAll = async (req, res) => {
        try {
            const data = await <%= tableName %>.findAll();
            res.json(data);
        } catch (error) {
            res.status(500).json({ error: error.message });
        }
    };

    exports.getById = async (req, res) => {
        try {
            const data = await <%= tableName %>.findByPk(req.params.id);
            if (!data) return res.status(404).json({ message: 'Not found' });
            res.json(data);
        } catch (error) {
            res.status(500).json({ error: error.message });
        }
    };

    exports.create = async (req, res) => {
        try {
            const data = await <%= tableName %>.create(req.body);
            res.status(201).json(data);
        } catch (error) {
            res.status(400).json({ error: error.message });
        }
    };

    exports.update = async (req, res) => {
        try {
            const [updated] = await <%= tableName %>.update(req.body, { where: { id: req.params.id } });
            if (!updated) return res.status(404).json({ message: 'Not found' });
            res.json({ message: 'Updated successfully' });
        } catch (error) {
            res.status(400).json({ error: error.message });
        }
    };

    exports.delete = async (req, res) => {
        try {
            const deleted = await <%= tableName %>.destroy({ where: { id: req.params.id } });
            if (!deleted) return res.status(404).json({ message: 'Not found' });
            res.json({ message: 'Deleted successfully' });
        } catch (error) {
            res.status(500).json({ error: error.message });
        }
    };
    `;
    return ejs.render(controllerTemplate, { tableName });
}

// Step 5: Generate router file with authentication and validation
function generateRouterFile(tableName) {
    const routerTemplate = `
    const express = require('express');
    const router = express.Router();
    const { body, param } = require('express-validator');
    const authMiddleware = require('../middleware/auth');
    const <%= tableName %>Controller = require('../controllers/<%= tableName %>Controller');

    // Validation middleware
    const validate = (req, res, next) => {
        const errors = validationResult(req);
        if (!errors.isEmpty()) {
            return res.status(400).json({ errors: errors.array() });
        }
        next();
    };

    // CRUD routes with authentication
    router.get('/', authMiddleware, <%= tableName %>Controller.getAll);
    router.get('/:id', authMiddleware, param('id').isInt(), validate, <%= tableName %>Controller.getById);
    router.post('/', authMiddleware, [
        body('<% Object.keys(columns).forEach((column) => { %><%= column %>').notEmpty(),<% }) %>
    ], validate, <%= tableName %>Controller.create);
    router.put('/:id', authMiddleware, param('id').isInt(), validate, <%= tableName %>Controller.update);
    router.delete('/:id', authMiddleware, param('id').isInt(), validate, <%= tableName %>Controller.delete);

    module.exports = router;
    `;
    return ejs.render(routerTemplate, { tableName });
}

// Step 6: Save files to 'generated' folder
function saveFiles(tableName, columns) {
    const generatedDir = path.join(__dirname, 'generated');
    if (!fs.existsSync(generatedDir)) fs.mkdirSync(generatedDir);

    const modelFile = path.join(generatedDir, `${tableName}Model.js`);
    const controllerFile = path.join(generatedDir, `${tableName}Controller.js`);
    const routerFile = path.join(generatedDir, `${tableName}Router.js`);

    fs.writeFileSync(modelFile, generateModelFile(tableName, columns));
    fs.writeFileSync(controllerFile, generateControllerFile(tableName));
    fs.writeFileSync(routerFile, generateRouterFile(tableName, columns));

    console.log(`Files generated successfully in ${generatedDir}`);
}

// Step 7: Setup package.json and dependencies
function setupProject() {
    const generatedDir = path.join(__dirname, 'generated');
    const packageJson = {
        name: 'generated-api',
        version: '1.0.0',
        scripts: {
            start: 'node server.js'
        },
        dependencies: {
            express: '^4.17.1',
            sequelize: '^6.6.5',
            'sequelize-cli': '^6.2.0',
            'express-validator': '^6.12.1',
            passport: '^0.4.1',
            helmet: '^4.6.0',
            cors: '^2.8.5'
        }
    };

    fs.writeFileSync(path.join(generatedDir, 'package.json'), JSON.stringify(packageJson, null, 2));
    execSync('npm install', { cwd: generatedDir });
}

// Main function
async function main() {
    try {
        const schema = await getSqlSchema();
        const { tableName, columns } = parseSqlSchema(schema);
        saveFiles(tableName, columns);
        setupProject();
        console.log('Project setup complete. Run `npm start` in the generated folder to start the server.');
    } catch (error) {
        console.error('Error generating files:', error);
    } finally {
        rl.close();
    }
}

main();
```

### Explanation of the Code

1. **Input Handling**: The user can input the SQL schema directly or provide a file path prefixed with `file:`.
2. **SQL Parsing**: The `node-sql-parser` library parses the SQL schema to extract table name, columns, types, and constraints.
3. **File Generation**:
   - **Model File**: Uses Sequelize ORM to define the table schema.
   - **Controller File**: Implements CRUD operations.
   - **Router File**: Defines endpoints with authentication, validation, and security middleware.
4. **Security Features**:
   - Authentication using `passport`.
   - Input validation using `express-validator`.
   - Security headers using `helmet`.
   - CORS handling using `cors`.
5. **Project Setup**: Generates a `package.json` file and installs dependencies.

### Running the Generated Files

1. Navigate to the `generated` folder.
2. Run `npm start` to start the server.

### Example Usage

Input SQL schema:
```sql
CREATE TABLE users (
    id INT PRIMARY KEY,
    username VARCHAR(50) NOT NULL,
    email VARCHAR(100) NOT NULL
);
```

Output: Generates `usersModel.js`, `usersController.js`, and `usersRouter.js` in the `generated` folder.

