let chartInstance = null; // To store the chart instance for updates

function calculateMarkup() {
  const costPrice = parseFloat(document.getElementById('costPrice').value);
  const markupPercentage = parseFloat(document.getElementById('markupPercentage').value);

  if (isNaN(costPrice) || isNaN(markupPercentage)) {
    alert('Please enter valid numbers for cost price and markup percentage.');
    return;
  }

  const sellingPrice = costPrice * (1 + markupPercentage / 100);

  // Prepare chart data
  const chartData = {
    labels: ['Cost Price', 'Selling Price'],
    datasets: [{
      label: 'Prices',
      data: [costPrice, sellingPrice],
      backgroundColor: ['rgba(54, 162, 235, 0.6)', 'rgba(75, 192, 192, 0.6)'],
      borderColor: ['rgba(54, 162, 235, 1)', 'rgba(75, 192, 192, 1)'],
      borderWidth: 1
    }]
  };

  // Destroy existing chart if it exists
  if (chartInstance) {
    chartInstance.destroy();
  }

  // Render new chart
  const ctx = document.getElementById('resultChart').getContext('2d');
  chartInstance = new Chart(ctx, {
    type: 'bar',
    data: chartData,
    options: {
      scales: {
        y: {
          beginAtZero: true
        }
      },
      responsive: true,
      plugins: {
        legend: {
          position: 'top',
        },
        title: {
          display: true,
          text: 'Cost Price vs Selling Price'
        }
      }
    }
  });
}
```

### How It Works:
1. **HTML**: The structure includes input fields for cost price and markup percentage, a button to trigger the calculation, and a `<canvas>` element for the chart.
2. **CSS**: Basic styling to make the calculator look clean and centered.
3. **JavaScript**:
   - Calculates the selling price based on the cost price and markup percentage.
   - Uses **Chart.js** to display the results in a bar chart.
   - Updates the chart whenever new values are calculated.

### Libraries Used:
- **Chart.js**: For rendering the chart. Include it via CDN in the HTML file.

### Usage:
1. Enter the **Cost Price** and **Markup Percentage**.
2. Click **Calculate** to see the **Selling Price** and a bar chart comparing the cost price and selling price.

This is a simple yet effective tool for calculating markups and visualizing the results.

