            font-size: 16px;
            cursor: pointer;
        }
    </style>
</head>
<body>
    <h1>Введите данные</h1>
    <input type="text" id="userInput" placeholder="Введите текст">
    <button onclick="redirectToSecondPage()">Перейти на вторую страницу</button>

    <script>
        function redirectToSecondPage() {
            const userInput = document.getElementById('userInput').value;
            // Кодирование значения для безопасной передачи в URL
            const encodedInput = encodeURIComponent(userInput);
            // Перенаправление на вторую страницу с передачей значения
            window.location.href = `second_page.html?input=${encodedInput}`;
        }
    </script>
</body>
</html>
```

### 2. **Вторая страница (second_page.html)**
```html
<!DOCTYPE html>
<html lang="en">
