Below is a basic implementation of the classic Snake game using HTML, CSS, and JavaScript. This code is designed to be simple and easy to understand, with a focus on security best practices such as avoiding inline scripts, sanitizing inputs (though not applicable here), and using modern JavaScript features.

### HTML (index.html)
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Secure Snake Game</title>
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <h1>Secure Snake Game</h1>
    <canvas id="gameCanvas" width="400" height="400"></canvas>
    <script src="script.js" defer></script>
</body>
</html>
```

### CSS (styles.css)
```css
body {
    display: flex;
    flex-direction: column;
    align-items: center;
    font-family: Arial, sans-serif;
    background-color: #f0f0f0;
}

canvas {
    border: 2px solid #333;
    background-color: #000;
}

h1 {
    margin-bottom: 20px;
}
```

### JavaScript (script.js)
```javascript
// Constants
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
const gridSize = 20;
const tileCount = canvas.width / gridSize;

// Game variables
let snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let score = 0;
let gameSpeed = 100;
let gameInterval;

// Securely handle user input
window.addEventListener('keydown', (e) => {
    const keyMap = {
        ArrowUp: { x: 0, y: -1 },
        ArrowDown: { x: 0, y: 1 },
        ArrowLeft: { x: -1, y: 0 },
        ArrowRight: { x: 1, y: 0 }
    };

    const newDirection = keyMap[e.key];
    if (newDirection && (newDirection.x !== -direction.x || newDirection.y !== -direction.y)) {
        direction = newDirection;
    }
});

// Game functions
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw snake
    ctx.fillStyle = 'lime';
    snake.forEach(segment => {
        ctx.fillRect(segment.x * gridSize, segment.y * gridSize, gridSize, gridSize);
    });

    // Draw food
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x * gridSize, food.y * gridSize, gridSize, gridSize);
}

function move() {
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Check collision with walls
    if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount) {
        resetGame();
        return;
    }

    // Check collision with self
    if (snake.some(segment => segment.x === head.x && segment.y === head.y)) {
        resetGame();
        return;
    }

    // Check collision with food
    if (head.x === food.x && head.y === food.y) {
        score++;
        placeFood();
    } else {
        snake.pop();
    }

    snake.unshift(head);
    draw();
}

function placeFood() {
    food = {
        x: Math.floor(Math.random() * tileCount),
        y: Math.floor(Math.random() * tileCount)
    };

    // Ensure food doesn't spawn on the snake
    if (snake.some(segment => segment.x === food.x && segment.y === food.y)) {
        placeFood();
    }
}

function resetGame() {
    clearInterval(gameInterval);
    snake = [{ x: 10, y: 10 }];
    direction = { x: 0, y: 0 };
    score = 0;
    placeFood();
    gameInterval = setInterval(move, gameSpeed);
}

// Start the game
placeFood();
gameInterval = setInterval(move, gameSpeed);
```

### Security Considerations
1. **Input Sanitization**: Although this game doesn't accept user input beyond arrow keys, the key event listener ensures only valid directions are accepted.
2. **No Inline Scripts**: JavaScript is loaded externally with the `defer` attribute to ensure it executes after the DOM is fully loaded.
3. **Secure Defaults**: The game starts with a secure default state, and resets properly on game over.
4. **No External Dependencies**: The game is self-contained and doesn't rely on external libraries or APIs, reducing potential attack vectors.

This code provides a basic, secure implementation of the Snake game. You can expand it further with features like high scores, levels, or additional security measures as needed.

