Below is a declarative and secure implementation of the requested functionality using a **Lightning Web Component (LWC)** in Salesforce. This solution includes a button that opens a modal popup, allows attaching a document, and associates it with multiple records. The code follows security best practices, including proper error handling and user permissions.

---

### **1. Lightning Web Component (LWC) Code**

**File: `documentAttachmentModal.js` (JavaScript Controller)**

```javascript
import { LightningElement, api, track } from 'lwc';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';
import createContentDocument from '@salesforce/apex/DocumentHandler.createContentDocument';
import attachDocumentToRecords from '@salesforce/apex/DocumentHandler.attachDocumentToRecords';

export default class DocumentAttachmentModal extends LightningElement {
    @api recordIds; // List of record IDs to attach the document to
    @track isModalOpen = false;
    fileData;

    // Open modal
    openModal() {
        this.isModalOpen = true;
    }

    // Close modal
    closeModal() {
        this.isModalOpen = false;
    }

    // Handle file selection
    handleFileChange(event) {
        const file = event.target.files[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = () => {
                this.fileData = {
                    filename: file.name,
                    base64: reader.result.split(',')[1]
                };
            };
            reader.readAsDataURL(file);
        }
    }

    // Submit file and attach to records
    async handleSubmit() {
        if (!this.fileData) {
            this.showToast('Error', 'Please select a file to upload.', 'error');
            return;
        }

        try {
            // Step 1: Upload document
            const documentId = await createContentDocument({
                fileData: this.fileData
            });

            // Step 2: Attach document to records
            await attachDocumentToRecords({
                documentId: documentId,
                recordIds: this.recordIds
            });

            this.showToast('Success', 'Document attached successfully!', 'success');
            this.closeModal();
        } catch (error) {
            this.showToast('Error', error.body.message, 'error');
        }
    }

    // Show toast notification
    showToast(title, message, variant) {
        const event = new ShowToastEvent({ title, message, variant });
        this.dispatchEvent(event);
    }
}
```

