document.addEventListener('DOMContentLoaded', () => {
    const searchInput = document.getElementById('searchInput');
    const searchButton = document.getElementById('searchButton');
    const resultsDiv = document.getElementById('results');

    searchButton.addEventListener('click', () => {
        const query = searchInput.value.trim();
        if (query) {
            // Simulação de uma busca (pode ser substituída por uma chamada API)
            const simulatedResults = [
                `Resultado 1 para: ${query}`,
                `Resultado 2 para: ${query}`,
                `Resultado 3 para: ${query}`
            ];

            // Exibir resultados
            resultsDiv.innerHTML = simulatedResults.map(result => `<p>${result}</p>`).join('');
        } else {
            resultsDiv.innerHTML = '<p>Por favor, digite algo para buscar.</p>';
        }
    });

    // Permitir busca ao pressionar Enter
