            });
        });
        console.groupEnd();

        // Check for insecure elements (HTTP resources on HTTPS pages)
        console.group('Insecure Resources (Mixed Content)');
        const insecureElements = [];
        const checkElements = ['a', 'link', 'script', 'img', 'iframe'];
        checkElements.forEach(tag => {
            document.querySelectorAll(tag).forEach(element => {
                const url = element.href || element.src;
                if (url && window.location.protocol === 'https:' && url.startsWith('http:')) {
                    insecureElements.push(url);
                }
            });
