  const rateLimit = new Map();

  function isRateLimited(ip) {
    const now = Date.now();
    const entries = rateLimit.get(ip) || [];
    entries.push(now);
    rateLimit.set(ip, entries.filter(time => time > now - 1000)); // 1-second window
    return entries.length > 10; // Allow max 10 messages per second
  }

  conn.on("text", function (str) {
    const ip = conn.remoteAddress;
