from .app import app, db
from flask import jsonify , abort , make_response , request, url_for

class Questionnaire(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(64))
    questions = []
    def __init__(self, name):
        self.name = name

    def __repr__(self):
        return '<Questionnaire (%d) %s>' % (self.id, self.name)

    def to_json(self):
        return {
            'id': self.id,
            'name': self.name,
            'questions': [q.to_json()["url"] for q in self.questions],
            'url': url_for('get_questionnaire', id=self.id, _external=True)
        }

class Question(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    title = db.Column(db.String(120))
    questionType = db.Column(db.String(120))
    questionnaire_id = db.Column(db.Integer, db.ForeignKey('questionnaire.id'))
    questionnaire = db.relationship('Questionnaire', backref=db.backref('questions', lazy='dynamic'))

    def __init__(self, title, questionType, questionnaire_id):
        self.title = title
        self.questionType = questionType
        self.questionnaire_id = questionnaire_id

    __mappers_args__ = {
        'polymorphic_identity': 'question',
        "with_polymorphic": "*",
        'polymorphic_on': questionType
    }

    def to_json(self):
        return {
            'id': self.id,
            'title': self.title,
            'questionType': self.questionType,
            'questionnaire_id': self.questionnaire.id,
            'url': url_for('get_question', id=self.id, _external=True)
        }

class Simple_Question(Question):
    id = db.Column(db.Integer, db.ForeignKey('question.id'), primary_key=True)
    reponse = db.Column(db.String(120))
    def __init__(self, title, questionnaire_id, reponse):
        super().__init__(title, "Question simple", questionnaire_id)
        self.reponse = reponse

    __mappers_args__ = {
        'polymorphic_identity': 'simple',
        'with_polymorphic': '*'
    }

    def to_json(self):
        return {
            'id': self.id,
            'title': self.title,
            'questionType': self.questionType,
            'questionnaire_id': self.questionnaire.id,
            'reponse': self.reponse,
            'url': url_for('get_question', id=self.id, _external=True)
        }

class Multiple_Question(Question):
    id = db.Column(db.Integer, db.ForeignKey('question.id'), primary_key=True)
    proposition1 = db.Column(db.String(120))
    proposition2 = db.Column(db.String(120))
    reponse = db.Column(db.Integer)
    def __init__(self, title, questionnaire_id, proposition1, proposition2, reponse):
        super().__init__(title, "Question multiple", questionnaire_id)
        self.proposition1 = proposition1
        self.proposition2 = proposition2
        self.reponse = reponse

    __mappers_args__ = {
        'polymorphic_identity': 'multiple',
        'with_polymorphic': '*'
    }

    def to_json(self):
        return {
            'id': self.id,
            'title': self.title,
            'questionType': self.questionType,
            'questionnaire_id': self.questionnaire.id,
            'proposition1': self.proposition1,
            'proposition2': self.proposition2,
            'reponse': self.reponse,
            'url': url_for('get_question', id=self.id, _external=True)
        }

def get_questionnaires():
    return [q.to_json() for q in Questionnaire.query.all()]

def add_questionnaire(json):
    q = Questionnaire(json['name'])
    db.session.add(q)
    db.session.commit()
    return q.to_json()

def get_le_questionnaire(id):
    return Questionnaire.query.get(id).to_json()

def update_le_questionnaire(id):
    questionnaire = Questionnaire.query.get(id)
    questionnaire.name = request.json['name']
    db.session.commit()
    return questionnaire.to_json()

def delete_le_questionnaire(id):
    questionnaire = Questionnaire.query.get(id)
    db.session.delete(questionnaire)
    db.session.commit()
    return questionnaire.to_json()

def get_les_questions_questionnaire(id):
    return [q.to_json() for q in Questionnaire.query.get(id).questions]

def get_les_questions():
    return [q.to_json() for q in Question.query.all()]

def get_la_question(id):
    if Question.query.get(id) is None:
        abort(404)
    if Question.query.get(id).questionType == "simple":
        return Simple_Question.query.get(id).to_json()
    elif Question.query.get(id).questionType == "multiple":
        return Multiple_Question.query.get(id).to_json()

def add_la_question(json):
    q = Question(json['title'], json['questionType'], json['questionnaire_id'])
    db.session.add(q)
    if json['questionType'] == "simple":
        q = Simple_Question(json['title'], json['questionnaire_id'], json['reponse'])
        if not isinstance(json['reponse'], str):
            abort(400)
    elif json['questionType'] == "multiple":
        q = Multiple_Question(json['title'], json['questionnaire_id'], json['proposition1'], json['proposition2'], json['reponse'])
        if not isinstance(json['reponse'], int):
            abort(400)
        if not isinstance(json['proposition1'], str):
            abort(400)
        if not isinstance(json['proposition2'], str):
            abort(400)
    db.session.add(q)
    db.session.commit()
    return q.to_json()

def update_la_question(id):
    question = Question.query.get(id)
    question.title = request.json['title']
    question.questionType = request.json['questionType']
    question.questionnaire_id = request.json['questionnaire_id']
    if question.questionType == "simple":
        question = Simple_Question.query.get(id)
        question.reponse = request.json['reponse']
        if not isinstance(request.json['reponse'], str):
            abort(400)
        db.session.commit()
        return question.to_json()
    elif question.questionType == "multiple":
        question = Multiple_Question.query.get(id)
        question.reponse = int(request.json['reponse'])
        question.proposition1 = request.json['proposition1']
        question.proposition2 = request.json['proposition2']
        if not isinstance(request.json['reponse'], int):
            abort(400)
        if not isinstance(request.json['proposition1'], str):
            abort(400)
        if not isinstance(request.json['proposition2'], str):
            abort(400)
        db.session.commit()
        return question.to_json()
    db.session.commit()
    return question.to_json()

def delete_la_question(id):
    question = Question.query.get(id)
    if question.questionType == "simple":
        question_simple = Simple_Question.query.get(id)
        db.session.delete(question_simple)
        db.session.commit()
    elif question.questionType == "multiple":
        question_multiple = Multiple_Question.query.get(id)
        db.session.delete(question_multiple)
        db.session.commit()
    db.session.delete(question)
    db.session.commit()
    return question.to_json()

def get_liste_questions_simples():
    return [q.to_json() for q in Simple_Question.query.all()]

def get_liste_questions_multiples():
    return [q.to_json() for q in Multiple_Question.query.all()]

def get_liste_question_simple(id):
    return Simple_Question.query.get(id).to_json()

