```javascript
require("dotenv").config();
const config = require("config"); // Use `config` library for hierarchical config management
const express = require("express");
const http = require("http");
const cors = require("cors");
const helmet = require("helmet");
const rateLimit = require("express-rate-limit");
const methodOverride = require("method-override");
const createLogger = require("./src/core/Logger");
const LockManager = require("node-locksmith");
const MongoDBConnectionManager = require("./src/core/MongodbService");
const { validateEnvVariables } = require("./src/utils/validators");
const { redactSensitiveData } = require("./src/middleware/redactSensitiveData");
const { globalErrorHandler } = require("./src/middleware/errorHandler");

const logger = createLogger("medics-communication-server");
const app = express();
app.logger = logger;

// Validate environment variables
validateEnvVariables();

// Initialize termination event handlers
const lockManager = new LockManager({ lockFileName: "medics-communication-server.lock" });
lockManager.initializeTerminationHandlers();

// Middleware setup
const setupMiddleware = () => {
  app.use(cors({ origin: config.get("allowedOrigins") })); // Restrict CORS origins
  app.use(helmet({ contentSecurityPolicy: false })); // Customize Helmet
  app.use(rateLimit({ windowMs: 15 * 60 * 1000, max: 100 }));
  app.use(methodOverride("X-HTTP-Method-Override"));
  app.use(express.json());
  app.use(express.urlencoded({ extended: true }));
  app.use(redactSensitiveData); // Redact sensitive data from logs
};

// Logging middleware
app.use((req, res, next) => {
  const clientIp = req.headers["x-forwarded-for"] || req.connection.remoteAddress;
  logger.info({ method: req.method, url: req.url, clientIp }, "Processing request");
  next();
});

