  const router = PromiseRouter();
  for (const [route, controller] of Object.entries(routes)) {
    router.use(route, controller(app, route));
  }
  app.use(router);
};

// Initialize the application
const initializeApp = async () => {
  try {
    await lockManager.checkLock();
    await lockManager.createLock(Infinity, 3);

    const dbManager = new MongoDBConnectionManager(
      process.env.COMMUNICATION_SERVER_MONGODB_URL || config.get("mongodbURL"),
      logger
    );
    await dbManager.connectToDatabase();

    app.models = require("./src/models"); // Load models
    setupMiddleware();
    loadRoutes();

    // Graceful shutdown
    process.on("SIGTERM", () => {
      logger.info("Received SIGTERM. Shutting down gracefully.");
      process.exit(0);
    });

    const httpPort = process.env.COMMUNICATION_SERVER_SERVER_PORT || config.get("serverPort");
    http.createServer(app).listen(httpPort, () => {
      logger.info(`HTTP server is listening on port: ${httpPort}`);
    });
  } catch (error) {
    logger.error("Initialization error:", error);
    process.exit(1);
  }
};

// Global error handler
app.use(globalErrorHandler);

// Start the application
initializeApp();
```

