### **Struktur Proyek**
```
youtube-gallery/
│
├── public/
│   ├── index.html
│   └── styles.css
│
├── server.js
└── package.json
```

### **Langkah 1: Setup Proyek**
Pastikan Anda telah menginstal Node.js dan npm. Buat proyek baru dan instal dependensi yang diperlukan:

```bash
mkdir youtube-gallery
cd youtube-gallery
npm init -y
npm install express axios
```

### **Langkah 2: Buat Server (`server.js`)**
```javascript
const express = require('express');
const axios = require('axios');
const app = express();
const port = 3000;

const YOUTUBE_API_KEY = 'YOUR_YOUTUBE_API_KEY'; // Ganti dengan API Key YouTube Anda
const YOUTUBE_API_URL = 'https://www.googleapis.com/youtube/v3/search';

app.use(express.static('public'));

app.get('/videos', async (req, res) => {
    const { q = 'programming', pageToken = '' } = req.query;
    const params = {
        part: 'snippet',
        q,
        type: 'video',
        maxResults: 9, // 3 kolom x 3 baris
        key: YOUTUBE_API_KEY,
        pageToken,
    };

    try {
        const response = await axios.get(YOUTUBE_API_URL, { params });
        res.json(response.data);
    } catch (error) {
        res.status(500).json({ error: 'Failed to fetch videos' });
    }
});

app.listen(port, () => {
    console.log(`Server running on http://localhost:${port}`);
});
```

### **Langkah 3: Buat Halaman HTML (`public/index.html`)**
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>YouTube Video Gallery</title>
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.1.3/dist/css/bootstrap.min.css" rel="stylesheet">
    <link rel="stylesheet" href="styles.css">
</head>
<body>
    <div class="container mt-5">
        <h1 class="text-center mb-4">YouTube Video Gallery</h1>
        <div class="row" id="video-container"></div>
        <div class="text-center mt-4">
            <button class="btn btn-primary" id="prev-page" disabled>Previous</button>
            <button class="btn btn-primary" id="next-page">Next</button>
        </div>
    </div>

    <script src="https://cdn.jsdelivr.net/npm/axios/dist/axios.min.js"></script>
    <script>
        let nextPageToken = '';
        let prevPageToken = '';

        async function fetchVideos(query = 'programming', pageToken = '') {
            const response = await axios.get('/videos', {
                params: { q: query, pageToken }
            });
            return response.data;
        }

        function renderVideos(videos) {
            const container = document.getElementById('video-container');
            container.innerHTML = '';
            videos.forEach(video => {
                const col = document.createElement('div');
                col.className = 'col-md-4 mb-4';
                col.innerHTML = `
                    <div class="card">
                        <img src="${video.snippet.thumbnails.medium.url}" class="card-img-top" alt="${video.snippet.title}">
                        <div class="card-body">
                            <h5 class="card-title">${video.snippet.title}</h5>
                            <a href="https://www.youtube.com/watch?v=${video.id.videoId}" target="_blank" class="btn btn-danger">Watch</a>
                        </div>
                    </div>
                `;
                container.appendChild(col);
            });
        }

        async function loadVideos(pageToken = '') {
            const data = await fetchVideos('programming', pageToken);
            nextPageToken = data.nextPageToken || '';
            prevPageToken = data.prevPageToken || '';
            document.getElementById('next-page').disabled = !nextPageToken;
            document.getElementById('prev-page').disabled = !prevPageToken;
            renderVideos(data.items);
        }

        document.getElementById('next-page').addEventListener('click', () => loadVideos(nextPageToken));
        document.getElementById('prev-page').addEventListener('click', () => loadVideos(prevPageToken));

        loadVideos();
    </script>
</body>
</html>
```

