        <h1>Conversor YouTube para MP3</h1>
        <input type="text" id="youtubeUrl" placeholder="Cole o link do YouTube aqui" required>
        <button onclick="convertMp3()">Converter e Baixar</button>
        <div id="status"></div>
    </div>

    <script>
        async function convertMp3() {
            const url = document.getElementById('youtubeUrl').value;
            const statusDiv = document.getElementById('status');

            if (!url) {
                statusDiv.className = 'error';
                statusDiv.textContent = 'Por favor, insira um link válido do YouTube.';
                return;
            }

            statusDiv.className = '';
            statusDiv.textContent = 'Processando...';

            try {
                const response = await fetch('/convert', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json',
                    },
                    body: JSON.stringify({ url }),
                });

                if (!response.ok) {
                    throw new Error('Erro ao converter o vídeo.');
                }

                const blob = await response.blob();
                const downloadUrl = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = downloadUrl;
                a.download = 'audio.mp3';
                document.body.appendChild(a);
                a.click();
                window.URL.revokeObjectURL(downloadUrl);
                statusDiv.textContent = 'Download concluído!';
            } catch (error) {
                statusDiv.className = 'error';
                statusDiv.textContent = 'Erro: ' + error.message;
            }
        }
    </script>
