### **Backend (Node.js + Express)**

Instale as dependências necessárias:

```bash
npm install express ytdl-core fluent-ffmpeg
```

Crie um arquivo `server.js`:

```javascript
const express = require('express');
const ytdl = require('ytdl-core');
const ffmpeg = require('fluent-ffmpeg');
const path = require('path');
const app = express();
const port = 3000;

app.use(express.json());

app.post('/convert', async (req, res) => {
    const url = req.body.url;

    if (!ytdl.validateURL(url)) {
        return res.status(400).send('URL do YouTube inválida.');
    }

    try {
        const audio = ytdl(url, { quality: 'highestaudio' });
        const ffmpegProcess = ffmpeg(audio)
            .audioBitrate(192)
            .format('mp3')
            .on('error', (err) => {
                console.error('Erro ao converter:', err);
                res.status(500).send('Erro ao converter o vídeo.');
            })
            .on('end', () => {
                console.log('Conversão concluída.');
            });

        ffmpegProcess.pipe(res, { end: true });
    } catch (error) {
        console.error('Erro:', error);
        res.status(500).send('Erro interno do servidor.');
    }
});

app.use(express.static(path.join(__dirname, 'public')));

app.listen(port, () => {
    console.log(`Servidor rodando em http://localhost:${port}`);
});
```

---

### **Como Executar**

1. Coloque o arquivo HTML na pasta `public` do seu projeto Node.js.
2. Inicie o servidor Node.js:
   ```bash
   node server.js
   ```
3. Acesse `http://localhost:3000` no navegador.

